const T = [{"n":1,"lab":"01.1","blk":"b","cls":5,"topic":"Обыкновенные дроби","err":"Складывает знаменатели","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>6</span></span> + <span class=\"fr\"><span>2</span><span>6</span></span></li><li><span class=\"fr\"><span>2</span><span>7</span></span> + <span class=\"fr\"><span>3</span><span>7</span></span></li><li><span class=\"fr\"><span>5</span><span>8</span></span> − <span class=\"fr\"><span>2</span><span>8</span></span></li></ol>","subs":[{"k":"e","v":"1/2","alt":["3/6"],"show":"3/6 = 1/2"},{"k":"e","v":"5/7","var":[],"show":"5/7"},{"k":"e","v":"3/8","var":[],"show":"3/8"}],"sym":"","h":["Подумай: «Сколько пятых получится, если к одной пятой добавить две?»","Если звучит «три десятых», покажи полоски одинаковой длины. Считаем пятые доли: 1 пятая + 2 пятые = 3 пятые."]},{"n":2,"lab":"09.1","blk":"b","cls":5,"topic":"Текстовые задачи","err":"Принимает «в три раза больше» за «на три больше»","type":"sub","q":"<p>Запиши выражение.</p><ol class=\"subq\"><li>В 4 раза больше x</li><li>На 4 больше x</li><li>В 2 раза больше x</li></ol>","subs":[{"k":"e","v":"4x","var":[],"show":"4x"},{"k":"e","v":"x + 4","var":[],"show":"x + 4"},{"k":"e","v":"2x","var":[],"show":"2x"}],"sym":"","h":["Подумай: «У Лены x наклеек, у Оли в 3 раза больше. Сколько у Оли?»","Изобрази количество наклеек Лены одной полоской. У Оли три такие полоски: x + x + x = 3x. Запись x + 3 означает, что наклеек на три больше."]},{"n":3,"lab":"09.2","blk":"b","cls":5,"topic":"Текстовые задачи","err":"Встречное движение: вычитает скорости","type":"sub","q":"<p>Найди скорость сближения при движении навстречу.</p><ol class=\"subq\"><li>8 и 13 км/ч</li><li>14 и 16 км/ч</li><li>10 и 12 км/ч</li></ol>","subs":[{"k":"e","v":"21","var":[],"show":"21 км/ч"},{"k":"e","v":"30","var":[],"show":"30 км/ч"},{"k":"e","v":"22","var":[],"show":"22 км/ч"}],"sym":"","h":["Подумай: «Едут навстречу: 12 и 15 км/ч. Какова скорость сближения?»","Что происходит за час: первый проезжает 12 км, второй 15 км. Расстояние между ними сокращается на 27 км за час. Такую скорость сближения получаем до встречи."]},{"n":4,"lab":"11.1","blk":"b","cls":5,"topic":"Десятичные дроби","err":"При сложении выравнивает по последней цифре","type":"sub","q":"<p>Сложи столбиком.</p><ol class=\"subq\"><li>3,2 + 0,45</li><li>6,4 + 1,08</li><li>0,9 + 2,16</li></ol>","subs":[{"k":"e","v":"3,65","var":[],"show":"3,65"},{"k":"e","v":"7,48","var":[],"show":"7,48"},{"k":"e","v":"3,06","var":[],"show":"3,06"}],"sym":"","h":["Подумай: «Как записать столбиком 2,7 + 0,35? Где будет запятая?»","Пишем единицы под единицами, десятые под десятыми. Запятые оказываются друг под другом. Дописываем ноль: 2,7 = 2,70. Теперь складываем по разрядам."]},{"n":5,"lab":"11.2","blk":"b","cls":5,"topic":"Десятичные дроби","err":"При умножении ставит запятую наугад","type":"sub","q":"<p>Найди произведение.</p><ol class=\"subq\"><li>0,6 · 0,7</li><li>1,2 · 0,4</li><li>0,5 · 0,08</li></ol>","subs":[{"k":"e","v":"0,42","var":[],"show":"0,42"},{"k":"e","v":"0,48","var":[],"show":"0,48"},{"k":"e","v":"0,04","var":[],"show":"0,04"}],"sym":"","h":["Подумай: «Чему равно 0,4 · 0,3? Сколько цифр после запятой в ответе?»","Четыре десятых умножаем на три десятых. Получаем двенадцать сотых. Отсчитываем справа столько цифр, сколько знаков после запятой в обоих множителях вместе."]},{"n":6,"lab":"14.1","blk":"b","cls":5,"topic":"Смешанные числа","err":"Складывает целую часть и числитель","type":"sub","q":"<p>Запиши неправильной дробью.</p><ol class=\"subq\"><li>1 <span class=\"fr\"><span>2</span><span>3</span></span></li><li>2 <span class=\"fr\"><span>1</span><span>4</span></span></li><li>3 <span class=\"fr\"><span>2</span><span>7</span></span></li></ol>","subs":[{"k":"e","v":"5/3","var":[],"show":"5/3"},{"k":"e","v":"9/4","var":[],"show":"9/4"},{"k":"e","v":"23/7","var":[],"show":"23/7"}],"sym":"","h":["Подумай: «Сколько пятых в числе 2 <span class=\"fr\"><span>3</span><span>5</span></span>?»","В каждой целой единице пять пятых. В двух целых их десять. Прибавляем ещё три пятых и получаем тринадцать пятых."],"flag":{"impr":true}},{"n":7,"lab":"14.2","blk":"b","cls":5,"topic":"Смешанные числа","err":"Вычитает дробные части в обратном порядке","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>4 <span class=\"fr\"><span>1</span><span>7</span></span> − 2 <span class=\"fr\"><span>5</span><span>7</span></span></li><li>5 <span class=\"fr\"><span>1</span><span>6</span></span> − 2 <span class=\"fr\"><span>5</span><span>6</span></span></li><li>6 <span class=\"fr\"><span>2</span><span>9</span></span> − 3 <span class=\"fr\"><span>7</span><span>9</span></span></li></ol>","subs":[{"k":"e","v":"1 3/7","var":[],"show":"1 3/7"},{"k":"e","v":"2 1/3","var":[],"show":"2 1/3"},{"k":"e","v":"2 4/9","var":[],"show":"2 4/9"}],"sym":"","h":["Подумай: «Как из 3 <span class=\"fr\"><span>1</span><span>5</span></span> вычесть 1 <span class=\"fr\"><span>4</span><span>5</span></span>, если одной пятой мало?»","Заменяем одну целую единицу пятью пятыми. Тогда 3 целых и одна пятая превращаются в 2 целых и шесть пятых. Теперь можно вычесть четыре пятых."]},{"n":8,"lab":"16.1","blk":"b","cls":5,"topic":"Перевод единиц","err":"Переводит минуты в часы как сотые доли","type":"sub","q":"<p>Вырази время в часах.</p><ol class=\"subq\"><li>2 ч 15 мин</li><li>45 мин</li><li>3 ч 6 мин</li></ol>","subs":[{"k":"e","v":"2,25","var":[],"show":"2,25 ч"},{"k":"e","v":"0,75","var":[],"show":"0,75 ч"},{"k":"e","v":"3,1","var":[],"show":"3,1 ч"}],"sym":"","h":["Подумай: «Сколько часов составляют 1 ч 30 мин? Это 1,30 ч?»","В одном часе 60 минут. Чтобы выразить минуты в часах, делим их число на 60. Тридцать минут составляют половину часа, поэтому 1 ч 30 мин = 1,5 ч."]},{"n":9,"lab":"16.2","blk":"b","cls":5,"topic":"Перевод единиц","err":"Переводит площадь по правилу для длины","type":"sub","q":"<p>Вырази площадь в см², а в третьем задании в дм².</p><ol class=\"subq\"><li>3 дм²</li><li>5 м²</li><li>2400 см² → в дм²</li></ol>","subs":[{"k":"e","v":"300","var":[],"show":"300 см²"},{"k":"e","v":"50 000","var":[],"show":"50 000 см²"},{"k":"e","v":"24","var":[],"show":"24 дм²"}],"sym":"²","h":["Подумай: «В одном дециметре 10 сантиметров. А в одном дм²?»","Представь квадрат со стороной 1 дм, или 10 см. В каждом ряду 10 квадратов по 1 см². Рядов тоже 10. Всего получаем 10 · 10 = 100 квадратных сантиметров."]},{"n":10,"lab":"16.3","blk":"b","cls":5,"topic":"Формулы движения","err":"Делит скорость на время при поиске пути","type":"sub","q":"<p>Найди пройденный путь.</p><ol class=\"subq\"><li>50 км/ч, 2 ч</li><li>72 км/ч, 0,5 ч</li><li>12 км/ч, 1,5 ч</li></ol>","subs":[{"k":"e","v":"100","var":[],"show":"100 км"},{"k":"e","v":"36","var":[],"show":"36 км"},{"k":"e","v":"18","var":[],"show":"18 км"}],"sym":"","h":["Подумай: «Скорость 60 км/ч. Сколько километров проедут за 3 часа?»","За каждый час проезжают 60 км. За три часа это 60 + 60 + 60 км. При постоянной скорости путь равен произведению скорости и времени: s = v · t."]},{"n":11,"lab":"16.4","blk":"b","cls":5,"topic":"Формулы движения","err":"Делит скорость на путь при поиске времени","type":"sub","q":"<p>Найди время движения.</p><ol class=\"subq\"><li>120 км, 40 км/ч</li><li>90 км, 60 км/ч</li><li>24 км, 48 км/ч</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3 ч"},{"k":"e","v":"1,5","var":[],"show":"1,5 ч"},{"k":"e","v":"0,5","var":[],"show":"0,5 ч"}],"sym":"","h":["Подумай: «Путь 150 км, скорость 50 км/ч. Сколько часов займёт поездка?»","За час проезжают 50 км. Чтобы узнать число часов, считаем, сколько раз по 50 км помещается в 150 км. Делим путь на скорость: t = s : v."]},{"n":12,"lab":"17.1","blk":"b","cls":5,"topic":"Деление столбиком","err":"Пропускает ноль в частном","type":"sub","q":"<p>Раздели столбиком.</p><ol class=\"subq\"><li>612 : 6</li><li>428 : 4</li><li>735 : 7</li></ol>","subs":[{"k":"e","v":"102","var":[],"show":"102"},{"k":"e","v":"107","var":[],"show":"107"},{"k":"e","v":"105","var":[],"show":"105"}],"sym":"","h":["Подумай: «Раздели 816 на 8. Что записать в частном после цифры 1?»","После первой цифры частного сносим 1. Если разделить 1 десяток на 8, выйдет 0 полных десятков. Пишем 0. Сносим 6. Теперь делим 16 единиц на 8 и пишем 2."]},{"n":13,"lab":"17.2","blk":"b","cls":5,"topic":"Деление столбиком","err":"Допускает остаток не меньше делителя","type":"sub","q":"<p>Найди частное и остаток.</p><ol class=\"subq\"><li>29 : 4</li><li>46 : 7</li><li>58 : 9</li></ol>","subs":[{"k":"t","v":["7 (ост. 1)"],"show":"7 (ост. 1)"},{"k":"t","v":["6 (ост. 4)"],"show":"6 (ост. 4)"},{"k":"t","v":["6 (ост. 4)"],"show":"6 (ост. 4)"}],"sym":"","h":["Подумай: «Верна ли запись 37 : 6 = 5 (ост. 7)? Почему?»","Из остатка 7 можно взять ещё одну шестёрку. Тогда частное увеличится на 1, а остаток станет равен 1. Остаток всегда меньше делителя. Проверяем: 6 · 6 + 1 = 37."]},{"n":14,"lab":"17.5","blk":"b","cls":5,"topic":"Объём","err":"Находит площадь основания вместо объёма","type":"sub","q":"<p>Найди объём прямоугольного параллелепипеда.</p><ol class=\"subq\"><li>5 × 2 × 3 см</li><li>4 × 4 × 2 см</li><li>6 × 3 × 2 см</li></ol>","subs":[{"k":"e","v":"30","var":[],"show":"30 см³"},{"k":"e","v":"32","var":[],"show":"32 см³"},{"k":"e","v":"36","var":[],"show":"36 см³"}],"sym":"³","h":["Подумай: «Размеры коробки 4 см, 3 см и 2 см. Как найти объём?»","В нижнем слое 4 · 3 = 12 кубиков объёмом 1 см³ каждый. При высоте 2 см таких слоёв два. Умножаем число кубиков в одном слое на число слоёв."]},{"n":15,"lab":"17.6","blk":"b","cls":5,"topic":"Объём","err":"Переводит объём по правилу для длины","type":"sub","q":"<p>Переведи единицы объёма.</p><ol class=\"subq\"><li>3 дм³ → в см³</li><li>0,5 дм³ → в см³</li><li>7200 см³ → в дм³</li></ol>","subs":[{"k":"e","v":"3000","var":[],"show":"3000 см³"},{"k":"e","v":"500","var":[],"show":"500 см³"},{"k":"e","v":"7,2","var":[],"show":"7,2 дм³"}],"sym":"³","h":["Подумай: «В одном дециметре 10 сантиметров. Сколько см³ в 1 дм³?»","Куб со стороной 1 дм складываем из кубиков по 1 см³. В каждом ряду 10 кубиков, в слое 10 рядов. Всего 10 слоёв. Получаем 10 · 10 · 10 = 1000 кубиков."]},{"n":16,"lab":"18.1","blk":"b","cls":5,"topic":"Порядок действий","err":"Считает слева направо без учёта действий","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>20 − 3 · 4</li><li>7 + 18 : 3</li><li>(7 + 18) : 5</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"13","var":[],"show":"13"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Что выполнить первым в выражении 18 − 4 · 3?»","Сначала выполняем умножение: 4 · 3 = 12. Затем вычитаем это произведение из 18. Если нужно начать с вычитания, его выделяют скобками."]},{"n":17,"lab":"18.2","blk":"b","cls":5,"topic":"Порядок действий","err":"Всегда выполняет умножение раньше деления","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>36 : 9 · 3</li><li>40 : 5 : 2</li><li>18 : 3 · 4</li></ol>","subs":[{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"24","var":[],"show":"24"}],"sym":"","h":["Подумай: «В выражении 24 : 6 · 2 что делаем первым?»","У деления и умножения одинаковый приоритет. Если скобок нет, выполняем их по порядку слева направо. Сначала 24 : 6 = 4. Затем 4 · 2 = 8."]},{"n":18,"lab":"19.1","blk":"b","cls":5,"topic":"Округление десятичных дробей","err":"Смотрит на последнюю цифру при округлении","type":"sub","q":"<p>Округли до десятых.</p><ol class=\"subq\"><li>2,341</li><li>5,678</li><li>8,449</li></ol>","subs":[{"k":"e","v":"2,3","var":[],"show":"2,3"},{"k":"e","v":"5,7","var":[],"show":"5,7"},{"k":"e","v":"8,4","var":[],"show":"8,4"}],"sym":"","h":["Подумай: «Округли 4,261 до десятых. На какую цифру нужно смотреть?»","Оставляем цифру десятых: это 2. Для решения смотрим на первую отбрасываемую цифру: это 6 в разряде сотых. Шесть больше четырёх, поэтому увеличиваем 2 до 3."]},{"n":19,"lab":"19.2","blk":"b","cls":5,"topic":"Округление десятичных дробей","err":"Теряет перенос при округлении через девятку","type":"sub","q":"<p>Округли до десятых.</p><ol class=\"subq\"><li>4,98</li><li>7,95</li><li>9,99</li></ol>","subs":[{"k":"e","v":"5,0","var":[],"show":"5,0"},{"k":"e","v":"8,0","var":[],"show":"8,0"},{"k":"e","v":"10,0","var":[],"show":"10,0"}],"sym":"","h":["Подумай: «Округли 2,96 до десятых. Что получится, если прибавить одну десятую?»","В числе 2,96 оставляем десятые и смотрим на сотые: это 6. Увеличиваем 2,9 на одну десятую: 2,9 + 0,1 = 3,0. Десять десятых образуют одну целую."]},{"n":20,"lab":"20.3","blk":"b","cls":5,"topic":"Сравнение обыкновенных дробей","err":"Выбирает дробь с большим знаменателем","type":"sub","q":"<p>Поставь знак сравнения.</p><ol class=\"subq\"><li><span class=\"fr\"><span>2</span><span>3</span></span> и <span class=\"fr\"><span>2</span><span>7</span></span></li><li><span class=\"fr\"><span>4</span><span>9</span></span> и <span class=\"fr\"><span>4</span><span>5</span></span></li><li><span class=\"fr\"><span>5</span><span>6</span></span> и <span class=\"fr\"><span>5</span><span>8</span></span></li></ol>","subs":[{"k":"t","v":["2/3 > 2/7",">"],"show":"2/3 > 2/7"},{"k":"t","v":["4/9 < 4/5","<"],"show":"4/9 < 4/5"},{"k":"t","v":["5/6 > 5/8",">"],"show":"5/6 > 5/8"}],"sym":"","h":["Подумай: «Что больше: <span class=\"fr\"><span>3</span><span>5</span></span> или <span class=\"fr\"><span>3</span><span>8</span></span>? Представь одинаковые шоколадки».","В обоих случаях берём по три кусочка. Пятые доли крупнее восьмых: первую шоколадку разделили на меньшее число равных частей. Поэтому три пятых больше трёх восьмых."]},{"n":21,"lab":"21.1","blk":"b","cls":5,"topic":"Деление десятичных дробей","err":"Переносит запятую только в делителе","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>2,4 : 0,6</li><li>4,2 : 0,07</li><li>0,81 : 0,09</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"60","var":[],"show":"60"},{"k":"e","v":"9","var":[],"show":"9"}],"sym":"","h":["Подумай: «Как заменить делитель 0,4 целым числом в примере 3,6 : 0,4?»","Умножаем делимое и делитель на 10. Частное сохраняется. Получаем 36 : 4 = 9. Если умножить только делитель, ответ станет в 10 раз меньше."]},{"n":22,"lab":"21.2","blk":"b","cls":5,"topic":"Деление десятичных дробей","err":"Ждёт, что при делении число уменьшится","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>3 : 0,5</li><li>2 : 0,25</li><li>1 : 0,2</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Будет ли 2 : 0,5 больше двух? Сколько половинок в двух целых?»","В одном целом две половинки, а в двух целых четыре. Поэтому 2 : 0,5 = 4. При делении положительного числа на положительную дробь меньше единицы частное растёт."]},{"n":23,"lab":"23.1","blk":"b","cls":5,"topic":"Сравнение десятичных дробей","err":"Сравнивает дробные части как целые числа","type":"sub","q":"<p>Поставь знак сравнения.</p><ol class=\"subq\"><li>3,4 и 3,35</li><li>0,8 и 0,79</li><li>5,2 и 5,25</li></ol>","subs":[{"k":"t","v":["3,4 > 3,35",">"],"show":"3,4 > 3,35"},{"k":"t","v":["0,8 > 0,79",">"],"show":"0,8 > 0,79"},{"k":"t","v":["5,2 < 5,25","<"],"show":"5,2 < 5,25"}],"sym":"","h":["Подумай: «Что больше: 2,7 или 2,65? Как сравнить по разрядам?»","Целые части одинаковые. В первом числе семь десятых, во втором шесть десятых. Семь десятых больше шести, поэтому 2,7 &gt; 2,65. Для проверки можно записать 2,70."]},{"n":24,"lab":"23.2","blk":"b","cls":5,"topic":"Сравнение десятичных дробей","err":"Считает, что ноль в конце меняет число","type":"sub","q":"<p>Проверь, равны ли числа.</p><ol class=\"subq\"><li>0,6 и 0,60</li><li>1,07 и 1,70</li><li>2,040 и 2,04</li></ol>","subs":[{"k":"t","v":["Равны"],"show":"Равны"},{"k":"t","v":["Не равны"],"show":"Не равны"},{"k":"t","v":["Равны"],"show":"Равны"}],"sym":"","h":["Подумай: «Равны ли 0,5 и 0,50? Сколько сотых в пяти десятых?»","Каждая десятая равна десяти сотым. Пять десятых составляют пятьдесят сотых. Ноль в конце дробной части можно дописать или убрать: значение числа сохраняется."]},{"n":25,"lab":"25.3","blk":"b","cls":5,"topic":"Дробь от числа и число по его дроби","err":"Находит одну долю вместо нескольких","type":"sub","q":"<p>Найди дробь от числа.</p><ol class=\"subq\"><li><span class=\"fr\"><span>2</span><span>3</span></span> от 18</li><li><span class=\"fr\"><span>3</span><span>8</span></span> от 40</li><li><span class=\"fr\"><span>4</span><span>7</span></span> от 35</li></ol>","subs":[{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"20","var":[],"show":"20"}],"sym":"","h":["Подумай: «В коробке 20 карандашей. Сколько составляют <span class=\"fr\"><span>3</span><span>5</span></span> от всех?»","Делим 20 на 5 равных частей. В каждой по 4 карандаша. В числителе стоит 3, поэтому берём три такие части. Получаем 4 · 3 = 12 карандашей."]},{"n":26,"lab":"25.5","blk":"b","cls":5,"topic":"Периметр и площадь","err":"Умножает стороны, когда нужен периметр","type":"sub","q":"<p>Найди периметр прямоугольника.</p><ol class=\"subq\"><li>5 см и 3 см</li><li>7 см и 2 см</li><li>8 см и 5 см</li></ol>","subs":[{"k":"e","v":"16","var":[],"show":"16 см"},{"k":"e","v":"18","var":[],"show":"18 см"},{"k":"e","v":"26","var":[],"show":"26 см"}],"sym":"","h":["Подумай: «У прямоугольника стороны 6 см и 4 см. Какова длина его контура?»","Периметр — длина всего контура. У прямоугольника две стороны по 6 см и две по 4 см. Складываем все четыре длины: 6 + 4 + 6 + 4 = 20 см."]},{"n":27,"lab":"25.6","blk":"b","cls":5,"topic":"Периметр и площадь","err":"Считает, что равные периметры дают равные площади","type":"sub","q":"<p>Найди площади обоих прямоугольников в клетках.</p><ol class=\"subq\"><li>5 × 3 и 6 × 2</li><li>4 × 4 и 7 × 1</li><li>8 × 2 и 6 × 4</li></ol>","subs":[{"k":"set","v":["15","12"],"show":"15 и 12"},{"k":"set","v":["16","7"],"show":"16 и 7"},{"k":"set","v":["16","24"],"show":"16 и 24"}],"sym":"","h":["Подумай: «У прямоугольников 6 × 4 и 7 × 3 поровну ли квадратных клеток?»","У обоих прямоугольников периметр равен 20. Площади считаем отдельно. В первом 6 · 4 = 24 клетки, во втором 7 · 3 = 21 клетка."]},{"n":28,"lab":"28.1","blk":"b","cls":5,"topic":"Задачи с остатком","err":"Округляет число машин вниз","type":"sub","q":"<p>Найди число машин.</p><ol class=\"subq\"><li>17 человек, по 4</li><li>33 человека, по 8</li><li>24 человека, по 6</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"","h":["Подумай: «28 учеников. В машине 6 мест для учеников. Сколько машин нужно?»","Делим 28 на 6: получаем 4 полные машины и ещё 4 ученика. Для оставшихся учеников нужна пятая машина. Проверяем: в четырёх машинах только 24 места."]},{"n":29,"lab":"28.2","blk":"b","cls":5,"topic":"Задачи с остатком","err":"Считает неполную коробку полной","type":"sub","q":"<p>Найди число полных коробок.</p><ol class=\"subq\"><li>23 яблока, по 5</li><li>38 яблок, по 9</li><li>42 яблока, по 7</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"6","var":[],"show":"6"}],"sym":"","h":["Подумай: «Есть 29 яблок. Сколько полных коробок по 6 можно собрать?»","Шесть яблок заполняют одну коробку. Делим с остатком. Из 29 яблок получаются 4 полные коробки и 5 лишних яблок. Для ещё одной полной коробки не хватает одного яблока."]},{"n":30,"lab":"30.1","blk":"b","cls":5,"topic":"Умножение столбиком","err":"Записывает десятки в разряд единиц","type":"sub","q":"<p>Умножь столбиком.</p><ol class=\"subq\"><li>23 · 14</li><li>32 · 21</li><li>45 · 12</li></ol>","subs":[{"k":"e","v":"322","var":[],"show":"322"},{"k":"e","v":"672","var":[],"show":"672"},{"k":"e","v":"540","var":[],"show":"540"}],"sym":"","h":["Подумай: «При умножении 24 на 13 чему равно второе произведение?»","Цифра 1 в числе 13 обозначает один десяток. Поэтому второе произведение равно 24 · 10 = 240. В столбике сдвигаем его на один разряд влево."]},{"n":31,"lab":"30.2","blk":"b","cls":5,"topic":"Умножение столбиком","err":"Пропускает разряд из-за нуля","type":"sub","q":"<p>Умножь столбиком.</p><ol class=\"subq\"><li>12 · 203</li><li>34 · 102</li><li>25 · 406</li></ol>","subs":[{"k":"e","v":"2436","var":[],"show":"2436"},{"k":"e","v":"3468","var":[],"show":"3468"},{"k":"e","v":"10 150","var":[],"show":"10 150"}],"sym":"","h":["Подумай: «Реши 21 · 304. В какой разряд попадёт произведение на 3?»","Число 304 состоит из 3 сотен и 4 единиц. Умножаем 21 на 4 и на 300. Произведение на 300 записываем со сдвигом на два разряда."]},{"n":32,"lab":"33.1","blk":"b","cls":5,"topic":"Десятичная запись обыкновенной дроби","err":"Пропускает нули после запятой","type":"sub","q":"<p>Запиши десятичной дробью.</p><ol class=\"subq\"><li><span class=\"fr\"><span>6</span><span>100</span></span></li><li><span class=\"fr\"><span>9</span><span>1000</span></span></li><li><span class=\"fr\"><span>4</span><span>10</span></span></li></ol>","subs":[{"k":"e","v":"0,06","var":[],"show":"0,06"},{"k":"e","v":"0,009","var":[],"show":"0,009"},{"k":"e","v":"0,4","var":[],"show":"0,4"}],"sym":"","h":["Подумай: «Как записать <span class=\"fr\"><span>7</span><span>100</span></span> десятичной дробью: 0,7 или 0,07?»","Семь сотых записываем в разряде сотых. Между запятой и цифрой 7 стоит разряд десятых. Десятых нет, поэтому на их месте пишем 0."],"flag":{"dec":true}},{"n":33,"lab":"35.1","blk":"b","cls":5,"topic":"Движение по реке","err":"Прибавляет течение при движении против него","type":"sub","q":"<p>Даны собственная скорость и течение. Найди скорости по и против течения.</p><ol class=\"subq\"><li>10 и 2 км/ч</li><li>14 и 3 км/ч</li><li>8 и 1 км/ч</li></ol>","subs":[{"k":"t","v":["12 и 8 км/ч"],"show":"12 и 8 км/ч"},{"k":"t","v":["17 и 11 км/ч"],"show":"17 и 11 км/ч"},{"k":"t","v":["9 и 7 км/ч"],"show":"9 и 7 км/ч"}],"sym":"","h":["Подумай: «Лодка в стоячей воде идёт 12 км/ч. Течение 3 км/ч. Каковы скорости по реке?»","Собственная скорость — скорость лодки в стоячей воде. По течению река помогает: 12 + 3 = 15 км/ч. Против течения река замедляет лодку: 12 − 3 = 9 км/ч."]},{"n":34,"lab":"36.1","blk":"b","cls":5,"topic":"Время по часам","err":"Вычитает минуты, как будто в часе их сто","type":"sub","q":"<p>Найди, сколько времени прошло.</p><ol class=\"subq\"><li>8:50 → 9:15</li><li>13:40 → 14:05</li><li>16:35 → 17:10</li></ol>","subs":[{"k":"e","v":"25","var":[],"show":"25 мин"},{"k":"e","v":"25","var":[],"show":"25 мин"},{"k":"e","v":"35","var":[],"show":"35 мин"}],"sym":"","h":["Подумай: «Урок начался в 9:45, закончился в 10:20. Сколько минут он шёл?»","От 9:45 до 10:00 проходит 15 минут. От 10:00 до 10:20 проходит ещё 20 минут. Складываем: урок длился 35 минут."]},{"n":35,"lab":"36.2","blk":"b","cls":5,"topic":"Время по часам","err":"Теряет время после полуночи","type":"sub","q":"<p>Найди, сколько времени прошло.</p><ol class=\"subq\"><li>23:50 → 00:15</li><li>23:35 → 00:05</li><li>23:55 → 00:35</li></ol>","subs":[{"k":"e","v":"25","var":[],"show":"25 мин"},{"k":"e","v":"30","var":[],"show":"30 мин"},{"k":"e","v":"40","var":[],"show":"40 мин"}],"sym":"","h":["Подумай: «Поезд выехал в 23:40 и прибыл в 00:25. Сколько он ехал?»","От 23:40 до полуночи проходит 20 минут. После полуночи прошло ещё 25 минут. Вся поездка заняла 45 минут."]},{"n":36,"lab":"38.1","blk":"b","cls":5,"topic":"Сравнение дробей с единицей","err":"Считает любую обыкновенную дробь меньше единицы","type":"sub","q":"<p>Сравни дробь с единицей.</p><ol class=\"subq\"><li><span class=\"fr\"><span>9</span><span>7</span></span> и 1</li><li><span class=\"fr\"><span>4</span><span>9</span></span> и 1</li><li><span class=\"fr\"><span>11</span><span>8</span></span> и 1</li></ol>","subs":[{"k":"t","v":["9/7 > 1",">"],"show":"9/7 > 1"},{"k":"t","v":["4/9 < 1","<"],"show":"4/9 < 1"},{"k":"t","v":["11/8 > 1",">"],"show":"11/8 > 1"}],"sym":"","h":["Подумай: «Что больше: <span class=\"fr\"><span>7</span><span>5</span></span> или 1? Сколько пятых составляет целое?»","Одно целое составляет пять пятых. Семь пятых — это одно целое и ещё две пятых. Поэтому семь пятых больше единицы."]},{"n":37,"lab":"38.2","blk":"b","cls":5,"topic":"Сравнение дробей с единицей","err":"Принимает равные числитель и знаменатель за ноль","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>6</span><span>6</span></span></li><li><span class=\"fr\"><span>0</span><span>7</span></span></li><li><span class=\"fr\"><span>13</span><span>13</span></span></li></ol>","subs":[{"k":"e","v":"1","var":[],"show":"1"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"1","var":[],"show":"1"}],"sym":"","h":["Подумай: «Дробь <span class=\"fr\"><span>8</span><span>8</span></span> равна 0 или 1? Что означает её дробная черта?»","Дробная черта означает деление. Восемь восьмых составляют целое: 8 : 8 = 1. Ноль получился бы, если бы числитель равнялся нулю."]},{"n":38,"lab":"41.1","blk":"b","cls":5,"topic":"Сравнение величин и перевод единиц","err":"Сравнивает числа без перевода единиц","type":"sub","q":"<p>Поставь знак сравнения.</p><ol class=\"subq\"><li>3 м 4 см и 340 см</li><li>1 м 25 см и 125 см</li><li>2 м 9 см и 205 см</li></ol>","subs":[{"k":"t","v":["<"],"show":"<"},{"k":"t","v":["="],"show":"="},{"k":"t","v":[">"],"show":">"}],"sym":"","h":["Подумай: «Что длиннее: 2 м 8 см или 280 см?»","Два метра составляют 200 см. Прибавляем 8 см. Получаем 208 см. Теперь сравниваем обе длины в сантиметрах: 208 &lt; 280."]},{"n":39,"lab":"41.2","blk":"b","cls":5,"topic":"Сравнение величин и перевод единиц","err":"Читает десятичную часть как граммы","type":"sub","q":"<p>Вырази массу в граммах.</p><ol class=\"subq\"><li>0,4 кг</li><li>2,08 кг</li><li>3,005 кг</li></ol>","subs":[{"k":"e","v":"400","var":[],"show":"400 г"},{"k":"e","v":"2080","var":[],"show":"2080 г"},{"k":"e","v":"3005","var":[],"show":"3005 г"}],"sym":"","h":["Подумай: «Сколько граммов в 1,25 кг: 1025 или 1250?»","Один килограмм равен 1000 г. Чтобы выразить массу в граммах, умножаем число килограммов на 1000: 1,25 · 1000 = 1250."]},{"n":40,"lab":"42.1","blk":"b","cls":5,"topic":"Чтение шкал и диаграмм","err":"Считает деления, не проверяя цену деления","type":"sub","q":"<p>Найди цену деления шкалы.</p><ol class=\"subq\"><li>0–12, 4 промежутка</li><li>0–30, 5 промежутков</li><li>0–40, 8 промежутков</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «На шкале между 0 и 20 четыре равных промежутка. Что означает один?»","Между 0 и 20 разница 20 единиц. Делим её на число промежутков: 20 : 4 = 5. Одно деление соответствует пяти единицам."]},{"n":41,"lab":"42.2","blk":"b","cls":5,"topic":"Чтение шкал и диаграмм","err":"Считает от нуля на обрезанной шкале","type":"sub","q":"<p>Найди значение, двигаясь вверх по шкале.</p><ol class=\"subq\"><li>От 20: 2 шага по 5</li><li>От 60: 3 шага по 2</li><li>От 80: 1 шаг на 10</li></ol>","subs":[{"k":"e","v":"30","var":[],"show":"30"},{"k":"e","v":"66","var":[],"show":"66"},{"k":"e","v":"90","var":[],"show":"90"}],"sym":"","h":["Подумай: «Шкала начинается с 40. Столбик занимает два деления по 5. Каково значение?»","Первой отметке соответствует 40. Два деления прибавляют 2 · 5 = 10. На верхней отметке столбика получаем 40 + 10 = 50."]},{"n":42,"lab":"43.1","blk":"b","cls":5,"topic":"Цена, количество и стоимость","err":"Путает цену одной вещи со стоимостью покупки","type":"sub","q":"<p>Найди стоимость покупки.</p><ol class=\"subq\"><li>4 по 15 ₽</li><li>6 по 12 ₽</li><li>5 по 23 ₽</li></ol>","subs":[{"k":"e","v":"60","var":[],"show":"60 ₽"},{"k":"e","v":"72","var":[],"show":"72 ₽"},{"k":"e","v":"115","var":[],"show":"115 ₽"}],"sym":"","h":["Подумай: «Три ручки стоят по 18 ₽. Сколько заплатят за покупку?»","18 ₽ — цена одной ручки. Чтобы узнать стоимость покупки, берём эту цену три раза. Получаем 18 · 3 = 54 ₽."]},{"n":43,"lab":"43.2","blk":"b","cls":5,"topic":"Цена, количество и стоимость","err":"Делит цену на стоимость при поиске количества","type":"sub","q":"<p>Найди число купленных тетрадей.</p><ol class=\"subq\"><li>84 ₽, по 14 ₽</li><li>135 ₽, по 27 ₽</li><li>96 ₽, по 12 ₽</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «Одна тетрадь стоит 24 ₽. Сколько тетрадей купили на 120 ₽?»","Ищем, сколько раз по 24 ₽ помещается в 120 ₽. Делим общую стоимость на цену одной тетради. Получаем 120 : 24 = 5 тетрадей."]},{"n":44,"lab":"46.1","blk":"b","cls":5,"topic":"Остаток в текстовых задачах","err":"Принимает остаток за число полных групп","type":"sub","q":"<p>Найди, сколько предметов останется.</p><ol class=\"subq\"><li>29 штук по 6</li><li>38 штук по 7</li><li>41 штука по 9</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «37 наклеек раскладывают по 8. Сколько наклеек останется?»","Четыре полные группы занимают 4 · 8 = 32 наклейки. От 37 отнимаем 32. Получаем остаток 5. В вопросе просят назвать именно то, что осталось."]},{"n":45,"lab":"46.2","blk":"b","cls":5,"topic":"Остаток в текстовых задачах","err":"Путает нулевой остаток с первым местом","type":"sub","q":"<p>Назови цвет бусины в том же цикле.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"12.0 17.0 242.0 26.0\" width=\"300\" height=\"32\" role=\"img\" aria-label=\"Рисунок к заданию\"><circle cx=\"25.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#bc574b\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"43.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#2f5bb5\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"61.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#e2b04a\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"85.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#bc574b\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"103.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#2f5bb5\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"121.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#e2b04a\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"145.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#bc574b\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"163.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#2f5bb5\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"181.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#e2b04a\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"205.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#bc574b\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"223.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#2f5bb5\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"241.0\" cy=\"30.0\" r=\"5.0\" stroke=\"none\" fill=\"#e2b04a\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div><ol class=\"subq\"><li>7-я бусина</li><li>8-я бусина</li><li>9-я бусина</li></ol>","subs":[{"k":"t","v":["Красная"],"show":"Красная"},{"k":"t","v":["Синяя"],"show":"Синяя"},{"k":"t","v":["Жёлтая"],"show":"Жёлтая"}],"sym":"","h":["Подумай: «Цикл: красный, синий, жёлтый. Какого цвета 12-я бусина?»","В каждом полном цикле три бусины. Двенадцатая завершает четвёртый цикл. При остатке 0 берём последний цвет цикла: жёлтый."]},{"n":46,"lab":"48.1","blk":"b","cls":5,"topic":"Распределительное свойство в вычислениях","err":"Умножает только десятки","type":"sub","q":"<p>Вычисли, разложив второй множитель.</p><ol class=\"subq\"><li>14 · 13</li><li>16 · 15</li><li>23 · 12</li></ol>","subs":[{"k":"e","v":"182","var":[],"show":"182"},{"k":"e","v":"240","var":[],"show":"240"},{"k":"e","v":"276","var":[],"show":"276"}],"sym":"","h":["Подумай: «Как вычислить 17 · 12 через сумму 10 + 2?»","В числе 12 есть 10 и 2. Умножаем 17 на каждую часть. Получаем 170 и 34. Складываем: 204."]},{"n":47,"lab":"48.2","blk":"b","cls":5,"topic":"Распределительное свойство в вычислениях","err":"Теряет вычитание при округлении множителя","type":"sub","q":"<p>Вычисли через удобный круглый множитель.</p><ol class=\"subq\"><li>39 · 7</li><li>98 · 6</li><li>49 · 8</li></ol>","subs":[{"k":"e","v":"273","var":[],"show":"273"},{"k":"e","v":"588","var":[],"show":"588"},{"k":"e","v":"392","var":[],"show":"392"}],"sym":"","h":["Подумай: «Как умножить 48 на 9, используя 50 − 2?»","Если взять 50 групп по 9, получится на две группы больше. Вычитаем эти две группы: 450 − 18 = 432."]},{"n":48,"lab":"50.1","blk":"b","cls":5,"topic":"Прикидка результата","err":"Считает оценку суммы точным ответом","type":"sub","q":"<p>Округли слагаемые до целых и оцени сумму.</p><ol class=\"subq\"><li>8,9 + 12,2</li><li>6,1 + 14,8</li><li>24,2 + 5,9</li></ol>","subs":[{"k":"t","v":["Примерно 21"],"show":"Примерно 21"},{"k":"t","v":["Примерно 21"],"show":"Примерно 21"},{"k":"t","v":["Примерно 30"],"show":"Примерно 30"}],"sym":"","h":["Подумай: «Оценили 19,8 + 30,1 как 20 + 30. Можно ли записать точное равенство?»","Округление помогает быстро прикинуть результат. По округлённым числам получается примерно 50. Точная сумма исходных чисел равна 49,9."]},{"n":49,"lab":"50.2","blk":"b","cls":5,"topic":"Прикидка результата","err":"Не проверяет порядок величины произведения","type":"sub","q":"<p>Выбери правдоподобный ответ.</p><ol class=\"subq\"><li>9,8 · 2: 1,96 или 19,6</li><li>3,9 · 5: 19,5 или 195</li><li>8,1 · 3: 2,43 или 24,3</li></ol>","subs":[{"k":"e","v":"19,6","var":[],"show":"19,6"},{"k":"e","v":"19,5","var":[],"show":"19,5"},{"k":"e","v":"24,3","var":[],"show":"24,3"}],"sym":"","h":["Подумай: «Какой ответ правдоподобен для 19,8 · 3,1: 6,138 или 61,38?»","Округляем множители: примерно 20 и 3. Их произведение равно 60. Значит, точный ответ должен быть близок к 60. Проверяем положение запятой."]},{"n":50,"lab":"01.2","blk":"b","cls":6,"topic":"Обыкновенные дроби","err":"Меняет знаменатель, забывает числитель","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>3</span></span> + <span class=\"fr\"><span>1</span><span>6</span></span></li><li><span class=\"fr\"><span>2</span><span>5</span></span> + <span class=\"fr\"><span>1</span><span>10</span></span></li><li><span class=\"fr\"><span>3</span><span>4</span></span> − <span class=\"fr\"><span>1</span><span>8</span></span></li></ol>","subs":[{"k":"e","v":"1/2","alt":["3/6"],"show":"3/6 = 1/2"},{"k":"e","v":"1/2","alt":["5/10"],"show":"5/10 = 1/2"},{"k":"e","v":"5/8","var":[],"show":"5/8"}],"sym":"","h":["Подумай: «Чему равна <span class=\"fr\"><span>1</span><span>2</span></span> в четвертях? А чему равна сумма <span class=\"fr\"><span>1</span><span>2</span></span> + <span class=\"fr\"><span>1</span><span>4</span></span>?»","Раздели каждую половину ещё пополам. В закрашенной половине теперь две четверти. При умножении знаменателя на 2 умножаем числитель на 2. После этого складываем четверти."]},{"n":51,"lab":"01.3","blk":"b","cls":6,"topic":"Минус перед скобками","err":"Меняет знак только у первого слагаемого","type":"sub","q":"<p>Раскрой скобки и упрости.</p><ol class=\"subq\"><li>−(a + 7)</li><li>5 − (x + 2)</li><li>−(2y + 1) + 4</li></ol>","subs":[{"k":"e","v":"−a − 7","var":[],"show":"−a − 7"},{"k":"e","v":"3 − x","var":[],"show":"3 − x"},{"k":"e","v":"3 − 2y","var":[],"show":"3 − 2y"}],"sym":"","h":["Подумай: «Раскрой скобки: −(x + 3). Какой знак будет у числа 3?»","Если получается −x + 3, запиши минус как множитель −1. Покажи, как −1 умножается на каждое слагаемое в скобках."],"flag":{"nopar":true}},{"n":52,"lab":"01.4","blk":"b","cls":6,"topic":"Минус перед скобками","err":"Теряет второй минус при раскрытии скобок","type":"sub","q":"<p>Раскрой скобки и упрости.</p><ol class=\"subq\"><li>−(a − 4)</li><li>7 − (y − 2)</li><li>−(3x − 5) − 2</li></ol>","subs":[{"k":"e","v":"−a + 4","var":[],"show":"−a + 4"},{"k":"e","v":"9 − y","var":[],"show":"9 − y"},{"k":"e","v":"3 − 3x","var":[],"show":"3 − 3x"}],"sym":"","h":["Подумай: «Раскрой скобки: 8 − (x − 3). Какой знак будет у числа 3?»","Внутри скобок два слагаемых: x и −3. Внешний минус меняет знак каждого. Для второго слагаемого (−1) · (−3) = 3."],"flag":{"nopar":true}},{"n":53,"lab":"02.1","blk":"b","cls":6,"topic":"Действия с отрицательными числами","err":"Смешивает правила при сложении и умножении","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>−5 + (−2)</li><li>(−5) · (−2)</li><li>−8 + (−1)</li></ol>","subs":[{"k":"e","v":"−7","var":[],"show":"−7"},{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"−9","var":[],"show":"−9"}],"sym":"","h":["Подумай: «Вычисли −3 + (−4) и (−3) · (−4). Где получится плюс?»","При сложении складываем модули и сохраняем общий минус. При умножении двух отрицательных чисел получаем плюс."]},{"n":54,"lab":"02.2","blk":"b","cls":6,"topic":"Действия с отрицательными числами","err":"Идёт влево при вычитании отрицательного","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>−8 − (−2)</li><li>5 − (−4)</li><li>−2 − (−7)</li></ol>","subs":[{"k":"e","v":"−6","var":[],"show":"−6"},{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Чему равно −7 − (−3)? От −7 пойдём вправо или влево?»","Вычесть число значит прибавить противоположное. Для −3 противоположное число равно 3. Делаем три шага вправо."]},{"n":55,"lab":"03.1","blk":"b","cls":6,"topic":"Проценты","err":"Прибавляет к цене число процентов","type":"sub","q":"<p>Найди новую цену.</p><ol class=\"subq\"><li>300 ₽, рост на 10%</li><li>400 ₽, рост на 25%</li><li>240 ₽, рост на 50%</li></ol>","subs":[{"k":"e","v":"330","var":[],"show":"330 ₽"},{"k":"e","v":"500","var":[],"show":"500 ₽"},{"k":"e","v":"360","var":[],"show":"360 ₽"}],"sym":"","h":["Подумай: «Тетрадь стоит 200 ₽. Что значит повысить цену на 10%?»","10% от 200 ₽ составляют 20 ₽. Это сумма прибавки. Новая цена = старая цена + прибавка."]},{"n":56,"lab":"05.1","blk":"b","cls":6,"topic":"Степени","err":"Возводит минус в квадрат без скобок","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>(−4)²</li><li>−5²</li><li>(−2)³</li></ol>","subs":[{"k":"e","v":"16","var":[],"show":"16"},{"k":"e","v":"−25","var":[],"show":"−25"},{"k":"e","v":"−8","var":[],"show":"−8"}],"sym":"²³","h":["Подумай: «Будут ли равны (−3)² и −3²? Что возводим в квадрат?»","В (−3)² основание степени равно −3. В записи −3² в квадрат возводим 3, а перед результатом ставим минус."]},{"n":57,"lab":"07.1","blk":"b","cls":6,"topic":"НОД и НОК","err":"Для НОД берёт все простые множители","type":"sub","q":"<p>Найди НОД.</p><ol class=\"subq\"><li>НОД(8, 12)</li><li>НОД(18, 24)</li><li>НОД(25, 35)</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Найди НОД чисел 12 и 18. Делится ли 12 на твой ответ?»","Подчеркни множители, которые есть в обоих разложениях. В каждой паре берём по одному множителю. Получаем 2 · 3. Проверяем: и 12, и 18 делятся на 6."]},{"n":58,"lab":"07.2","blk":"b","cls":6,"topic":"НОД и НОК","err":"Для НОК берёт только общие множители","type":"sub","q":"<p>Найди НОК.</p><ol class=\"subq\"><li>НОК(4, 6)</li><li>НОК(8, 12)</li><li>НОК(15, 20)</li></ol>","subs":[{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"24","var":[],"show":"24"},{"k":"e","v":"60","var":[],"show":"60"}],"sym":"","h":["Подумай: «Найди НОК чисел 12 и 18. Делится ли ответ на оба числа?»","Начни с 12 = 2 · 2 · 3. Для делимости на 18 = 2 · 3 · 3 не хватает ещё одной тройки. Домножаем 12 на 3. Получаем 36: оно делится и на 12, и на 18."]},{"n":59,"lab":"07.3","blk":"b","cls":6,"topic":"Обратная пропорциональность","err":"При удвоении x удваивает y","type":"sub","q":"<p>Найди y, если y = <span class=\"fr\"><span>24</span><span>x</span></span>.</p><ol class=\"subq\"><li>x = 4</li><li>x = 8</li><li>x = 12</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"y = 6"},{"k":"e","v":"3","var":[],"show":"y = 3"},{"k":"e","v":"2","var":[],"show":"y = 2"}],"sym":"","h":["Подумай: «В формуле y = <span class=\"fr\"><span>24</span><span>x</span></span> увеличили x с 3 до 6. Как изменится y?»","Произведение x · y всегда равно 24. Если x увеличили вдвое, y уменьшается вдвое. Проверяем: 3 · 8 = 6 · 4."]},{"n":60,"lab":"11.3","blk":"b","cls":6,"topic":"Уравнения с модулем","err":"Записывает только один корень уравнения","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li>|x| = 2</li><li>|x| = 7</li><li>|x| = 10</li></ol>","subs":[{"k":"set","v":["−2","2"],"show":"−2 и 2"},{"k":"set","v":["−7","7"],"show":"−7 и 7"},{"k":"set","v":["−10","10"],"show":"−10 и 10"}],"sym":"","h":["Подумай: «Какие числа на прямой находятся на расстоянии 4 от нуля?»","Модуль числа — расстояние от числа до нуля. Отложи по 4 единицы в обе стороны от нуля. Получаем два решения уравнения |x| = 4: −4 и 4."]},{"n":61,"lab":"11.4","blk":"b","cls":6,"topic":"Уравнения с модулем","err":"Ищет корни, когда модуль равен отрицательному числу","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li>|x| = −5</li><li>|x| = 0</li><li>|x| = −0,4</li></ol>","subs":[{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"}],"sym":"","h":["Подумай: «Можно ли отойти от нуля на расстояние −3?»","Расстояние всегда неотрицательно. Модуль может быть нулём или положительным числом. Поэтому |x| = −3 не имеет решений, а из |x| = 0 получаем x = 0."]},{"n":62,"lab":"12.1","blk":"b","cls":6,"topic":"Деление обыкновенных дробей","err":"Переворачивает первую дробь","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>3</span><span>4</span></span> : <span class=\"fr\"><span>2</span><span>5</span></span></li><li><span class=\"fr\"><span>2</span><span>7</span></span> : <span class=\"fr\"><span>4</span><span>7</span></span></li><li><span class=\"fr\"><span>5</span><span>6</span></span> : <span class=\"fr\"><span>5</span><span>9</span></span></li></ol>","subs":[{"k":"e","v":"15/8","var":[],"show":"15/8"},{"k":"e","v":"1/2","var":[],"show":"1/2"},{"k":"e","v":"3/2","var":[],"show":"3/2"}],"sym":"","h":["Подумай: «Какую дробь заменяем обратной при вычислении <span class=\"fr\"><span>2</span><span>3</span></span> : <span class=\"fr\"><span>4</span><span>5</span></span>?»","Первую дробь оставляем. Заменяем деление умножением на дробь, обратную делителю. Для <span class=\"fr\"><span>4</span><span>5</span></span> обратная дробь равна <span class=\"fr\"><span>5</span><span>4</span></span>."]},{"n":63,"lab":"12.2","blk":"b","cls":6,"topic":"Деление обыкновенных дробей","err":"Умножает на целое число при делении","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>3</span><span>5</span></span> : 2</li><li><span class=\"fr\"><span>2</span><span>3</span></span> : 4</li><li><span class=\"fr\"><span>5</span><span>7</span></span> : 5</li></ol>","subs":[{"k":"e","v":"3/10","var":[],"show":"3/10"},{"k":"e","v":"1/6","var":[],"show":"1/6"},{"k":"e","v":"1/7","var":[],"show":"1/7"}],"sym":"","h":["Подумай: «Половину пирога разделили на двоих. Сколько получил каждый?»","Записываем 2 в виде дроби <span class=\"fr\"><span>2</span><span>1</span></span>. Обратная к ней равна <span class=\"fr\"><span>1</span><span>2</span></span>. Значит, деление на 2 даёт половину от исходной величины. Каждому достанется четверть целого пирога."]},{"n":64,"lab":"13.1","blk":"b","cls":6,"topic":"Пропорции","err":"Приравнивает произведения в столбцах","type":"sub","q":"<p>Найди неизвестный член пропорции.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x</span><span>10</span></span> = <span class=\"fr\"><span>3</span><span>5</span></span></li><li><span class=\"fr\"><span>x</span><span>8</span></span> = <span class=\"fr\"><span>3</span><span>4</span></span></li><li><span class=\"fr\"><span>x</span><span>12</span></span> = <span class=\"fr\"><span>2</span><span>3</span></span></li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «В пропорции <span class=\"fr\"><span>x</span><span>6</span></span> = <span class=\"fr\"><span>2</span><span>3</span></span> какие числа умножаем крест-накрест?»","Умножаем числитель каждой дроби на знаменатель другой. Это равносильно умножению обеих частей на 6 · 3. Получаем 3x = 12, значит x = 4."]},{"n":65,"lab":"13.2","blk":"b","cls":6,"topic":"Пропорции","err":"В прямой пропорции прибавляет одно и то же","type":"sub","q":"<p>Найди стоимость указанного количества тетрадей.</p><ol class=\"subq\"><li>2 шт. за 60 ₽ → 7 шт.</li><li>4 шт. за 80 ₽ → 6 шт.</li><li>6 шт. за 90 ₽ → 4 шт.</li></ol>","subs":[{"k":"e","v":"210","var":[],"show":"210 ₽"},{"k":"e","v":"120","var":[],"show":"120 ₽"},{"k":"e","v":"60","var":[],"show":"60 ₽"}],"sym":"","h":["Подумай: «Три тетради стоят 90 ₽. Сколько стоят пять таких тетрадей?»","При одинаковой цене сначала найдём стоимость одной тетради: 90 : 3 = 30 ₽. Теперь умножаем 30 на 5. Две дополнительные тетради стоят 60 ₽."]},{"n":66,"lab":"15.1","blk":"b","cls":6,"topic":"Умножение дробей","err":"Ищет общий знаменатель при умножении","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"fr\"><span>2</span><span>3</span></span> · <span class=\"fr\"><span>3</span><span>4</span></span></li><li><span class=\"fr\"><span>4</span><span>5</span></span> · <span class=\"fr\"><span>5</span><span>7</span></span></li><li><span class=\"fr\"><span>3</span><span>8</span></span> · <span class=\"fr\"><span>2</span><span>3</span></span></li></ol>","subs":[{"k":"e","v":"1/2","var":[],"show":"1/2"},{"k":"e","v":"4/7","var":[],"show":"4/7"},{"k":"e","v":"1/4","var":[],"show":"1/4"}],"sym":"","h":["Подумай: «Как умножить <span class=\"fr\"><span>2</span><span>3</span></span> на <span class=\"fr\"><span>3</span><span>5</span></span>? Нужен ли общий знаменатель?»","Умножаем числитель на числитель и знаменатель на знаменатель. Получаем шесть пятнадцатых. Делим числитель и знаменатель на 3 и получаем две пятых."]},{"n":67,"lab":"15.2","blk":"b","cls":6,"topic":"Умножение дробей","err":"Умножает только целые части","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>1 <span class=\"fr\"><span>1</span><span>2</span></span> · 1 <span class=\"fr\"><span>1</span><span>3</span></span></li><li>2 <span class=\"fr\"><span>1</span><span>4</span></span> · 1 <span class=\"fr\"><span>1</span><span>3</span></span></li><li>1 <span class=\"fr\"><span>2</span><span>3</span></span> · 1 <span class=\"fr\"><span>1</span><span>5</span></span></li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"2","var":[],"show":"2"}],"sym":"","h":["Подумай: «Как вычислить 1 <span class=\"fr\"><span>1</span><span>2</span></span> · 2 <span class=\"fr\"><span>1</span><span>3</span></span>? Можно ли умножить только 1 на 2?»","Смешанное число включает целую и дробную части. Переводим оба числа в неправильные дроби: полторы единицы дают три половины, а две с третью — семь третей."]},{"n":68,"lab":"16.5","blk":"b","cls":6,"topic":"Симметрия на координатной плоскости","err":"Меняет оба знака при отражении в оси y","type":"sub","q":"<p>Найди отражение относительно оси y.</p><ol class=\"subq\"><li>(4; 1)</li><li>(−2; −3)</li><li>(0; 5)</li></ol>","subs":[{"k":"t","v":["(−4; 1)","−4; 1"],"show":"(−4; 1)"},{"k":"t","v":["(2; −3)","2; −3"],"show":"(2; −3)"},{"k":"t","v":["(0; 5)","0; 5"],"show":"(0; 5)"}],"sym":"","h":["Подумай: «Какая точка симметрична A(3; 2) относительно оси y?»","От точки A до оси y три единицы по горизонтали. Отложи столько же слева от оси на той же высоте. Знак x меняется, координата y остаётся прежней."]},{"n":69,"lab":"16.6","blk":"b","cls":6,"topic":"Симметрия на координатной плоскости","err":"Меняет только один знак при центральной симметрии","type":"sub","q":"<p>Найди симметричную точку относительно (0; 0).</p><ol class=\"subq\"><li>(5; 2)</li><li>(−3; 4)</li><li>(0; −6)</li></ol>","subs":[{"k":"t","v":["(−5; −2)","−5; −2"],"show":"(−5; −2)"},{"k":"t","v":["(3; −4)","3; −4"],"show":"(3; −4)"},{"k":"t","v":["(0; 6)","0; 6"],"show":"(0; 6)"}],"sym":"","h":["Подумай: «Какая точка симметрична A(3; 2) относительно начала координат?»","При центральной симметрии начало координат служит серединой отрезка AA′. Поэтому координаты точек попарно противоположны: меняются оба знака."]},{"n":70,"lab":"17.3","blk":"b","cls":6,"topic":"Совместная работа","err":"Складывает время вместо долей работы","type":"sub","q":"<p>Найди долю бака за час по времени каждой трубы.</p><ol class=\"subq\"><li>4 ч и 4 ч</li><li>6 ч и 12 ч</li><li>5 ч и 10 ч</li></ol>","subs":[{"k":"e","v":"1/2","var":[],"show":"1/2 бака"},{"k":"e","v":"1/4","var":[],"show":"1/4 бака"},{"k":"e","v":"3/10","var":[],"show":"3/10 бака"}],"sym":"","h":["Подумай: «Один заполнит бак за 6 ч, другой за 3 ч. Что они сделают за час?»","За целый бак берём 1. За час первый заполнит его на одну шестую, второй на одну треть. Складываем доли за час. Вместе они заполнят половину бака за час."]},{"n":71,"lab":"17.4","blk":"b","cls":6,"topic":"Совместная работа","err":"Принимает долю за час за время работы","type":"sub","q":"<p>Найди время заполнения всего бака.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>3</span></span> бака за час</li><li><span class=\"fr\"><span>1</span><span>5</span></span> бака за час</li><li><span class=\"fr\"><span>2</span><span>3</span></span> бака за час</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3 ч"},{"k":"e","v":"5","var":[],"show":"5 ч"},{"k":"e","v":"1 1/2","var":[],"show":"1 1/2 ч"}],"sym":"","h":["Подумай: «За час вместе заполняют четверть бака. За сколько часов весь?»","Четверть бака — результат за один час. Чтобы найти время, считаем, сколько таких частей помещается в целом баке: 1 делим на одну четверть."]},{"n":72,"lab":"20.1","blk":"b","cls":6,"topic":"Масштаб","err":"Делит вместо умножения при чтении карты","type":"sub","q":"<p>Найди расстояние на местности.</p><ol class=\"subq\"><li>2 см, 1 : 5000</li><li>4 см, 1 : 2000</li><li>5 см, 1 : 10 000</li></ol>","subs":[{"k":"e","v":"100","var":[],"show":"100 м"},{"k":"e","v":"80","var":[],"show":"80 м"},{"k":"e","v":"500","var":[],"show":"500 м"}],"sym":"","h":["Подумай: «Масштаб 1 : 5000. На карте 3 см. Сколько это на местности?»","Каждый сантиметр на карте соответствует 5000 см. Для трёх сантиметров берём три таких отрезка. Получаем 15 000 см, или 150 м."]},{"n":73,"lab":"20.2","blk":"b","cls":6,"topic":"Масштаб","err":"Делит величины в разных единицах","type":"sub","q":"<p>Найди длину отрезка на плане.</p><ol class=\"subq\"><li>80 м, 1 : 2000</li><li>350 м, 1 : 5000</li><li>120 м, 1 : 4000</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4 см"},{"k":"e","v":"7","var":[],"show":"7 см"},{"k":"e","v":"3","var":[],"show":"3 см"}],"sym":"","h":["Подумай: «На местности 240 м. Масштаб 1 : 4000. Сколько см на плане?»","В одном сантиметре плана помещаются 4000 см местности. Приводим величины к одним единицам: 4000 см = 40 м. Отрезок 240 м содержит шесть отрезков по 40 м."]},{"n":74,"lab":"20.4","blk":"b","cls":6,"topic":"Сравнение обыкновенных дробей","err":"Сравнивает дроби только по числителям","type":"sub","q":"<p>Поставь знак сравнения.</p><ol class=\"subq\"><li><span class=\"fr\"><span>2</span><span>3</span></span> и <span class=\"fr\"><span>3</span><span>5</span></span></li><li><span class=\"fr\"><span>3</span><span>8</span></span> и <span class=\"fr\"><span>2</span><span>5</span></span></li><li><span class=\"fr\"><span>5</span><span>6</span></span> и <span class=\"fr\"><span>7</span><span>9</span></span></li></ol>","subs":[{"k":"t","v":["2/3 > 3/5",">"],"show":"2/3 > 3/5"},{"k":"t","v":["3/8 < 2/5","<"],"show":"3/8 < 2/5"},{"k":"t","v":["5/6 > 7/9",">"],"show":"5/6 > 7/9"}],"sym":"","h":["Подумай: «Что больше: <span class=\"fr\"><span>3</span><span>4</span></span> или <span class=\"fr\"><span>4</span><span>7</span></span>? Достаточно ли сравнить 3 и 4?»","Приводим дроби к знаменателю 28. Получаем 21 и 16 долей одинакового размера. Теперь можно сравнить числители: 21 больше 16, значит, три четверти больше четырёх седьмых."]},{"n":75,"lab":"22.1","blk":"b","cls":6,"topic":"Отрицательные числа","err":"Сравнивает отрицательные числа по модулю","type":"sub","q":"<p>Сравни числа.</p><ol class=\"subq\"><li>−8 и −2</li><li>−4 и −9</li><li>−12 и −11</li></ol>","subs":[{"k":"t","v":["−8 < −2","<"],"show":"−8 < −2"},{"k":"t","v":["−4 > −9",">"],"show":"−4 > −9"},{"k":"t","v":["−12 < −11","<"],"show":"−12 < −11"}],"sym":"","h":["Подумай: «Какое число больше: −7 или −3? Какое правее на прямой?»","Число, расположенное правее на числовой прямой, больше. Точка −3 правее точки −7, поэтому −3 &gt; −7."]},{"n":76,"lab":"22.2","blk":"b","cls":6,"topic":"Отрицательные числа","err":"Не замечает целое число между отрицательными","type":"sub","q":"<p>Назови целое число между указанными числами.</p><ol class=\"subq\"><li>Между −8 и −6</li><li>Между −4 и −2</li><li>Между −3 и −1</li></ol>","subs":[{"k":"e","v":"−7","var":[],"show":"−7"},{"k":"e","v":"−3","var":[],"show":"−3"},{"k":"e","v":"−2","var":[],"show":"−2"}],"sym":"","h":["Подумай: «Есть ли целое число между −5 и −3? Где его отметить?»","Проведи пальцем по прямой от −5 вправо к −3. Сначала встретится −4. Это число больше −5 и меньше −3."]},{"n":77,"lab":"23.5","blk":"b","cls":6,"topic":"Длина окружности и дуги","err":"Подставляет диаметр в формулу с радиусом","type":"sub","q":"<p>Найди длину окружности.</p><ol class=\"subq\"><li>d = 10 см</li><li>d = 14 см</li><li>r = 6 см</li></ol>","subs":[{"k":"e","v":"10π","var":[],"show":"10π см"},{"k":"e","v":"14π","var":[],"show":"14π см"},{"k":"e","v":"12π","var":[],"show":"12π см"}],"sym":"π","h":["Подумай: «Диаметр окружности 8 см. Чему равна её длина?»","Диаметр d вдвое больше радиуса r. Длину окружности можно найти как πd или 2πr. Если диаметр равен 8 см, радиус равен 4 см, и обе формулы дают 8π см."]},{"n":78,"lab":"24.1","blk":"b","cls":6,"topic":"Признаки делимости","err":"Проверяет делимость на 3 по последней цифре","type":"sub","q":"<p>Проверь делимость на 3.</p><ol class=\"subq\"><li>124</li><li>231</li><li>415</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «Делится ли 132 на 3? Что нужно проверить?»","Складываем все цифры числа: 1 + 3 + 2 = 6. Сумма делится на 3, значит, и число 132 делится на 3. Последняя цифра 2 сама по себе ответа не даёт."]},{"n":79,"lab":"24.2","blk":"b","cls":6,"topic":"Признаки делимости","err":"Путает признаки делимости на 3 и на 9","type":"sub","q":"<p>Проверь делимость на 3 и на 9.</p><ol class=\"subq\"><li>234</li><li>321</li><li>251</li></ol>","subs":[{"k":"t","v":["На 3 и на 9"],"show":"На 3 и на 9"},{"k":"t","v":["Только на 3"],"show":"Только на 3"},{"k":"t","v":["Ни на 3, ни на 9"],"show":"Ни на 3, ни на 9"}],"sym":"","h":["Подумай: «Делится ли 123 на 3? А на 9?»","Сумма цифр числа 123 равна 6. Число 6 делится на 3, поэтому 123 делится на 3. Для делимости на 9 сумма цифр должна делиться на 9."]},{"n":80,"lab":"24.3","blk":"b","cls":6,"topic":"Координатная плоскость","err":"Переставляет координаты точки","type":"sub","q":"<p>Опиши путь от начала координат.</p><ol class=\"subq\"><li>A(4; 1)</li><li>B(1; 4)</li><li>C(3; 2)</li></ol>","subs":[{"k":"t","v":["4 вправо, 1 вверх"],"show":"4 вправо, 1 вверх"},{"k":"t","v":["1 вправо, 4 вверх"],"show":"1 вправо, 4 вверх"},{"k":"t","v":["3 вправо, 2 вверх"],"show":"3 вправо, 2 вверх"}],"sym":"","h":["Подумай: «Где отметить A(2; 3)? Сколько шагов вправо и вверх?»","Первое число в паре задаёт положение по оси x. Второе число задаёт положение по оси y. От нуля идём на 2 вправо, затем на 3 вверх."]},{"n":81,"lab":"24.4","blk":"b","cls":6,"topic":"Координатная плоскость","err":"Относит точку на оси к четверти","type":"sub","q":"<p>Назови ось или четверть.</p><ol class=\"subq\"><li>(0; 4)</li><li>(−3; 0)</li><li>(−2; −1)</li></ol>","subs":[{"k":"t","v":["На оси y"],"show":"На оси y"},{"k":"t","v":["На оси x"],"show":"На оси x"},{"k":"t","v":["III четверть"],"show":"III четверть"}],"sym":"","h":["Подумай: «Где находится A(0; −3): на оси или в четверти?»","Первая координата равна нулю. От начала координат двигаемся только вниз, вдоль оси y. Оси отделяют четверти друг от друга. Точка на оси не входит в четверть."]},{"n":82,"lab":"25.4","blk":"b","cls":6,"topic":"Дробь от числа и число по его дроби","err":"Снова берёт дробь, когда нужно найти целое","type":"sub","q":"<p>Восстанови целое число.</p><ol class=\"subq\"><li><span class=\"fr\"><span>2</span><span>3</span></span> числа равны 10</li><li><span class=\"fr\"><span>3</span><span>4</span></span> числа равны 12</li><li><span class=\"fr\"><span>2</span><span>5</span></span> числа равны 14</li></ol>","subs":[{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"16","var":[],"show":"16"},{"k":"e","v":"35","var":[],"show":"35"}],"sym":"","h":["Подумай: «Три пятых всех карандашей составляют 12. Сколько их всего?»","В трёх равных частях 12 карандашей, значит, в одной 4. Целое состоит из пяти таких частей. Восстанавливаем все пять: 4 · 5 = 20 карандашей."]},{"n":83,"lab":"26.5","blk":"b","cls":6,"topic":"Цена до скидки и повышения","err":"Берёт процент от цены после скидки","type":"sub","q":"<p>Найди цену до скидки.</p><ol class=\"subq\"><li>720 ₽, скидка 10%</li><li>600 ₽, скидка 25%</li><li>450 ₽, скидка 50%</li></ol>","subs":[{"k":"e","v":"800","var":[],"show":"800 ₽"},{"k":"e","v":"800","var":[],"show":"800 ₽"},{"k":"e","v":"900","var":[],"show":"900 ₽"}],"sym":"","h":["Подумай: «После скидки 20% цена стала 800 ₽. Какой она была до скидки?»","Исходную цену принимаем за 100%. После скидки осталось 80%. Если 80% исходной цены равны 800 ₽, то 1% составляет 10 ₽. Умножаем 10 ₽ на 100 и получаем 1000 ₽."]},{"n":84,"lab":"26.6","blk":"b","cls":6,"topic":"Цена до скидки и повышения","err":"Убирает наценку, вычитая процент от новой цены","type":"sub","q":"<p>Найди цену до повышения.</p><ol class=\"subq\"><li>660 ₽, рост 10%</li><li>720 ₽, рост 20%</li><li>900 ₽, рост 50%</li></ol>","subs":[{"k":"e","v":"600","var":[],"show":"600 ₽"},{"k":"e","v":"600","var":[],"show":"600 ₽"},{"k":"e","v":"600","var":[],"show":"600 ₽"}],"sym":"","h":["Подумай: «После повышения на 25% цена стала 500 ₽. Сколько было?»","Цена после повышения составляет 125% от исходной. Делим 500 ₽ на 125 и находим 1%, то есть 4 ₽. Изначальная цена равна 100 · 4 ₽ = 400 ₽."]},{"n":85,"lab":"27.1","blk":"b","cls":6,"topic":"Перевод единиц скорости","err":"Переводит километры, но забывает про часы","type":"sub","q":"<p>Переведи в метры в секунду.</p><ol class=\"subq\"><li>18 км/ч</li><li>72 км/ч</li><li>90 км/ч</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5 м/с"},{"k":"e","v":"20","var":[],"show":"20 м/с"},{"k":"e","v":"25","var":[],"show":"25 м/с"}],"sym":"","h":["Подумай: «Скорость 36 км/ч. Сколько метров тело проходит за секунду?»","За час тело проходит 36 000 м. В одном часе 3600 секунд. Чтобы узнать путь за одну секунду, делим 36 000 на 3600. Получаем 10 м/с."]},{"n":86,"lab":"27.2","blk":"b","cls":6,"topic":"Перевод единиц скорости","err":"Делит на 3,6 при переводе в км/ч","type":"sub","q":"<p>Переведи в километры в час.</p><ol class=\"subq\"><li>10 м/с</li><li>15 м/с</li><li>25 м/с</li></ol>","subs":[{"k":"e","v":"36","var":[],"show":"36 км/ч"},{"k":"e","v":"54","var":[],"show":"54 км/ч"},{"k":"e","v":"90","var":[],"show":"90 км/ч"}],"sym":"","h":["Подумай: «Скорость 5 м/с. Сколько километров тело проходит за час?»","За час проходит 5 · 3600 = 18 000 м. Переводим метры в километры: 18 000 : 1000 = 18. Так получается множитель 3600 : 1000 = 3,6."]},{"n":87,"lab":"29.1","blk":"b","cls":6,"topic":"Средняя скорость","err":"Усредняет скорости на равных расстояниях","type":"sub","q":"<p>Найди среднюю скорость на двух равных участках.</p><ol class=\"subq\"><li>30 и 60 км/ч</li><li>20 и 60 км/ч</li><li>40 и 60 км/ч</li></ol>","subs":[{"k":"e","v":"40","var":[],"show":"40 км/ч"},{"k":"e","v":"30","var":[],"show":"30 км/ч"},{"k":"e","v":"48","var":[],"show":"48 км/ч"}],"sym":"","h":["Подумай: «Туда и обратно по 60 км. Скорости 60 и 30 км/ч. Какая средняя?»","В одну сторону едем 1 час, в другую 2 часа. Средняя скорость равна всему пути, делённому на всё время. Получаем 120 : (1 + 2) = 40 км/ч."]},{"n":88,"lab":"29.2","blk":"b","cls":6,"topic":"Средняя скорость","err":"Забывает учесть остановку","type":"sub","q":"<p>Ехали 1 час. Найди среднюю скорость с учётом стоянки.</p><ol class=\"subq\"><li>12 км, стоп 0,5 ч</li><li>20 км, стоп 1 ч</li><li>15 км, стоп 0,5 ч</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8 км/ч"},{"k":"e","v":"10","var":[],"show":"10 км/ч"},{"k":"e","v":"10","var":[],"show":"10 км/ч"}],"sym":"","h":["Подумай: «За час проехали 24 км и стояли ещё 30 мин. Какая средняя скорость?»","Во время остановки путь не меняется, а время идёт. От начала движения прошло 1,5 ч, путь равен 24 км. Средняя скорость за весь промежуток равна 24 : 1,5 = 16 км/ч."]},{"n":89,"lab":"31.1","blk":"b","cls":6,"topic":"Модуль в числовых выражениях","err":"Убирает минус перед модулем","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>−|−8|</li><li>−|3|</li><li>−|0|</li></ol>","subs":[{"k":"e","v":"−8","var":[],"show":"−8"},{"k":"e","v":"−3","var":[],"show":"−3"},{"k":"e","v":"0","var":[],"show":"0"}],"sym":"","h":["Подумай: «Чему равны |−5| и −|−5|? Где находится внешний минус?»","Сначала вычисляем модуль: расстояние от −5 до нуля равно 5. В выражении −|−5| внешний минус сохраняется. После вычисления модуля получаем −5."]},{"n":90,"lab":"31.2","blk":"b","cls":6,"topic":"Модуль в числовых выражениях","err":"Находит модуль раньше действий внутри","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>|5 − 9|</li><li>|2 − 10|</li><li>|7 − 3|</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"","h":["Подумай: «Чему равно |3 − 7|? Какое действие выполняем первым?»","Сначала вычисляем выражение внутри знаков модуля. Разность 3 − 7 равна −4. Затем находим расстояние от −4 до нуля и получаем 4."]},{"n":91,"lab":"32.1","blk":"b","cls":6,"topic":"Отношение частей и доля целого","err":"Делит целое на одну из частей отношения","type":"sub","q":"<p>Найди обе части.</p><ol class=\"subq\"><li>20, отношение 1 : 4</li><li>30, отношение 2 : 3</li><li>42, отношение 3 : 4</li></ol>","subs":[{"k":"set","v":["4","16"],"show":"4 и 16"},{"k":"set","v":["12","18"],"show":"12 и 18"},{"k":"set","v":["18","24"],"show":"18 и 24"}],"sym":"","h":["Подумай: «24 бусины разделили в отношении 1 : 3. Сколько в меньшей группе?»","В меньшей группе одна доля, в большей три. Всего четыре одинаковые доли. Делим 24 на 4. В меньшей группе 6 бусин, в большей 18."]},{"n":92,"lab":"32.2","blk":"b","cls":6,"topic":"Отношение частей и доля целого","err":"Принимает отношение двух частей за долю целого","type":"sub","q":"<p>Найди долю красных, если дано отношение красных к синим.</p><ol class=\"subq\"><li>1 : 4</li><li>3 : 4</li><li>2 : 7</li></ol>","subs":[{"k":"e","v":"1/5","var":[],"show":"1/5"},{"k":"e","v":"3/7","var":[],"show":"3/7"},{"k":"e","v":"2/9","var":[],"show":"2/9"}],"sym":"","h":["Подумай: «Красные и синие бусины относятся как 2 : 3. Какая доля красных?»","Две доли относятся к трём долям синих бусин. Для дроби от всех бусин знаменатель равен 2 + 3. Поэтому красные составляют две пятых всех бусин."]},{"n":93,"lab":"33.2","blk":"b","cls":6,"topic":"Десятичная запись обыкновенной дроби","err":"Меняет знаменатель, оставляя числитель","type":"sub","q":"<p>Запиши десятичной дробью.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>4</span></span></li><li><span class=\"fr\"><span>7</span><span>20</span></span></li><li><span class=\"fr\"><span>3</span><span>8</span></span></li></ol>","subs":[{"k":"e","v":"0,25","var":[],"show":"0,25"},{"k":"e","v":"0,35","var":[],"show":"0,35"},{"k":"e","v":"0,375","var":[],"show":"0,375"}],"sym":"","h":["Подумай: «Как записать <span class=\"fr\"><span>3</span><span>4</span></span> в сотых долях и затем десятичной дробью?»","Чтобы получить знаменатель 100, умножаем 4 на 25. Числитель умножаем на то же число. Получаем 75 сотых. Семь десятых и пять сотых записываем как 0,75."],"flag":{"dec":true}},{"n":94,"lab":"35.2","blk":"b","cls":6,"topic":"Движение по реке","err":"Считает разность скоростей скоростью течения","type":"sub","q":"<p>Даны скорости по и против течения. Найди скорость течения.</p><ol class=\"subq\"><li>16 и 10 км/ч</li><li>21 и 13 км/ч</li><li>15 и 11 км/ч</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3 км/ч"},{"k":"e","v":"4","var":[],"show":"4 км/ч"},{"k":"e","v":"2","var":[],"show":"2 км/ч"}],"sym":"","h":["Подумай: «Лодка идёт по течению 18 км/ч, против 12 км/ч. Какова скорость течения?»","По течению к собственной скорости прибавляем скорость реки, против течения вычитаем её. Разность скоростей содержит две скорости течения. Поэтому (18 − 12) : 2 = 3."]},{"n":95,"lab":"37.1","blk":"b","cls":6,"topic":"Раскрытие скобок с дробным множителем","err":"Умножает на дробь только первое слагаемое","type":"sub","q":"<p>Раскрой скобки.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>2</span></span>(8x + 6)</li><li><span class=\"fr\"><span>1</span><span>4</span></span>(12a − 8)</li><li><span class=\"fr\"><span>1</span><span>5</span></span>(15y + 10)</li></ol>","subs":[{"k":"e","v":"4x + 3","var":[],"show":"4x + 3"},{"k":"e","v":"3a − 2","var":[],"show":"3a − 2"},{"k":"e","v":"3y + 2","var":[],"show":"3y + 2"}],"sym":"","h":["Подумай: «Раскрой скобки: <span class=\"fr\"><span>1</span><span>3</span></span>(6x + 9). Что получится из числа 9?»","Одну треть берём от каждого слагаемого. От 6x получаем 2x, от 9 получаем 3. Складываем результаты: 2x + 3."],"flag":{"nopar":true}},{"n":96,"lab":"37.2","blk":"b","cls":6,"topic":"Раскрытие скобок с дробным множителем","err":"Теряет минус дробного множителя","type":"sub","q":"<p>Раскрой скобки.</p><ol class=\"subq\"><li>−<span class=\"fr\"><span>1</span><span>2</span></span>(6x − 8)</li><li>−<span class=\"fr\"><span>1</span><span>3</span></span>(9a + 6)</li><li>−<span class=\"fr\"><span>1</span><span>5</span></span>(10y − 15)</li></ol>","subs":[{"k":"e","v":"−3x + 4","var":[],"show":"−3x + 4"},{"k":"e","v":"−3a − 2","var":[],"show":"−3a − 2"},{"k":"e","v":"−2y + 3","var":[],"show":"−2y + 3"}],"sym":"","h":["Подумай: «Раскрой скобки: −<span class=\"fr\"><span>1</span><span>2</span></span>(4x − 6). Каким будет знак числа 3?»","Умножаем каждое слагаемое на минус одну вторую. Произведение с 4x даёт −2x. Произведение двух отрицательных чисел даёт +3."],"flag":{"nopar":true}},{"n":97,"lab":"39.1","blk":"b","cls":6,"topic":"Изменение температуры и отрицательные числа","err":"Принимает изменение температуры за итог","type":"sub","q":"<p>Найди итоговую температуру.</p><ol class=\"subq\"><li>−9 °C, рост на 5 °C</li><li>−3 °C, рост на 7 °C</li><li>2 °C, спад на 6 °C</li></ol>","subs":[{"k":"t","v":["−4 °C"],"show":"−4 °C"},{"k":"t","v":["4 °C"],"show":"4 °C"},{"k":"t","v":["−4 °C"],"show":"−4 °C"}],"sym":"°","h":["Подумай: «Было −6 °C, потеплело на 4 °C. Какая теперь температура?»","Начинаем с −6. Потепление на 4 означает прибавить 4. Число 4 показывает изменение температуры. Итоговая температура равна −6 + 4 = −2 °C."]},{"n":98,"lab":"39.2","blk":"b","cls":6,"topic":"Изменение температуры и отрицательные числа","err":"Вычитает конечную температуру из начальной","type":"sub","q":"<p>Найди, на сколько градусов потеплело.</p><ol class=\"subq\"><li>От −7 до −2 °C</li><li>От −3 до 4 °C</li><li>От −9 до 0 °C</li></ol>","subs":[{"k":"t","v":["5 °C"],"show":"5 °C"},{"k":"t","v":["7 °C"],"show":"7 °C"},{"k":"t","v":["9 °C"],"show":"9 °C"}],"sym":"°","h":["Подумай: «Было −5 °C, стало 2 °C. На сколько градусов потеплело?»","Из конечной температуры вычитаем начальную. Получаем 2 − (−5) = 2 + 5 = 7 °C. Проверяем: если к −5 прибавить 7, получится 2."]},{"n":99,"lab":"45.1","blk":"b","cls":6,"topic":"Дроби от разных величин","err":"Сравнивает доли, забывая о размере целого","type":"sub","q":"<p>Сравни значения долей.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>2</span></span> от 14 и <span class=\"fr\"><span>1</span><span>3</span></span> от 24</li><li><span class=\"fr\"><span>1</span><span>2</span></span> от 18 и <span class=\"fr\"><span>1</span><span>4</span></span> от 32</li><li><span class=\"fr\"><span>1</span><span>3</span></span> от 21 и <span class=\"fr\"><span>1</span><span>2</span></span> от 14</li></ol>","subs":[{"k":"t","v":["<"],"show":"<"},{"k":"t","v":[">"],"show":">"},{"k":"t","v":["="],"show":"="}],"sym":"","h":["Подумай: «Что больше: половина от 18 конфет или треть от 30 конфет?»","Половина больше трети, если берём доли одного целого. Здесь целые разные. Находим обе доли отдельно: 18 : 2 = 9, а 30 : 3 = 10. Значит, больше треть от 30."]},{"n":100,"lab":"45.2","blk":"b","cls":6,"topic":"Дроби от разных величин","err":"Находит вторую долю от исходного числа","type":"sub","q":"<p>Сначала потратили половину суммы. Сколько потратили потом?.</p><ol class=\"subq\"><li>18 ₽ и <span class=\"fr\"><span>1</span><span>3</span></span> остатка</li><li>32 ₽ и <span class=\"fr\"><span>1</span><span>4</span></span> остатка</li><li>30 ₽ и <span class=\"fr\"><span>1</span><span>5</span></span> остатка</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3 ₽"},{"k":"e","v":"4","var":[],"show":"4 ₽"},{"k":"e","v":"3","var":[],"show":"3 ₽"}],"sym":"","h":["Подумай: «Из 24 ₽ потратили половину, потом треть остатка. Сколько потратили потом?»","После первой покупки осталось 24 − 12 = 12 ₽. Слово «остатка» задаёт новое целое: 12 ₽. Делим 12 на 3 и получаем 4 ₽."]},{"n":101,"lab":"47.1","blk":"b","cls":6,"topic":"Вычисления по формуле","err":"Подставляет значения не на свои места","type":"sub","q":"<p>Найди P по формуле P = 2a + b.</p><ol class=\"subq\"><li>a = 4, b = 1</li><li>a = 5, b = 2</li><li>a = 1, b = 8</li></ol>","subs":[{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"10","var":[],"show":"10"}],"sym":"","h":["Подумай: «По формуле P = 2a + b вычисли P, если a = 3, b = 7».","Буква a встречается рядом с множителем 2. На её место ставим 3. На место b ставим 7. Сначала вычисляем 2 · 3, затем прибавляем 7."]},{"n":102,"lab":"47.6","blk":"b","cls":6,"topic":"Процентные изменения","err":"Делит разницу на новое значение","type":"sub","q":"<p>Найди рост в процентах.</p><ol class=\"subq\"><li>Было 40, стало 50</li><li>Было 60, стало 90</li><li>Было 20, стало 22</li></ol>","subs":[{"k":"e","v":"25","var":[],"show":"25%"},{"k":"e","v":"50","var":[],"show":"50%"},{"k":"e","v":"10","var":[],"show":"10%"}],"sym":"","h":["Подумай: «Было 80 участников, стало 100. На сколько процентов стало больше?»","Прирост равен 100 − 80 = 20 участников. За 100% принимаем исходные 80 участников. Делим 20 на 80 и получаем 0,25, или 25%."]},{"n":103,"lab":"01.5","blk":"m","cls":7,"topic":"Формулы сокращённого умножения","err":"Теряет средний член в квадрате суммы","type":"sub","q":"<p>Раскрой скобки по формуле.</p><ol class=\"subq\"><li>(a + 2)²</li><li>(y + 5)²</li><li>(2x + 1)²</li></ol>","subs":[{"k":"e","v":"a² + 4a + 4","var":[],"show":"a² + 4a + 4"},{"k":"e","v":"y² + 10y + 25","var":[],"show":"y² + 10y + 25"},{"k":"e","v":"4x² + 4x + 1","var":[],"show":"4x² + 4x + 1"}],"sym":"²","h":["Подумай: «Чему равно (x + 3)²? Откуда берётся слагаемое с x?»","Запиши квадрат как произведение двух скобок. При умножении получаем x · 3 и 3 · x. Вместе они дают 6x."],"flag":{"nopar":true}},{"n":104,"lab":"01.6","blk":"m","cls":7,"topic":"Формулы сокращённого умножения","err":"Путает разность квадратов и квадрат разности","type":"sub","q":"<p>Разложи на множители.</p><ol class=\"subq\"><li>a² − 16</li><li>9y² − 1</li><li>25 − 4x²</li></ol>","subs":[{"k":"e","v":"(a − 4)(a + 4)","var":[],"show":"(a − 4)(a + 4)"},{"k":"e","v":"(3y − 1)(3y + 1)","var":[],"show":"(3y − 1)(3y + 1)"},{"k":"e","v":"(5 − 2x)(5 + 2x)","var":[],"show":"(5 − 2x)(5 + 2x)"}],"sym":"²","h":["Подумай: «Как разложить x² − 25? Что получится, если раскрыть (x − 5)²?»","Покажи, что 25 = 5². В произведении (x − 5)(x + 5) члены 5x и −5x уничтожаются. В квадрате (x − 5)² они оба равны −5x."],"flag":{"par":true}},{"n":105,"lab":"03.3","blk":"m","cls":7,"topic":"Линейная функция","err":"Ставит b на ось x","type":"sub","q":"<p>Найди точку пересечения с осью y.</p><ol class=\"subq\"><li>y = x − 2</li><li>y = −3x + 1</li><li>y = 4x</li></ol>","subs":[{"k":"t","v":["(0; −2)","0; −2"],"show":"(0; −2)"},{"k":"t","v":["(0; 1)","0; 1"],"show":"(0; 1)"},{"k":"t","v":["(0; 0)","0; 0"],"show":"(0; 0)"}],"sym":"","h":["Подумай: «Где график y = 2x + 3 пересекает ось y? Чему там равен x?»","У каждой точки на оси y первая координата равна нулю. Подставляем x = 0 и получаем y = 3. Записываем (0; 3)."]},{"n":106,"lab":"03.4","blk":"m","cls":7,"topic":"Линейная функция","err":"По знаку b судит, растёт ли график","type":"sub","q":"<p>Определи, возрастает или убывает функция.</p><ol class=\"subq\"><li>y = 2x − 5</li><li>y = −x + 7</li><li>y = −3x − 4</li></ol>","subs":[{"k":"t","v":["Возрастает"],"show":"Возрастает"},{"k":"t","v":["Убывает"],"show":"Убывает"},{"k":"t","v":["Убывает"],"show":"Убывает"}],"sym":"","h":["Подумай: «Куда идёт график y = −2x + 3 слева направо?»","Сравни y при x = 0 и x = 1: было 3, стало 1. При шаге вправо на 1 значение y меняется на k. Здесь k = −2."]},{"n":107,"lab":"03.5","blk":"m","cls":7,"topic":"Смежные и вертикальные углы","err":"Приравнивает смежные углы","type":"sub","q":"<p>Найди смежный угол.</p><ol class=\"subq\"><li>Первый угол 40°</li><li>Первый угол 125°</li><li>Первый угол 89°</li></ol>","subs":[{"k":"e","v":"140","var":[],"show":"140°"},{"k":"e","v":"55","var":[],"show":"55°"},{"k":"e","v":"91","var":[],"show":"91°"}],"sym":"°","h":["Подумай: «Угол AOB равен 65°. Чему равен смежный с ним угол BOC?»","У этих углов общая сторона OB. Лучи OA и OC образуют прямую. На два угла приходится 180°, поэтому 180° − 65° = 115°."]},{"n":108,"lab":"03.6","blk":"m","cls":7,"topic":"Смежные и вертикальные углы","err":"Вычитает вертикальный угол из 180°","type":"sub","q":"<p>Найди вертикальный угол.</p><ol class=\"subq\"><li>Первый угол 32°</li><li>Первый угол 117°</li><li>Первый угол 90°</li></ol>","subs":[{"k":"e","v":"32","var":[],"show":"32°"},{"k":"e","v":"117","var":[],"show":"117°"},{"k":"e","v":"90","var":[],"show":"90°"}],"sym":"°","h":["Подумай: «На рисунке угол AOB равен 48°. Чему равен угол COD?»","Углы AOB и COD лежат друг против друга при пересечении прямых AC и BD. Вертикальные углы равны: ∠COD = 48°."]},{"n":109,"lab":"05.2","blk":"m","cls":7,"topic":"Степени","err":"Перемножает показатели при умножении","type":"sub","q":"<p>Запиши одной степенью.</p><ol class=\"subq\"><li>3² · 3⁴</li><li>5³ · 5²</li><li>7 · 7³</li></ol>","subs":[{"k":"e","v":"3⁶","var":[],"show":"3⁶"},{"k":"e","v":"5⁵","var":[],"show":"5⁵"},{"k":"e","v":"7⁴","var":[],"show":"7⁴"}],"sym":"²³","h":["Подумай: «Как записать 2³ · 2² одной степенью числа 2?»","Распиши степени как произведения. В первой три двойки, во второй ещё две. При умножении степеней с одинаковым основанием показатели складываем."],"flag":{"pow":true}},{"n":110,"lab":"06.1","blk":"m","cls":7,"topic":"Системы линейных уравнений","err":"При подстановке теряет скобки","type":"sub","q":"<p>Подставь выражение и раскрой скобки.</p><ol class=\"subq\"><li>2y, y = x + 4</li><li>5y, y = x − 1</li><li>−2y, y = x + 3</li></ol>","subs":[{"k":"e","v":"2x + 8","var":[],"show":"2x + 8"},{"k":"e","v":"5x − 5","var":[],"show":"5x − 5"},{"k":"e","v":"−2x − 6","var":[],"show":"−2x − 6"}],"sym":"","h":["Подумай: «Если y = x + 2, как записать 3y через x?»","Тройка умножается на всё выражение x + 2. Сначала подставляем его в скобках, затем раскрываем их."]},{"n":111,"lab":"06.2","blk":"m","cls":7,"topic":"Системы линейных уравнений","err":"Проверяет пару только в одном уравнении","type":"sub","q":"<p>Проверь пары для системы x + y = 5 и x − y = 1.</p><ol class=\"subq\"><li>(4; 1)</li><li>(3; 2)</li><li>(2; 1)</li></ol>","subs":[{"k":"t","v":["Нет: разность 3","Нет"],"show":"Нет: разность 3"},{"k":"t","v":["Да: сумма 5, разность 1","Да"],"show":"Да: сумма 5, разность 1"},{"k":"t","v":["Нет: сумма 3","Нет"],"show":"Нет: сумма 3"}],"sym":"","h":["Подумай: «Подходит ли (3; 1) для системы x + y = 4 и x − y = 1?»","Подставляем x = 3 и y = 1 в каждое уравнение. Пара решает систему, если оба равенства верны."]},{"n":112,"lab":"08.1","blk":"m","cls":7,"topic":"Линейные уравнения","err":"Меняет сторону равенства, но сохраняет знак","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li>2x + 7 = 15</li><li>5x − 3 = 12</li><li>4x + 9 = 1</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"−2","var":[],"show":"−2"}],"sym":"","h":["Подумай: «Как убрать +5 из левой части уравнения 3x + 5 = 17?»","Вычитаем 5 из обеих частей. Слева +5 и −5 дают ноль. Справа остаётся 17 − 5. Затем делим обе части на 3."]},{"n":113,"lab":"08.2","blk":"m","cls":7,"topic":"Линейные уравнения","err":"При раскрытии скобок умножает только x","type":"sub","q":"<p>Раскрой скобки и реши уравнение.</p><ol class=\"subq\"><li>3(x + 2) = 15</li><li>5(x − 1) = 20</li><li>2(3x + 4) = 20</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"2","var":[],"show":"2"}],"sym":"","h":["Подумай: «Раскрой скобки в 2(x + 3) = 14. Во что превратится 3?»","Число 2 умножается на каждое слагаемое в скобках. Получаем 2x + 6 = 14. После вычитания 6 остаётся 2x = 8."],"flag":{"nopar":true}},{"n":114,"lab":"09.5","blk":"m","cls":7,"topic":"Параллельные прямые и секущая","err":"Складывает накрест лежащие углы","type":"sub","q":"<p>Найди второй накрест лежащий угол.</p><ol class=\"subq\"><li>Первый угол 40°</li><li>Первый угол 75°</li><li>Первый угол 112°</li></ol>","subs":[{"k":"e","v":"40","var":[],"show":"40°"},{"k":"e","v":"75","var":[],"show":"75°"},{"k":"e","v":"112","var":[],"show":"112°"}],"sym":"°","h":["Подумай: «На рисунке a ∥ b. Один отмеченный угол равен 55°. А второй?»","Углы лежат между параллельными прямыми по разные стороны от секущей. Это накрест лежащие углы. При параллельных прямых такие углы равны."]},{"n":115,"lab":"09.6","blk":"m","cls":7,"topic":"Параллельные прямые и секущая","err":"Приравнивает односторонние углы","type":"sub","q":"<p>Найди второй односторонний угол.</p><ol class=\"subq\"><li>Первый угол 30°</li><li>Первый угол 72°</li><li>Первый угол 137°</li></ol>","subs":[{"k":"e","v":"150","var":[],"show":"150°"},{"k":"e","v":"108","var":[],"show":"108°"},{"k":"e","v":"43","var":[],"show":"43°"}],"sym":"°","h":["Подумай: «На рисунке a ∥ b. Один отмеченный угол равен 55°. А второй?»","Углы лежат между параллельными прямыми по одну сторону от секущей. Это односторонние углы. Их сумма равна 180°, поэтому второй угол равен 125°."]},{"n":116,"lab":"10.1","blk":"m","cls":7,"topic":"Чтение графиков","err":"Считывает x вместо значения функции","type":"sub","q":"<p>Найди значения функции по графику.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"40.0 -5.6 149.1 76.8\" width=\"300\" height=\"154\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M54.9,49.0 L170.6,49.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M64.0,53.0 L64.0,5.8\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M90.0,51.0 L90.0,47.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M116.0,51.0 L116.0,47.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M142.0,51.0 L142.0,47.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.0,40.0 L66.0,40.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.0,31.0 L66.0,31.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.0,22.0 L66.0,22.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.0,13.0 L66.0,13.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M59.6,41.5 L157.6,7.6\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"175.0\" y=\"51.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">x</text><text x=\"70.0\" y=\"11.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">y</text><text x=\"55.0\" y=\"58.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">0</text><text x=\"85.0\" y=\"61.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">1</text><text x=\"111.0\" y=\"61.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">2</text><text x=\"137.0\" y=\"61.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">3</text><text x=\"49.0\" y=\"36.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">1</text><text x=\"49.0\" y=\"27.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">2</text><text x=\"49.0\" y=\"18.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">3</text><text x=\"49.0\" y=\"9.0\" font-size=\"8.5\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">4</text></svg></div><ol class=\"subq\"><li>f(1)</li><li>f(2)</li><li>f(3)</li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"","h":["Подумай: «На рисунке отмечена точка (2; 3). Чему равно f(2)?»","На горизонтальной оси находим 2 и поднимаемся к графику. От точки идём влево к оси y и читаем высоту: 3. В записи f(2) число 2 задаёт x, а значение функции равно 3."]},{"n":117,"lab":"10.3","blk":"m","cls":7,"topic":"Многочлены","err":"Складывает слагаемые с разными степенями","type":"sub","q":"<p>Приведи подобные слагаемые.</p><ol class=\"subq\"><li>5x² + 2x + x²</li><li>3a + 4a² − a</li><li>7y² + y − 2y²</li></ol>","subs":[{"k":"e","v":"6x² + 2x","var":[],"show":"6x² + 2x"},{"k":"e","v":"4a² + 2a","var":[],"show":"4a² + 2a"},{"k":"e","v":"5y² + y","var":[],"show":"5y² + y"}],"sym":"²","h":["Подумай: «Можно ли упростить 2x² + 3x до 5x²?»","При x = 2 выражение 2x² + 3x равно 14, а 5x² равно 20. Собираем подобные слагаемые: их буквенные части совпадают, включая степени. Меняются только коэффициенты."],"flag":{"nopar":true}},{"n":118,"lab":"10.4","blk":"m","cls":7,"topic":"Многочлены","err":"При умножении пропускает часть произведений","type":"sub","q":"<p>Перемножь скобки и приведи подобные.</p><ol class=\"subq\"><li>(x + 1)(x + 4)</li><li>(x + 2)(x − 3)</li><li>(x − 1)(x − 5)</li></ol>","subs":[{"k":"e","v":"x² + 5x + 4","var":[],"show":"x² + 5x + 4"},{"k":"e","v":"x² − x − 6","var":[],"show":"x² − x − 6"},{"k":"e","v":"x² − 6x + 5","var":[],"show":"x² − 6x + 5"}],"sym":"²","h":["Подумай: «Что получится, если умножить (x + 2) на (x + 3)?»","Сначала умножь x из первой скобки на оба слагаемых второй скобки. Затем сделай то же самое с числом 2. Получаются четыре произведения. Собери подобные."],"flag":{"nopar":true}},{"n":119,"lab":"10.5","blk":"m","cls":7,"topic":"Медиана и биссектриса треугольника","err":"Делит угол пополам, когда дана медиана","type":"sub","q":"<p>AM — медиана. Найди длину отрезка.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"9.0 -13.6 179.6 85.3\" width=\"300\" height=\"143\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M30.0,49.0 L95.0,8.0 L168.0,49.0 L30.0,49.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M95.0,8.0 L99.0,49.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.5,52.0 L66.5,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M131.5,52.0 L135.5,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"88.0\" y=\"3.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"18.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"173.0\" y=\"53.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"92.0\" y=\"61.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">M</text></svg></div><ol class=\"subq\"><li>BC = 18. Найди BM</li><li>MC = 7. Найди BC</li><li>BM = 5. Найди MC</li></ol>","subs":[{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"14","var":[],"show":"14"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «AM — медиана треугольника ABC. Что она делит пополам?»","Медиана соединяет вершину с серединой противоположной стороны. Точка M лежит на BC, поэтому BM = MC. Равные отрезки на чертеже отмечаем одинаковыми штрихами."]},{"n":120,"lab":"10.6","blk":"m","cls":7,"topic":"Медиана и биссектриса треугольника","err":"Делит сторону пополам, когда дана биссектриса","type":"sub","q":"<p>AD — биссектриса. Найди угол.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"9.0 -13.6 179.6 85.3\" width=\"300\" height=\"143\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M30.0,49.0 L95.0,8.0 L168.0,49.0 L30.0,49.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M95.0,8.0 L96.0,49.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M84.4,15.5 C86.7,18.8 90.6,20.9 94.7,21.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M96.0,21.0 C100.1,20.6 103.8,18.4 106.0,15.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"88.0\" y=\"3.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"18.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"173.0\" y=\"53.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"89.0\" y=\"61.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>∠A = 78°. ∠BAD = ?</li><li>∠DAC = 22°. ∠A = ?</li><li>∠BAD = 37°. ∠DAC = ?</li></ol>","subs":[{"k":"e","v":"39","var":[],"show":"39°"},{"k":"e","v":"44","var":[],"show":"44°"},{"k":"e","v":"37","var":[],"show":"37°"}],"sym":"°","h":["Подумай: «AD — биссектриса угла A. Что она делит пополам?»","Биссектриса делит угол A на два равных угла. На рисунке эти углы отмечены одинаковыми дугами. Из определения следует ∠BAD = ∠DAC."]},{"n":121,"lab":"14.5","blk":"m","cls":7,"topic":"Углы треугольника","err":"Прибавляет два угла и принимает сумму за третий","type":"sub","q":"<p>Найди третий угол по двум известным.</p><ol class=\"subq\"><li>40° и 55°</li><li>25° и 90°</li><li>32° и 58°</li></ol>","subs":[{"k":"e","v":"85","var":[],"show":"85°"},{"k":"e","v":"65","var":[],"show":"65°"},{"k":"e","v":"90","var":[],"show":"90°"}],"sym":"°","h":["Подумай: «В треугольнике углы A и B равны 45° и 65°. Чему равен C?»","Все три угла треугольника в сумме дают 180°. Два известных угла занимают 110°. На третий остаётся 70°."]},{"n":122,"lab":"14.6","blk":"m","cls":7,"topic":"Углы треугольника","err":"Путает смежный угол с удалёнными углами","type":"sub","q":"<p>Найди угол B по внешнему углу при C и углу A.</p><ol class=\"subq\"><li>130° и 50°</li><li>100° и 35°</li><li>150° и 80°</li></ol>","subs":[{"k":"e","v":"80","var":[],"show":"80°"},{"k":"e","v":"65","var":[],"show":"65°"},{"k":"e","v":"70","var":[],"show":"70°"}],"sym":"°","h":["Подумай: «При вершине C внешний угол 120°. Угол A равен 45°. Найди B».","Внешний угол при C равен сумме двух внутренних углов, которые с ним не смежны: A и B. Поэтому B = 120° − 45°. Внутренний угол C смежный с внешним и равен 60°."]},{"n":123,"lab":"15.3","blk":"m","cls":7,"topic":"Медиана и среднее арифметическое","err":"Ищет медиану без сортировки","type":"sub","q":"<p>Найди медиану.</p><ol class=\"subq\"><li>9, 1, 4</li><li>7, 3, 6, 2, 1</li><li>5, 10, 2, 3, 8</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Какова медиана ряда 8, 2, 5? Какое число стоит посередине?»","Сначала расположи числа по возрастанию: 2, 5, 8. Теперь бери число, которое оказалось посередине. В ряду из трёх чисел это второе число."]},{"n":124,"lab":"15.4","blk":"m","cls":7,"topic":"Медиана и среднее арифметическое","err":"Делит сумму на число разных значений","type":"sub","q":"<p>Найди среднее арифметическое.</p><ol class=\"subq\"><li>1, 1, 4</li><li>3, 3, 7, 7</li><li>2, 2, 2, 10</li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"","h":["Подумай: «Какое среднее арифметическое у чисел 2, 2, 8?»","В сумме учитываем каждое число, включая повторения. Число 2 записано дважды, всего в ряду три числа. Поэтому делим сумму 12 на 3 и получаем 4."]},{"n":125,"lab":"15.5","blk":"m","cls":7,"topic":"Признаки равенства треугольников","err":"Берёт любой угол при двух равных сторонах","type":"sub","q":"<p>Назови угол между указанными сторонами.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"6.0 -11.6 145.6 72.3\" width=\"300\" height=\"149\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M26.0,46.0 L131.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M67.0,11.0 L26.0,46.0 M67.0,11.0 L131.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M57.9,18.8 C60.4,21.8 64.3,23.3 68.2,22.9 C72.2,22.5 75.6,20.2 77.5,16.8\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"59.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"15.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"136.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>AB и BC</li><li>AC и BC</li><li>AB и AC</li></ol>","subs":[{"k":"t","v":["∠ABC"],"show":"∠ABC"},{"k":"t","v":["∠ACB"],"show":"∠ACB"},{"k":"t","v":["∠BAC"],"show":"∠BAC"}],"sym":"","h":["Подумай: «Даны стороны AB и AC. Какой угол нужен для первого признака?»","Стороны AB и AC встречаются в вершине A. Для первого признака проверяем равенство двух сторон и угла между ними. Здесь это угол A, или ∠BAC."]},{"n":126,"lab":"15.6","blk":"m","cls":7,"topic":"Признаки равенства треугольников","err":"Считает равные углы признаком равенства","type":"sub","q":"<p>Достаточно ли этих совпадающих данных для равенства?.</p><ol class=\"subq\"><li>Стороны 3, 4, 5</li><li>Три равных угла</li><li>Стороны 5, 5, 6</li></ol>","subs":[{"k":"t","v":["Да, по трём сторонам","Да"],"show":"Да, по трём сторонам"},{"k":"t","v":["Нет, данных мало","Нет"],"show":"Нет, данных мало"},{"k":"t","v":["Да, по трём сторонам","Да"],"show":"Да, по трём сторонам"}],"sym":"","h":["Подумай: «У двух треугольников углы 30°, 60° и 90°. Равны ли они?»","Равные углы дают подобие. Размеры могут различаться. На рисунке второй треугольник получен увеличением первого. Углы сохранились, а длины сторон изменились."]},{"n":127,"lab":"21.3","blk":"m","cls":7,"topic":"Графическое решение уравнений","err":"Записывает ординату точки как корень","type":"sub","q":"<p>Найди корень по точке пересечения графиков.</p><ol class=\"subq\"><li>Точка (1; 3)</li><li>Точка (−2; 5)</li><li>Точка (0; −3)</li></ol>","subs":[{"k":"e","v":"1","var":[],"show":"1"},{"k":"e","v":"−2","var":[],"show":"−2"},{"k":"e","v":"0","var":[],"show":"0"}],"sym":"","h":["Подумай: «Графики пересекаются в (2; 3). Какое число будет корнем?»","В точке пересечения значения двух выражений совпадают. Для решения уравнения берём абсциссу, то есть x. В примере корень равен 2."]},{"n":128,"lab":"22.5","blk":"m","cls":7,"topic":"Равнобедренный треугольник","err":"Приравнивает угол при основании к углу при вершине","type":"sub","q":"<p>Найди угол B, если AB = AC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"15.0 -15.6 169.6 76.3\" width=\"300\" height=\"135\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M100.0,8.0 L35.0,46.0 M100.0,8.0 L165.0,46.0 M35.0,46.0 L165.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M65.0,31.0 L69.0,23.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M131.0,31.0 L135.0,23.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"90.0\" y=\"1.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"24.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"169.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>∠A = 30°</li><li>∠A = 80°</li><li>∠A = 120°</li></ol>","subs":[{"k":"e","v":"75","var":[],"show":"75°"},{"k":"e","v":"50","var":[],"show":"50°"},{"k":"e","v":"30","var":[],"show":"30°"}],"sym":"°","h":["Подумай: «В треугольнике AB = AC, угол A равен 40°. Чему равен B?»","Основание — сторона BC. Углы B и C при основании равны. На них вместе приходится 180° − 40° = 140°. Каждый из этих двух углов равен 70°."]},{"n":129,"lab":"22.6","blk":"m","cls":7,"topic":"Равнобедренный треугольник","err":"Выбирает равные стороны рядом с равными углами","type":"sub","q":"<p>Назови равные стороны.</p><ol class=\"subq\"><li>∠A = ∠B</li><li>∠B = ∠C</li><li>∠A = ∠C</li></ol>","subs":[{"k":"t","v":["BC = AC"],"show":"BC = AC"},{"k":"t","v":["AC = AB"],"show":"AC = AB"},{"k":"t","v":["BC = AB"],"show":"BC = AB"}],"sym":"","h":["Подумай: «Углы B и C равны. Какие стороны треугольника равны?»","Равные углы лежат напротив равных сторон. Напротив B лежит AC, напротив C лежит AB. Следовательно, AC = AB, а BC — основание."]},{"n":130,"lab":"23.3","blk":"m","cls":7,"topic":"Разложение на множители","err":"Теряет единицу после вынесения множителя","type":"sub","q":"<p>Вынеси общий множитель.</p><ol class=\"subq\"><li>2a² + 2a</li><li>5b³ − 5b</li><li>4y⁴ + 4y²</li></ol>","subs":[{"k":"e","v":"2a(a + 1)","var":[],"show":"2a(a + 1)"},{"k":"e","v":"5b(b² − 1)","var":[],"show":"5b(b² − 1)"},{"k":"e","v":"4y²(y² + 1)","var":[],"show":"4y²(y² + 1)"}],"sym":"²³","h":["Подумай: «Когда выносим 3x из 3x² + 3x, что останется от 3x?»","Каждое слагаемое делим на общий множитель 3x. От первого остаётся x, от второго — 1, потому что 3x = 3x · 1. Проверяем раскрытием скобок."],"flag":{"par":true}},{"n":131,"lab":"23.4","blk":"m","cls":7,"topic":"Разложение на множители","err":"После группировки складывает скобки","type":"sub","q":"<p>Разложи на множители группировкой.</p><ol class=\"subq\"><li>ax + ay + 2x + 2y</li><li>mx − my + 3x − 3y</li><li>ax + 2a − bx − 2b</li></ol>","subs":[{"k":"e","v":"(a + 2)(x + y)","var":[],"show":"(a + 2)(x + y)"},{"k":"e","v":"(m + 3)(x − y)","var":[],"show":"(m + 3)(x − y)"},{"k":"e","v":"(a − b)(x + 2)","var":[],"show":"(a − b)(x + 2)"}],"sym":"","h":["Подумай: «Как разложить на множители ax + ay + bx + by?»","Из первых двух слагаемых выносим a, из последних двух b. Получаем a(x + y) + b(x + y). Теперь общим множителем служит вся скобка x + y. Она записывается один раз."],"flag":{"par":true}},{"n":132,"lab":"25.1","blk":"m","cls":7,"topic":"Нулевая и отрицательная степени","err":"Считает, что нулевая степень равна нулю","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>7⁰</li><li>(−3)⁰</li><li>2 · 9⁰</li></ol>","subs":[{"k":"e","v":"1","var":[],"show":"1"},{"k":"e","v":"1","var":[],"show":"1"},{"k":"e","v":"2","var":[],"show":"2"}],"sym":"","h":["Подумай: «Чему равно 5⁰? Что получится, если разделить 5³ на 5³?»","При делении одинаковых ненулевых чисел получаем 1. Чтобы правило вычитания показателей работало и при одинаковых степенях, полагаем 5⁰ = 1. В общем: a⁰ = 1 при a ≠ 0."]},{"n":133,"lab":"26.1","blk":"m","cls":7,"topic":"Неравенство треугольника","err":"Сравнивает сумму сторон с короткой стороной","type":"sub","q":"<p>Можно ли построить треугольник?.</p><ol class=\"subq\"><li>2, 5, 8</li><li>4, 5, 7</li><li>3, 3, 7</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «Можно ли построить треугольник со сторонами 3, 4 и 8?»","Проверяем сумму двух меньших сторон: 3 + 4 = 7. Она должна быть больше самой длинной стороны. Здесь 7 &lt; 8, поэтому треугольник построить нельзя."]},{"n":134,"lab":"26.2","blk":"m","cls":7,"topic":"Неравенство треугольника","err":"Допускает равенство в неравенстве треугольника","type":"sub","q":"<p>Можно ли построить треугольник?.</p><ol class=\"subq\"><li>2, 3, 5</li><li>4, 5, 8</li><li>6, 7, 13</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «Получится ли треугольник со сторонами 3, 4 и 7?»","Если 3 + 4 = 7, короткие отрезки можно соединить только вдоль длинного. Все три вершины окажутся на одной прямой. Для треугольника сумма должна быть строго больше 7."]},{"n":135,"lab":"29.3","blk":"m","cls":7,"topic":"Деление степеней","err":"Вычитает показатели при разных основаниях","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>4³ : 2⁴</li><li>9² : 3³</li><li>8² : 2⁵</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"2","var":[],"show":"2"}],"sym":"²³","h":["Подумай: «Можно ли записать 6⁴ : 3² как 6²? Как переписать 6⁴?»","Вычитаем показатели только у степеней с одинаковым основанием. Здесь 6⁴ = (2 · 3)⁴ = 2⁴ · 3⁴. Сокращаем степени числа 3. Получаем 2⁴ · 3² = 144."]},{"n":136,"lab":"29.4","blk":"m","cls":7,"topic":"Деление степеней","err":"Делит показатели при одинаковых основаниях","type":"sub","q":"<p>Упрости при a ≠ 0.</p><ol class=\"subq\"><li>a⁹ : a³</li><li>a⁷ : a²</li><li>a¹⁰ : a⁴</li></ol>","subs":[{"k":"e","v":"a⁶","var":[],"show":"a⁶"},{"k":"e","v":"a⁵","var":[],"show":"a⁵"},{"k":"e","v":"a⁶","var":[],"show":"a⁶"}],"sym":"²³≠","h":["Подумай: «Чему равно a⁸ : a² при a ≠ 0? Почему показатель не 4?»","В числителе восемь множителей a, в знаменателе два. Сокращаем два одинаковых множителя. Остаётся шесть. При делении степеней с одинаковым основанием вычитаем показатели."]},{"n":137,"lab":"33.3","blk":"m","cls":7,"topic":"Уравнения с произведением","err":"Требует, чтобы обе скобки равнялись нулю","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li>(x − 1)(x + 4) = 0</li><li>(x + 2)(x − 5) = 0</li><li>(x + 6)(x + 3) = 0</li></ol>","subs":[{"k":"set","v":["−4","1"],"show":"−4 и 1"},{"k":"set","v":["−2","5"],"show":"−2 и 5"},{"k":"set","v":["−6","−3"],"show":"−6 и −3"}],"sym":"","h":["Подумай: «Подходит ли x = 2 для (x − 2)(x + 3) = 0?»","При x = 2 первая скобка равна нулю, вторая равна 5. Чтобы произведение равнялось нулю, достаточно одного нулевого множителя. Проверяем каждую скобку отдельно."]},{"n":138,"lab":"33.5","blk":"m","cls":7,"topic":"Высоты треугольника","err":"Ищет основание высоты только на стороне","type":"sub","q":"<p>Ответь по рисунку.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"14.0 -5.6 134.6 71.3\" width=\"296\" height=\"157\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M33.0,44.0 L90.0,44.0 L129.0,13.0 L33.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M90.0,44.0 L129.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-dasharray=\"4 3\"/><path d=\"M129.0,44.0 L129.0,13.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M124.0,44.0 L124.0,39.0 L129.0,39.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"133.0\" y=\"53.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">H</text><text x=\"23.0\" y=\"52.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"87.0\" y=\"55.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"133.0\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>Куда продолжить AB?</li><li>Назови высоту из C</li><li>Чему равен угол BHC?</li></ol>","subs":[{"k":"t","v":["За B"],"show":"За B"},{"k":"t","v":["CH"],"show":"CH"},{"k":"e","v":"90","var":[],"show":"90°"}],"sym":"°","h":["Подумай: «На рисунке угол B тупой. Где основание высоты из C к AB?»","Высота проходит через вершину C перпендикулярно прямой AB. Продлеваем AB за B и опускаем перпендикуляр. Его основание H лежит на продолжении стороны."]},{"n":139,"lab":"33.6","blk":"m","cls":7,"topic":"Высоты треугольника","err":"Проводит высоту к катету внутри треугольника","type":"sub","q":"<p>Назови высоту из указанной вершины.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"14.0 -5.6 95.6 71.3\" width=\"210\" height=\"157\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M33.0,44.0 L90.0,44.0 L90.0,13.0 L33.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M90.0,44.0 L90.0,13.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M85.0,44.0 L85.0,39.0 L90.0,39.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"23.0\" y=\"52.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"87.0\" y=\"55.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"94.0\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>Из C к AB</li><li>Из A к BC</li><li>Из B к AC</li></ol>","subs":[{"k":"t","v":["CB"],"show":"CB"},{"k":"t","v":["AB"],"show":"AB"},{"k":"t","v":["Перпендикуляр из B к AC"],"show":"Перпендикуляр из B к AC"}],"sym":"","h":["Подумай: «В ABC угол B прямой. Какой отрезок служит высотой из C к AB?»","Стороны AB и BC перпендикулярны. Поэтому катет CB уже является высотой, проведённой из C к стороне AB. Её основание — точка B."]},{"n":140,"lab":"36.5","blk":"m","cls":7,"topic":"Равносторонний треугольник","err":"Путает угол с суммой углов","type":"sub","q":"<p>Найди указанные углы и их сумму.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"23.0 -11.8 84.6 72.5\" width=\"186\" height=\"160\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M64.5,10.8 L43.0,48.0 L86.0,48.0 L64.5,10.8\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"57.5\" y=\"4.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"32.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"92.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>∠A</li><li>∠A + ∠B</li><li>Внешний угол при C</li></ol>","subs":[{"k":"e","v":"60","var":[],"show":"60°"},{"k":"e","v":"120","var":[],"show":"120°"},{"k":"e","v":"120","var":[],"show":"120°"}],"sym":"°","h":["Подумай: «Все стороны треугольника равны. Чему равен каждый угол?»","Напротив равных сторон лежат равные углы. Сумма трёх одинаковых углов равна 180°. Поэтому каждый угол равен 60°."]},{"n":141,"lab":"36.6","blk":"m","cls":7,"topic":"Равносторонний треугольник","err":"Считает половину стороны длиной высоты","type":"sub","q":"<p>Найди BM по длине стороны BC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"23.0 -11.8 84.6 83.5\" width=\"186\" height=\"184\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M64.5,10.8 L43.0,48.0 L86.0,48.0 L64.5,10.8\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M64.5,10.8 L64.5,48.0 M64.5,43.0 L69.5,43.0 L69.5,48.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"57.5\" y=\"4.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"32.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"92.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"57.5\" y=\"61.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">M</text></svg></div><ol class=\"subq\"><li>BC = 10 см</li><li>BC = 13 см</li><li>BC = 18 см</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5 см"},{"k":"e","v":"6,5","var":[],"show":"6,5 см"},{"k":"e","v":"9","var":[],"show":"9 см"}],"sym":"","h":["Подумай: «В равностороннем ABC сторона 8 см. AM — высота к BC. Чему равен BM?»","Высота из A в равностороннем треугольнике также медиана. Поэтому половина стороны — это отрезок BM на основании. Получаем BM = 4 см. Длина самой высоты вычисляется отдельно."]},{"n":142,"lab":"37.3","blk":"m","cls":7,"topic":"График прямой пропорциональности","err":"Считает любую прямую графиком пропорциональности","type":"sub","q":"<p>Является ли зависимость прямой пропорциональностью?.</p><ol class=\"subq\"><li>y = 3x + 2</li><li>y = −4x</li><li>y = 2x − 1</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «Какой график проходит через (0; 0): y = 2x или y = 2x + 1?»","Подставляем x = 0. Для y = 2x получаем y = 0. Для y = 2x + 1 получаем y = 1. Поэтому только график y = 2x показывает прямую пропорциональность."]},{"n":143,"lab":"37.4","blk":"m","cls":7,"topic":"График прямой пропорциональности","err":"Делит x на y при поиске коэффициента","type":"sub","q":"<p>Найди k по координатам точки графика y = kx.</p><ol class=\"subq\"><li>(3; 12)</li><li>(4; −8)</li><li>(−2; 10)</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"−2","var":[],"show":"−2"},{"k":"e","v":"−5","var":[],"show":"−5"}],"sym":"","h":["Подумай: «На графике y = kx лежит A(2; 6). Чему равен k?»","Подставляем координаты: 6 = k · 2. Коэффициент показывает, во сколько раз значение y больше x в этом примере. Делим 6 на 2 и получаем 3."]},{"n":144,"lab":"38.3","blk":"m","cls":7,"topic":"Возведение одночлена в степень","err":"Не возводит коэффициент в степень","type":"sub","q":"<p>Возведи одночлен в степень.</p><ol class=\"subq\"><li>(2a)³</li><li>(5b)²</li><li>(−3y)²</li></ol>","subs":[{"k":"e","v":"8a³","var":[],"show":"8a³"},{"k":"e","v":"25b²","var":[],"show":"25b²"},{"k":"e","v":"9y²","var":[],"show":"9y²"}],"sym":"²³","h":["Подумай: «Чему равно (3x)²? Что происходит с тройкой?»","Квадрат означает произведение двух одинаковых множителей. Записываем (3x) · (3x) и собираем числовые множители. Получаем 3 · 3 · x · x = 9x²."],"flag":{"nopar":true}},{"n":145,"lab":"38.4","blk":"m","cls":7,"topic":"Возведение одночлена в степень","err":"Складывает показатели при возведении в степень","type":"sub","q":"<p>Представь в виде степени.</p><ol class=\"subq\"><li>(x²)³</li><li>(b⁵)²</li><li>(y³)⁴</li></ol>","subs":[{"k":"e","v":"x⁶","var":[],"show":"x⁶"},{"k":"e","v":"b¹⁰","var":[],"show":"b¹⁰"},{"k":"e","v":"y¹²","var":[],"show":"y¹²"}],"sym":"²³","h":["Подумай: «Чему равно (a³)²? Сколько множителей a получится?»","Квадрат даёт две группы по три множителя a. Всего их шесть. При возведении степени в степень показатели перемножаем: 3 · 2 = 6."],"flag":{"nopar":true,"pow":true}},{"n":146,"lab":"40.1","blk":"m","cls":7,"topic":"Углы на клетчатой бумаге","err":"Считает любой наклон к клеткам углом 45°","type":"sub","q":"<p>Сравни угол луча с горизонталью с 45°.</p><ol class=\"subq\"><li>2 вправо, 2 вверх</li><li>3 вправо, 1 вверх</li><li>1 вправо, 3 вверх</li></ol>","subs":[{"k":"t","v":["Равен"],"show":"Равен"},{"k":"t","v":["Меньше"],"show":"Меньше"},{"k":"t","v":["Больше"],"show":"Больше"}],"sym":"°","h":["Подумай: «Луч идёт на 3 клетки вправо и на 3 вверх. Чему равен угол с горизонталью?»","Горизонтальный и вертикальный отрезки образуют катеты. Они равны, поэтому два острых угла тоже равны. Вместе они дают 90°, значит каждый равен 45°."]},{"n":147,"lab":"40.2","blk":"m","cls":7,"topic":"Углы на клетчатой бумаге","err":"Забывает, что вертикаль даёт другой угол","type":"sub","q":"<p>Дан угол луча с горизонталью. Найди острый угол с вертикалью.</p><ol class=\"subq\"><li>Угол 15°</li><li>Угол 40°</li><li>Угол 75°</li></ol>","subs":[{"k":"e","v":"75","var":[],"show":"75°"},{"k":"e","v":"50","var":[],"show":"50°"},{"k":"e","v":"15","var":[],"show":"15°"}],"sym":"°","h":["Подумай: «Угол луча с горизонталью 25°. Каков острый угол с вертикалью?»","Горизонталь и вертикаль перпендикулярны. Внутри прямого угла луч делит 90° на две части. Вторая часть равна 90° − 25° = 65°."]},{"n":148,"lab":"40.3","blk":"m","cls":7,"topic":"Уравнения с дробными коэффициентами","err":"Убирает знаменатели только в одной части","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x</span><span>2</span></span> = <span class=\"fr\"><span>3</span><span>4</span></span></li><li><span class=\"fr\"><span>x</span><span>5</span></span> = <span class=\"fr\"><span>2</span><span>3</span></span></li><li><span class=\"fr\"><span>x</span><span>6</span></span> = <span class=\"fr\"><span>3</span><span>2</span></span></li></ol>","subs":[{"k":"e","v":"3/2","var":[],"show":"3/2"},{"k":"e","v":"10/3","var":[],"show":"10/3"},{"k":"e","v":"9","var":[],"show":"9"}],"sym":"","h":["Подумай: «Что получится из <span class=\"fr\"><span>x</span><span>3</span></span> = <span class=\"fr\"><span>2</span><span>5</span></span>, если умножить равенство на 15?»","Чтобы равенство сохранилось, умножаем обе части. Слева 15 : 3 = 5, поэтому получаем 5x. Справа 15 : 5 = 3, поэтому получаем 3 · 2 = 6."]},{"n":149,"lab":"40.4","blk":"m","cls":7,"topic":"Уравнения с дробными коэффициентами","err":"Пропускает целое слагаемое при умножении","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x</span><span>3</span></span> + 2 = 6</li><li><span class=\"fr\"><span>x</span><span>5</span></span> − 1 = 4</li><li><span class=\"fr\"><span>x</span><span>4</span></span> + 3 = 5</li></ol>","subs":[{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"25","var":[],"show":"25"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «Умножь <span class=\"fr\"><span>x</span><span>4</span></span> + 2 = 5 на 4. Что получится из слагаемого 2?»","Умножаем на 4 каждое слагаемое, включая целые числа. Слева получаем x + 8, справа 20. Вычитаем 8 из обеих частей и получаем x = 12."]},{"n":150,"lab":"43.3","blk":"m","cls":7,"topic":"Метод сложения в системах уравнений","err":"Складывает уравнения с одинаковыми знаками","type":"sub","q":"<p>Реши систему методом сложения.</p><ol class=\"subq\"><li>x+y=6, 2x+y=10</li><li>x+y=7, x+2y=9</li><li>x+y=3, 2x+y=1</li></ol>","subs":[{"k":"t","v":["(4; 2)","4; 2"],"show":"(4; 2)"},{"k":"t","v":["(5; 2)","5; 2"],"show":"(5; 2)"},{"k":"t","v":["(−2; 5)","−2; 5"],"show":"(−2; 5)"}],"sym":"","h":["Подумай: «Чтобы убрать y из уравнений x + y = 5 и 2x + y = 8, что сделать?»","При сложении y + y получится 2y. Чтобы y исчезло, вычитаем первое уравнение из второго: y − y = 0. Получаем x = 3. Подставляем в x + y = 5 и находим y = 2."]},{"n":151,"lab":"43.4","blk":"m","cls":7,"topic":"Метод сложения в системах уравнений","err":"Умножает только левую часть уравнения","type":"sub","q":"<p>Умножь обе части на указанное число.</p><ol class=\"subq\"><li>2x + y = 7, ×3</li><li>x − 2y = 4, ×(−2)</li><li>3x + y = 8, ×2</li></ol>","subs":[{"k":"t","v":["6x + 3y = 21"],"show":"6x + 3y = 21"},{"k":"t","v":["−2x + 4y = −8"],"show":"−2x + 4y = −8"},{"k":"t","v":["6x + 2y = 16"],"show":"6x + 2y = 16"}],"sym":"","h":["Подумай: «Если умножить x + y = 5 на −2, что станет с правой частью?»","Умножаем все слагаемые с обеих сторон равенства. Получаем −2x − 2y = −10. Так можно убрать y при сложении с уравнением, которое содержит +2y."]},{"n":152,"lab":"44.3","blk":"m","cls":7,"topic":"Размах и мода","err":"Принимает наибольшее число за размах","type":"sub","q":"<p>Найди размах ряда.</p><ol class=\"subq\"><li>2, 5, 8, 8</li><li>−3, 1, 4, 4</li><li>12, 7, 9, 10</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"7","var":[],"show":"7"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Каков размах ряда 4, 7, 9, 9? Число 9 уже даёт ответ?»","Размах показывает разницу между крайними значениями. Наибольшее число равно 9, наименьшее равно 4. Вычитаем 4 из 9 и получаем размах 5."]},{"n":153,"lab":"44.4","blk":"m","cls":7,"topic":"Размах и мода","err":"Принимает моду за самое большое число","type":"sub","q":"<p>Найди моду ряда.</p><ol class=\"subq\"><li>1, 1, 6, 8</li><li>3, 3, 5, 5, 9</li><li>2, 4, 8, 8, 8</li></ol>","subs":[{"k":"e","v":"1","var":[],"show":"1"},{"k":"set","v":["3","5"],"show":"3 и 5"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «Какова мода ряда 2, 2, 4, 9? Какое число встречается чаще?»","Мода — значение, которое встречается чаще остальных. Число 2 встречается дважды, а 4 и 9 по одному разу. Если лидируют два значения, обе величины будут модами."]},{"n":154,"lab":"45.5","blk":"m","cls":7,"topic":"Катет напротив угла 30°","err":"Делит гипотенузу пополам для любого катета","type":"sub","q":"<p>Найди катет BC напротив угла 30°.</p><ol class=\"subq\"><li>AC = 10</li><li>AC = 15</li><li>AC = 28</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"7,5","var":[],"show":"7,5"},{"k":"e","v":"14","var":[],"show":"14"}],"sym":"°","h":["Подумай: «Угол A равен 30°, угол B прямой, AC = 14. Чему равен BC?»","Катет BC лежит напротив угла A. Именно катет напротив 30° равен половине гипотенузы. Значит, BC = 14 : 2 = 7."]},{"n":155,"lab":"45.6","blk":"m","cls":7,"topic":"Катет напротив угла 30°","err":"Удваивает катет без проверки угла","type":"sub","q":"<p>В ABC угол B прямой. Можно ли удвоить катет, чтобы найти AC?.</p><ol class=\"subq\"><li>A = 30°, катет BC</li><li>A = 60°, катет BC</li><li>C = 30°, катет AB</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"}],"sym":"°","h":["Подумай: «Угол B прямой, A = 60°, BC = 5. Верно ли AC = 2 · BC?»","Напротив A лежит катет BC, а угол A равен 60°. Угол C равен 30°. Напротив него лежит катет AB. Поэтому гипотенуза AC вдвое длиннее AB."]},{"n":156,"lab":"47.2","blk":"m","cls":7,"topic":"Вычисления по формуле","err":"Делит раньше, чем убирает слагаемое","type":"sub","q":"<p>Найди x по формуле y = 3x + 5.</p><ol class=\"subq\"><li>y = 11</li><li>y = 26</li><li>y = 32</li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"7","var":[],"show":"7"},{"k":"e","v":"9","var":[],"show":"9"}],"sym":"","h":["Подумай: «В формуле y = 3x + 5 известно y = 20. Чему равен x?»","Подставляем 20 вместо y. Чтобы оставить 3x, вычитаем 5 из обеих частей. Затем делим на 3. Получаем x = 5. Проверка: 3 · 5 + 5 = 20."]},{"n":157,"lab":"47.3","blk":"m","cls":7,"topic":"Линейная модель тарифа","err":"Умножает фиксированную плату на число часов","type":"sub","q":"<p>Найди плату за вход и время игры.</p><ol class=\"subq\"><li>1 час</li><li>4 часа</li><li>6 часов</li></ol>","subs":[{"k":"e","v":"140","var":[],"show":"140 ₽"},{"k":"e","v":"260","var":[],"show":"260 ₽"},{"k":"e","v":"340","var":[],"show":"340 ₽"}],"sym":"","h":["Подумай: «Вход стоит 100 ₽, каждый час игры 40 ₽. Какова цена за 3 часа?»","Сто рублей платим один раз за вход. Плата за время равна 40 · 3. Складываем эти суммы. Для t часов получаем C = 100 + 40t."]},{"n":158,"lab":"47.4","blk":"m","cls":7,"topic":"Линейная модель тарифа","err":"Сравнивает тарифы только по цене часа","type":"sub","q":"<p>Выбери более дешёвый тариф из примера.</p><ol class=\"subq\"><li>3 часа</li><li>4 часа</li><li>5 часов</li></ol>","subs":[{"k":"t","v":["Тариф B"],"show":"Тариф B"},{"k":"t","v":["Тариф A"],"show":"Тариф A"},{"k":"t","v":["Тариф A"],"show":"Тариф A"}],"sym":"","h":["Подумай: «A: 100 ₽ за вход и 20 ₽/ч. B: 50 ₽/ч без входа. Что дешевле за 2 ч?»","На тарифе A за два часа заплатим 100 + 40 = 140 ₽. На тарифе B заплатим 50 · 2 = 100 ₽. Сравниваем полные суммы для одного и того же времени."]},{"n":159,"lab":"49.1","blk":"m","cls":7,"topic":"Комбинаторика","err":"Складывает число вариантов двух выборов","type":"sub","q":"<p>Найди число комплектов из одной вещи каждого вида.</p><ol class=\"subq\"><li>2 кофты, 4 юбки</li><li>3 рубашки, 5 брюк</li><li>4 топа, 2 пары шорт</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «Есть 3 футболки и 2 пары брюк. Сколько комплектов?»","С каждой из трёх футболок можно надеть любую из двух пар брюк. Получаем три группы по два комплекта."]},{"n":160,"lab":"49.3","blk":"m","cls":7,"topic":"Число решений системы по графикам","err":"Ищет пересечение у разных параллельных прямых","type":"sub","q":"<p>Определи число решений системы.</p><ol class=\"subq\"><li>y = x и y = x + 2</li><li>y = −x и y = −x − 1</li><li>y = 3x и y = 3x + 5</li></ol>","subs":[{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"0","var":[],"show":"0"}],"sym":"","h":["Подумай: «Сколько решений у системы y = 2x + 1 и y = 2x − 3?»","Коэффициент при x одинаков, поэтому наклон один и тот же. Свободные члены разные. Это две разные параллельные прямые. Общих точек нет, значит, решений нет."]},{"n":161,"lab":"49.4","blk":"m","cls":7,"topic":"Число решений системы по графикам","err":"Считает совпадающие прямые одним решением","type":"sub","q":"<p>Определи число решений системы.</p><ol class=\"subq\"><li>y = x и 2y = 2x</li><li>y = x и y = x + 1</li><li>y = x и y = 2x</li></ol>","subs":[{"k":"t","v":["Бесконечно много"],"show":"Бесконечно много"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"1","var":[],"show":"1"}],"sym":"","h":["Подумай: «Даны y = x + 1 и 2y = 2x + 2. Сколько решений у системы?»","Делим второе уравнение на 2. Получаем первое уравнение. Графики совпадают. Каждая точка этой прямой решает оба уравнения. Таких точек бесконечно много."]},{"n":162,"lab":"50.3","blk":"m","cls":7,"topic":"Сумма и разность кубов","err":"Принимает сумму кубов за куб суммы","type":"sub","q":"<p>Разложи сумму кубов на множители.</p><ol class=\"subq\"><li>x³ + 27</li><li>a³ + 1</li><li>y³ + 64</li></ol>","subs":[{"k":"e","v":"(x + 3)(x² − 3x + 9)","var":[],"show":"(x + 3)(x² − 3x + 9)"},{"k":"e","v":"(a + 1)(a² − a + 1)","var":[],"show":"(a + 1)(a² − a + 1)"},{"k":"e","v":"(y + 4)(y² − 4y + 16)","var":[],"show":"(y + 4)(y² − 4y + 16)"}],"sym":"²³","h":["Подумай: «Верно ли x³ + 8 = (x + 2)³? Проверь при x = 1».","При x = 1 левая часть равна 9, а правая 27. Сумма кубов раскладывается иначе: во второй скобке стоят квадрат первого, минус произведение и квадрат второго."],"flag":{"par":true}},{"n":163,"lab":"50.4","blk":"m","cls":7,"topic":"Сумма и разность кубов","err":"Ставит минус в обеих скобках разности кубов","type":"sub","q":"<p>Разложи разность кубов на множители.</p><ol class=\"subq\"><li>x³ − 8</li><li>a³ − 1</li><li>y³ − 64</li></ol>","subs":[{"k":"e","v":"(x − 2)(x² + 2x + 4)","var":[],"show":"(x − 2)(x² + 2x + 4)"},{"k":"e","v":"(a − 1)(a² + a + 1)","var":[],"show":"(a − 1)(a² + a + 1)"},{"k":"e","v":"(y − 4)(y² + 4y + 16)","var":[],"show":"(y − 4)(y² + 4y + 16)"}],"sym":"²³","h":["Подумай: «Какой знак перед 3x в разложении x³ − 27?»","Первая скобка содержит разность x − 3. Во второй скобке среднее слагаемое положительное. При умножении x · 3x и −3 · x² взаимно уничтожаются."],"flag":{"par":true}},{"n":164,"lab":"02.3","blk":"h","cls":8,"topic":"Квадратные корни","err":"Пишет два значения квадратного корня","type":"sub","q":"<p>Найди значение корня или реши уравнение.</p><ol class=\"subq\"><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">49</span></span></li><li>x² = 49</li><li>−<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">49</span></span></li></ol>","subs":[{"k":"e","v":"7","var":[],"show":"7"},{"k":"set","v":["−7","7"],"show":"−7 и 7"},{"k":"e","v":"−7","var":[],"show":"−7"}],"sym":"√²","h":["Подумай: «Чему равно <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">36</span></span>? А какие числа подходят в x² = 36?»","Знак √ обозначает арифметический квадратный корень. Из чисел, квадрат которых равен 36, берём неотрицательное. В уравнении проверяем оба числа: и 6, и −6."]},{"n":165,"lab":"02.4","blk":"h","cls":8,"topic":"Квадратные корни","err":"Раскладывает корень из суммы на два корня","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">16 + 9</span></span></li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">36 + 64</span></span></li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">81 − 56</span></span></li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"√","h":["Подумай: «Чему равно <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">9 + 16</span></span>? А сколько будет <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">9</span></span> + <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">16</span></span>?»","Под корнем сначала вычисляем сумму. В примере это 25. Корень из 25 равен 5, а сумма <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">9</span></span> + <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">16</span></span> равна 7."]},{"n":166,"lab":"02.5","blk":"h","cls":8,"topic":"Квадратные уравнения","err":"Подставляет коэффициент b без минуса","type":"sub","q":"<p>Укажи b и найди дискриминант D.</p><ol class=\"subq\"><li>x² − 6x + 5 = 0</li><li>2x² − 3x + 1 = 0</li><li>3x² − 4x + 1 = 0</li></ol>","subs":[{"k":"nums","v":["−6","16"],"show":"b = −6, D = 16"},{"k":"nums","v":["−3","1"],"show":"b = −3, D = 1"},{"k":"nums","v":["−4","4"],"show":"b = −4, D = 4"}],"sym":"²","h":["Подумай: «Назови a, b и c в уравнении 2x² − 5x + 3 = 0».","Читай коэффициент вместе со знаком: −5x = (−5) · x. В дискриминант подставляй b со знаком и в скобках."]},{"n":167,"lab":"02.6","blk":"h","cls":8,"topic":"Квадратные уравнения","err":"Теряет нулевой корень при делении на x","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li>x² − 3x = 0</li><li>x² + 4x = 0</li><li>2x² − 6x = 0</li></ol>","subs":[{"k":"set","v":["0","3"],"show":"0 и 3"},{"k":"set","v":["−4","0"],"show":"−4 и 0"},{"k":"set","v":["0","3"],"show":"0 и 3"}],"sym":"²","h":["Подумай: «Реши x² − 5x = 0. Подходит ли x = 0?»","При делении обеих частей на x мы исключаем x = 0. Вынеси x за скобки. Произведение равно нулю, когда хотя бы один множитель равен нулю."]},{"n":168,"lab":"04.1","blk":"h","cls":8,"topic":"Линейные неравенства","err":"Сохраняет знак при делении на минус","type":"sub","q":"<p>Реши неравенство.</p><ol class=\"subq\"><li>−3x &gt; 9</li><li>−2x ≤ 8</li><li>−5x &lt; −10</li></ol>","subs":[{"k":"t","v":["x < −3","<"],"show":"x < −3"},{"k":"t","v":["x ≥ −4"],"show":"x ≥ −4"},{"k":"t","v":["x > 2",">"],"show":"x > 2"}],"sym":"≤≥","h":["Подумай: «Реши −2x &gt; 6. Подходит ли x = −4? А x = 0?»","При делении обеих частей неравенства на отрицательное число знак неравенства меняется на противоположный. Проверяем: при x = −4 получаем 8 &gt; 6."]},{"n":169,"lab":"04.2","blk":"h","cls":8,"topic":"Линейные неравенства","err":"Закрашивает точку в строгом неравенстве","type":"sub","q":"<p>Запиши числовой промежуток.</p><ol class=\"subq\"><li>x &gt; 3</li><li>x ≤ 0</li><li>x ≥ −2</li></ol>","subs":[{"k":"t","v":["(3; +∞)"],"show":"(3; +∞)"},{"k":"t","v":["(−∞; 0]"],"show":"(−∞; 0]"},{"k":"t","v":["[−2; +∞)"],"show":"[−2; +∞)"}],"sym":"≤≥∞","h":["Подумай: «Подходит ли x = 2 для x &lt; 2? А для x ≤ 2?»","Сравни 2 &lt; 2 и 2 ≤ 2. Первое неверно, второе верно. Пустая точка означает, что граница не входит в ответ. Закрашенная точка означает, что граница входит в ответ."]},{"n":170,"lab":"04.3","blk":"h","cls":8,"topic":"Рациональные дроби","err":"Сокращает слагаемые вместо множителей","type":"sub","q":"<p>Запиши в виде суммы числа и дроби при x ≠ 0.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x+8</span><span>x</span></span></li><li><span class=\"fr\"><span>x+12</span><span>x</span></span></li><li><span class=\"fr\"><span>x+3</span><span>x</span></span></li></ol>","subs":[{"k":"e","v":"1 + 8/x","var":[],"show":"1 + 8/x"},{"k":"e","v":"1 + 12/x","var":[],"show":"1 + 12/x"},{"k":"e","v":"1 + 3/x","var":[],"show":"1 + 3/x"}],"sym":"≠","h":["Подумай: «Можно ли сократить x в дроби <span class=\"fr\"><span>x+6</span><span>x</span></span>? Что выйдет при x = 2?»","При x = 2 исходная дробь равна 4. Если зачеркнуть x в сумме, равенство нарушится. Сокращаем общий множитель всего числителя и всего знаменателя."]},{"n":171,"lab":"04.4","blk":"h","cls":8,"topic":"Рациональные дроби","err":"Теряет ограничение после сокращения","type":"sub","q":"<p>Сократи дробь и укажи ограничение.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x²−9</span><span>x−3</span></span></li><li><span class=\"fr\"><span>x²−16</span><span>x+4</span></span></li><li><span class=\"fr\"><span>x²−1</span><span>x−1</span></span></li></ol>","subs":[{"k":"t","v":["x + 3, x ≠ 3"],"show":"x + 3, x ≠ 3"},{"k":"t","v":["x − 4, x ≠ −4"],"show":"x − 4, x ≠ −4"},{"k":"t","v":["x + 1, x ≠ 1"],"show":"x + 1, x ≠ 1"}],"sym":"²≠","h":["Подумай: «При x = 2 есть ли значение у исходной дроби <span class=\"fr\"><span>x²−4</span><span>x−2</span></span>?»","При x = 2 знаменатель равен нулю. Сначала записываем x ≠ 2. Затем раскладываем числитель и сокращаем дробь. Ограничение x ≠ 2 сохраняется."]},{"n":172,"lab":"04.5","blk":"h","cls":8,"topic":"Подобие фигур","err":"Сопоставляет стороны по положению","type":"sub","q":"<p>По рисунку найди соответствующую сторону.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"10.0 -5.6 240.6 63.3\" width=\"300\" height=\"79\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M31.0,43.0 L31.0,14.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M31.0,14.0 L96.0,43.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M96.0,43.0 L31.0,43.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M230.0,43.0 L169.0,43.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M169.0,43.0 L230.0,15.8\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M230.0,15.8 L230.0,43.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"19.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"21.0\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"101.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"235.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">P</text><text x=\"159.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">Q</text><text x=\"235.0\" y=\"14.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">R</text></svg></div><ol class=\"subq\"><li>Сторона BC</li><li>Сторона AC</li><li>Сторона QR</li></ol>","subs":[{"k":"t","v":["QR"],"show":"QR"},{"k":"t","v":["PR"],"show":"PR"},{"k":"t","v":["BC"],"show":"BC"}],"sym":"","h":["Подумай: «Если △ABC ∼ △PQR, какой стороне соответствует AB?»","Читаем запись по порядку: A ↔ P, B ↔ Q, C ↔ R. Сторону AB соединяют вершины A и B. В другом треугольнике этим вершинам соответствуют P и Q."]},{"n":173,"lab":"04.6","blk":"h","cls":8,"topic":"Подобие фигур","err":"Умножает площадь на коэффициент подобия","type":"sub","q":"<p>Найди площадь S₂, если стороны увеличили в k раз.</p><ol class=\"subq\"><li>k = 2, S₁ = 7</li><li>k = 3, S₁ = 5</li><li>k = 4, S₁ = 3</li></ol>","subs":[{"k":"e","v":"28","var":[],"show":"28"},{"k":"e","v":"45","var":[],"show":"45"},{"k":"e","v":"48","var":[],"show":"48"}],"sym":"","h":["Подумай: «Если сторона квадрата выросла вдвое, как изменилась площадь?»","На рисунке каждый ряд стал вдвое длиннее, и рядов стало вдвое больше. Это правило действует и для подобных треугольников: стороны увеличили в k раз, площади в k² раз."]},{"n":174,"lab":"05.5","blk":"h","cls":8,"topic":"Трапеция","err":"Забывает делить сумму оснований пополам","type":"sub","q":"<p>Найди среднюю линию по двум основаниям.</p><ol class=\"subq\"><li>4 и 12</li><li>7 и 15</li><li>9 и 13</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"11","var":[],"show":"11"},{"k":"e","v":"11","var":[],"show":"11"}],"sym":"","h":["Подумай: «Основания трапеции 6 и 14. Чему равна средняя линия?»","Средняя линия соединяет середины боковых сторон. Её длина равна полусумме оснований: складываем длины оснований и делим сумму на 2."]},{"n":175,"lab":"05.6","blk":"h","cls":8,"topic":"Трапеция","err":"Подставляет боковую сторону вместо высоты","type":"sub","q":"<p>Найди площадь по основаниям и высоте.</p><ol class=\"subq\"><li>6, 12, h = 5</li><li>8, 16, h = 3</li><li>5, 9, h = 6</li></ol>","subs":[{"k":"e","v":"45","var":[],"show":"45"},{"k":"e","v":"36","var":[],"show":"36"},{"k":"e","v":"42","var":[],"show":"42"}],"sym":"","h":["Подумай: «Основания 8 и 14, боковая сторона 5, высота 4. Какова площадь?»","Высота перпендикулярна основаниям. Здесь высота равна 4. Умножаем полусумму оснований на высоту."]},{"n":176,"lab":"06.5","blk":"h","cls":8,"topic":"Теорема Пифагора","err":"Выбирает гипотенузу по положению","type":"sub","q":"<p>Назови гипотенузу треугольника ABC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"39.0 -8.6 100.6 66.3\" width=\"221\" height=\"146\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M59.0,44.0 L98.0,15.0 L119.6,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M59.0,44.0 L119.6,44.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M92.0,19.0 L96.0,25.0 L102.0,21.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"48.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"93.0\" y=\"8.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"124.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>Угол A прямой</li><li>Угол C прямой</li><li>Угол B прямой</li></ol>","subs":[{"k":"t","v":["BC"],"show":"BC"},{"k":"t","v":["AB"],"show":"AB"},{"k":"t","v":["AC"],"show":"AC"}],"sym":"","h":["Подумай: «В треугольнике ABC угол B прямой. Где гипотенуза?»","Гипотенуза лежит напротив прямого угла. Её концы A и C, поэтому гипотенуза AC."]},{"n":177,"lab":"06.6","blk":"h","cls":8,"topic":"Теорема Пифагора","err":"Складывает квадраты при поиске катета","type":"sub","q":"<p>Найди катет b по гипотенузе c и катету a.</p><ol class=\"subq\"><li>c = 10, a = 6</li><li>c = 17, a = 8</li><li>c = 25, a = 7</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"24","var":[],"show":"24"}],"sym":"","h":["Подумай: «Гипотенуза 13, один катет 5. Как найти второй катет?»","Квадрат гипотенузы равен сумме квадратов катетов. Чтобы найти квадрат неизвестного катета, вычитаем 5² из 13². Затем берём квадратный корень."]},{"n":178,"lab":"07.4","blk":"h","cls":8,"topic":"Обратная пропорциональность","err":"Рисует точку на оси для y = k/x","type":"sub","q":"<p>Проверь, лежит ли точка на графике y = <span class=\"fr\"><span>6</span><span>x</span></span>.</p><ol class=\"subq\"><li>(2; 3)</li><li>(6; 0)</li><li>(−2; −3)</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"}],"sym":"","h":["Подумай: «Может ли на графике y = <span class=\"fr\"><span>6</span><span>x</span></span> быть точка (0; 3) или (3; 0)?»","У точки (0; 3) знаменатель равен нулю. У точки (3; 0) произведение координат равно нулю, а должно быть 6. При k ≠ 0 обе координаты точек графика отличны от нуля."]},{"n":179,"lab":"07.6","blk":"h","cls":8,"topic":"Окружность и круг","err":"Считает вписанный угол равным центральному","type":"sub","q":"<p>Найди вписанный угол, опирающийся на дугу.</p><ol class=\"subq\"><li>Дуга 60°</li><li>Дуга 140°</li><li>Дуга 220°</li></ol>","subs":[{"k":"e","v":"30","var":[],"show":"30°"},{"k":"e","v":"70","var":[],"show":"70°"},{"k":"e","v":"110","var":[],"show":"110°"}],"sym":"°","h":["Подумай: «Дуга AB без точки C равна 100°. Чему равен угол ACB?»","Вершина центрального угла лежит в центре окружности. Вершина вписанного угла лежит на окружности. Угол ACB равен половине дуги AB, которая не содержит точку C."]},{"n":180,"lab":"08.5","blk":"h","cls":8,"topic":"Тригонометрия в прямоугольном треугольнике","err":"Путает синус и косинус","type":"sub","q":"<p>Вычисли по рисунку.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"24.0 -11.6 94.6 79.3\" width=\"208\" height=\"175\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M45.0,44.0 L97.0,5.0 L97.0,44.0 L45.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M91.0,44.0 L91.0,38.0 L97.0,38.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M97.0,44.0 L97.0,5.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"33.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"101.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"101.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"66.0\" y=\"57.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">4</text><text x=\"103.0\" y=\"32.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">3</text><text x=\"60.0\" y=\"22.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">5</text></svg></div><ol class=\"subq\"><li>sin A</li><li>cos A</li><li>sin C</li></ol>","subs":[{"k":"e","v":"3/5","var":[],"show":"3/5"},{"k":"e","v":"4/5","var":[],"show":"4/5"},{"k":"e","v":"4/5","var":[],"show":"4/5"}],"sym":"","h":["Подумай: «В треугольнике на рисунке чему равен синус угла A?»","Для угла A катет BC лежит напротив, а катет AB прилегает. Синус равен отношению противолежащего катета к гипотенузе. Для косинуса берём прилежащий катет."]},{"n":181,"lab":"08.6","blk":"h","cls":8,"topic":"Тригонометрия в прямоугольном треугольнике","err":"Делит катет на гипотенузу в тангенсе","type":"sub","q":"<p>Вычисли по рисунку.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"24.0 -11.6 94.6 79.3\" width=\"208\" height=\"175\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M45.0,44.0 L97.0,5.0 L97.0,44.0 L45.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M91.0,44.0 L91.0,38.0 L97.0,38.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M97.0,44.0 L97.0,5.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"33.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"101.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"101.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"66.0\" y=\"57.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">4</text><text x=\"103.0\" y=\"32.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">3</text><text x=\"60.0\" y=\"22.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">5</text></svg></div><ol class=\"subq\"><li>tg A</li><li>tg C</li><li>tg A · tg C</li></ol>","subs":[{"k":"e","v":"3/4","var":[],"show":"3/4"},{"k":"e","v":"4/3","var":[],"show":"4/3"},{"k":"e","v":"1","var":[],"show":"1"}],"sym":"","h":["Подумай: «Какие две стороны нужно взять для тангенса угла A?»","Для тангенса берём два катета. Сначала определяем, какой катет лежит напротив угла, затем делим его на прилежащий. Если поменять угол A на C, катеты меняются ролями."]},{"n":182,"lab":"09.3","blk":"h","cls":8,"topic":"Вероятность","err":"Делит на число неподходящих исходов","type":"sub","q":"<p>Найди вероятность вытянуть синий шар.</p><ol class=\"subq\"><li>3 синих, 1 белый</li><li>2 синих, 3 белых</li><li>1 синий, 5 белых</li></ol>","subs":[{"k":"e","v":"3/4","var":[],"show":"3/4"},{"k":"e","v":"2/5","var":[],"show":"2/5"},{"k":"e","v":"1/6","var":[],"show":"1/6"}],"sym":"","h":["Подумай: «В мешке 3 синих и 2 белых шара. Каков шанс вытянуть синий?»","Если вытягиваем один шар наугад, каждый из пяти может выпасть с одинаковой вероятностью. Подходят три синих. Делим число подходящих исходов на число всех исходов."]},{"n":183,"lab":"09.4","blk":"h","cls":8,"topic":"Вероятность","err":"Забывает вычесть вероятность из единицы","type":"sub","q":"<p>Найди вероятность, что дождя не будет.</p><ol class=\"subq\"><li>Дождь: 0,2</li><li>Дождь: 0,65</li><li>Дождь: 0,9</li></ol>","subs":[{"k":"e","v":"0,8","var":[],"show":"0,8"},{"k":"e","v":"0,35","var":[],"show":"0,35"},{"k":"e","v":"0,1","var":[],"show":"0,1"}],"sym":"","h":["Подумай: «Вероятность дождя 0,3. Какова вероятность, что дождя не будет?»","Возможны два исхода: дождь будет или его не будет. Вместе их вероятности дают 1. Если дождю соответствует 0,3, на отсутствие дождя остаётся 1 − 0,3 = 0,7."]},{"n":184,"lab":"11.5","blk":"h","cls":8,"topic":"Параллелограмм","err":"Считает соседние углы равными","type":"sub","q":"<p>Найди соседний угол параллелограмма.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"17.0 -5.6 159.1 66.3\" width=\"300\" height=\"125\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M38.0,44.0 L51.5,15.0 L156.5,15.0 L143.0,44.0 L38.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M48.0,44.0 C48.0,40.1 45.7,36.6 42.2,34.9\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M47.3,24.1 C50.4,25.5 54.0,25.3 56.9,23.4 C59.8,21.6 61.5,18.4 61.5,15.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"26.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"41.5\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"160.5\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"148.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>∠A = 48°. ∠B = ?</li><li>∠B = 110°. ∠C = ?</li><li>∠D = 92°. ∠A = ?</li></ol>","subs":[{"k":"e","v":"132","var":[],"show":"132°"},{"k":"e","v":"70","var":[],"show":"70°"},{"k":"e","v":"88","var":[],"show":"88°"}],"sym":"°","h":["Подумай: «В параллелограмме ABCD угол A равен 65°. Чему равен угол B?»","Соседние углы A и B лежат по одну сторону от секущей AB между параллельными AD и BC. Их сумма равна 180°. Значит, угол B равен 115°."]},{"n":185,"lab":"11.6","blk":"h","cls":8,"topic":"Параллелограмм","err":"Считает диагонали равными","type":"sub","q":"<p>Точка O — пересечение диагоналей. Найди отрезок.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"17.0 -6.1 159.1 66.8\" width=\"300\" height=\"126\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M38.0,44.0 L51.5,15.0 L156.5,15.0 L143.0,44.0 L38.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M38.0,44.0 L156.5,15.0 M51.5,15.0 L143.0,44.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"26.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"41.5\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"160.5\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"148.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text><text x=\"79.3\" y=\"10.5\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text></svg></div><ol class=\"subq\"><li>AC = 18. Найди AO</li><li>BO = 6. Найди BD</li><li>BD = 16. Найди DO</li></ol>","subs":[{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «В параллелограмме AC = 14, BD = 10. Найди AO и BO».","Точка O — пересечение диагоналей. Она делит каждую диагональ пополам. Половина AC равна 7, половина BD равна 5. У диагоналей могут быть разные длины."]},{"n":186,"lab":"12.5","blk":"h","cls":8,"topic":"Площадь треугольника","err":"Забывает делить произведение пополам","type":"sub","q":"<p>Найди площадь по основанию a и высоте h.</p><ol class=\"subq\"><li>a = 6, h = 5</li><li>a = 12, h = 4</li><li>a = 9, h = 8</li></ol>","subs":[{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"24","var":[],"show":"24"},{"k":"e","v":"36","var":[],"show":"36"}],"sym":"","h":["Подумай: «Основание 8 см, высота к нему 3 см. Какова площадь?»","Вторая такая же копия прямоугольного треугольника дополняет его до прямоугольника. Его площадь 8 · 3 = 24. Треугольник занимает половину, поэтому его площадь 12 см²."]},{"n":187,"lab":"12.6","blk":"h","cls":8,"topic":"Площадь треугольника","err":"Берёт высоту, проведённую к другой стороне","type":"sub","q":"<p>Найди площадь ABC. BD — высота к стороне AC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"11.0 -12.6 135.6 82.3\" width=\"298\" height=\"181\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M32.0,46.0 L65.0,8.0 L127.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M32.0,46.0 L127.0,46.0 M65.0,8.0 L65.0,46.0 M65.0,41.0 L70.0,41.0 L70.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"20.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"68.0\" y=\"4.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"131.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"59.0\" y=\"59.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>AC = 9, BD = 4</li><li>AC = 16, BD = 8</li><li>AC = 18, BD = 12</li></ol>","subs":[{"k":"e","v":"18","var":[],"show":"18"},{"k":"e","v":"64","var":[],"show":"64"},{"k":"e","v":"108","var":[],"show":"108"}],"sym":"","h":["Подумай: «AB = 5, AC = 10, высота к AC равна 4. Какова площадь?»","Высота должна быть перпендикулярна выбранному основанию. Здесь BD перпендикулярна AC, поэтому умножаем 10 на 4 и делим пополам. Длина AB в этом вычислении не нужна."]},{"n":188,"lab":"13.3","blk":"h","cls":8,"topic":"Теорема Виета","err":"Берёт сумму корней со знаком b","type":"sub","q":"<p>Реши уравнение по теореме Виета.</p><ol class=\"subq\"><li>x² − 5x + 6 = 0</li><li>x² + 7x + 12 = 0</li><li>x² − x − 6 = 0</li></ol>","subs":[{"k":"set","v":["2","3"],"show":"2 и 3"},{"k":"set","v":["−4","−3"],"show":"−4 и −3"},{"k":"set","v":["−2","3"],"show":"−2 и 3"}],"sym":"²","h":["Подумай: «В уравнении x² − 7x + 12 = 0 чему равна сумма корней?»","В приведённом уравнении x² + bx + c = 0 сумма корней равна −b, а произведение равно c. Здесь b = −7, c = 12. Числа 3 и 4 дают нужную сумму 7 и произведение 12."]},{"n":189,"lab":"13.4","blk":"h","cls":8,"topic":"Теорема Виета","err":"Читает коэффициенты по Виету до деления","type":"sub","q":"<p>Приведи уравнение и найди корни.</p><ol class=\"subq\"><li>3x² − 12x + 9 = 0</li><li>2x² + 6x − 8 = 0</li><li>4x² − 20x + 24 = 0</li></ol>","subs":[{"k":"set","v":["1","3"],"show":"1 и 3"},{"k":"set","v":["−4","1"],"show":"−4 и 1"},{"k":"set","v":["2","3"],"show":"2 и 3"}],"sym":"²","h":["Подумай: «В уравнении 2x² − 10x + 12 = 0 чему равна сумма корней?»","Чтобы использовать правило для приведённого уравнения, делим все слагаемые на 2. Получаем x² − 5x + 6 = 0. Сумма корней равна 5, произведение равно 6."]},{"n":190,"lab":"13.5","blk":"h","cls":8,"topic":"Ромб","err":"Забывает делить произведение диагоналей","type":"sub","q":"<p>Найди площадь ромба по диагоналям.</p><ol class=\"subq\"><li>d₁ = 10, d₂ = 6</li><li>d₁ = 12, d₂ = 8</li><li>d₁ = 14, d₂ = 5</li></ol>","subs":[{"k":"e","v":"30","var":[],"show":"30"},{"k":"e","v":"48","var":[],"show":"48"},{"k":"e","v":"35","var":[],"show":"35"}],"sym":"","h":["Подумай: «Диагонали ромба равны 8 и 6. Какова его площадь?»","Ромб равен по площади половине прямоугольника на рисунке. Стороны прямоугольника равны диагоналям ромба. В каждом из четырёх прямоугольников закрашена половина."]},{"n":191,"lab":"13.6","blk":"h","cls":8,"topic":"Ромб","err":"Берёт целые диагонали при поиске стороны","type":"sub","q":"<p>Найди сторону ромба по диагоналям.</p><ol class=\"subq\"><li>d₁ = 10, d₂ = 24</li><li>d₁ = 16, d₂ = 30</li><li>d₁ = 14, d₂ = 48</li></ol>","subs":[{"k":"e","v":"13","var":[],"show":"13"},{"k":"e","v":"17","var":[],"show":"17"},{"k":"e","v":"25","var":[],"show":"25"}],"sym":"","h":["Подумай: «Диагонали ромба равны 6 и 8. Чему равна его сторона?»","Диагонали ромба перпендикулярны и делятся пополам. Катеты на чертеже равны 3 и 4. Сторона ромба служит гипотенузой: её квадрат равен 3² + 4² = 25."]},{"n":192,"lab":"18.3","blk":"h","cls":8,"topic":"Дробно-рациональные уравнения","err":"Приравнивает знаменатель к нулю","type":"sub","q":"<p>Реши уравнение.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x−5</span><span>x+1</span></span> = 0</li><li><span class=\"fr\"><span>x+3</span><span>x−2</span></span> = 0</li><li><span class=\"fr\"><span>2x−8</span><span>x+4</span></span> = 0</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"−3","var":[],"show":"−3"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"","h":["Подумай: «Какие значения x нужно проверить в уравнении <span class=\"fr\"><span>x−3</span><span>x+2</span></span> = 0?»","Дробь равна нулю, когда числитель равен нулю, а знаменатель отличен от нуля. При x = 3 знаменатель равен 5. Значение x = −2 исключаем: делить на ноль нельзя."]},{"n":193,"lab":"18.4","blk":"h","cls":8,"topic":"Дробно-рациональные уравнения","err":"Принимает корень, обнуляющий знаменатель","type":"sub","q":"<p>Реши уравнение с учётом знаменателя.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x</span><span>x−3</span></span> = <span class=\"fr\"><span>3</span><span>x−3</span></span></li><li><span class=\"fr\"><span>x</span><span>x−2</span></span> = <span class=\"fr\"><span>5</span><span>x−2</span></span></li><li><span class=\"fr\"><span>x+1</span><span>x−1</span></span> = <span class=\"fr\"><span>2</span><span>x−1</span></span></li></ol>","subs":[{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"}],"sym":"","h":["Подумай: «После умножения на x − 2 получили x = 2. Подходит ли это x?»","Сначала исключаем значение, при котором знаменатель равен нулю. В примере x ≠ 2. Умножаем обе части на x − 2 и получаем x = 2. Это значение исключено."]},{"n":194,"lab":"18.5","blk":"h","cls":8,"topic":"Касательная к окружности","err":"Проводит перпендикуляр к любому радиусу","type":"sub","q":"<p>Назови радиус, перпендикулярный касательной.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"35.0 0.0 75.6 62.0\" width=\"166\" height=\"136\" role=\"img\" aria-label=\"Рисунок к заданию\"><circle cx=\"66.0\" cy=\"31.0\" r=\"23.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M66.0,31.0 L89.0,31.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M89.0,54.0 L89.0,8.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M84.0,31.0 L84.0,26.0 L89.0,26.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"56.0\" y=\"34.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text><text x=\"95.0\" y=\"34.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">T</text></svg></div><ol class=\"subq\"><li>Касание в A</li><li>Касание в B</li><li>Касание в C</li></ol>","subs":[{"k":"t","v":["OA"],"show":"OA"},{"k":"t","v":["OB"],"show":"OB"},{"k":"t","v":["OC"],"show":"OC"}],"sym":"","h":["Подумай: «Прямая касается окружности в T. Какой радиус ей перпендикулярен?»","Соедини центр O с точкой касания T. Именно в точке T радиус OT образует с касательной прямой угол. Теперь можно искать углы или длины."]},{"n":195,"lab":"18.6","blk":"h","cls":8,"topic":"Касательная к окружности","err":"Считает один отрезок касательной длиннее","type":"sub","q":"<p>Найди длину отрезка.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"35.0 -11.5 97.6 84.1\" width=\"215\" height=\"185\" role=\"img\" aria-label=\"Рисунок к заданию\"><circle cx=\"66.0\" cy=\"31.0\" r=\"23.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M66.0,31.0 L77.5,11.1\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M77.5,11.1 L112.0,31.0 M77.5,50.9 L112.0,31.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"56.0\" y=\"34.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text><text x=\"78.5\" y=\"5.1\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"78.5\" y=\"61.9\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"117.0\" y=\"34.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">P</text></svg></div><ol class=\"subq\"><li>PA = 5. Найди PB</li><li>PB = 12. Найди PA</li><li>PA + PB = 18. PA = ?</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"9","var":[],"show":"9"}],"sym":"","h":["Подумай: «Из точки P проведены касательные в A и B. PA = 7. Чему равно PB?»","От одной внешней точки до двух точек касания отрезки касательных равны. Поэтому PA = PB = 7."]},{"n":196,"lab":"19.5","blk":"h","cls":8,"topic":"Диагонали прямоугольника","err":"Принимает половину диагонали за целую","type":"sub","q":"<p>Найди отрезок. O — точка пересечения диагоналей.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"19.0 -3.6 90.6 65.3\" width=\"199\" height=\"144\" role=\"img\" aria-label=\"Рисунок к заданию\"><rect x=\"40.0\" y=\"12.0\" width=\"49.0\" height=\"36.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M40.0,48.0 L89.0,12.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M40.0,12.0 L89.0,48.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"28.0\" y=\"51.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"94.0\" y=\"51.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"94.0\" y=\"13.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"28.0\" y=\"13.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text><text x=\"45.5\" y=\"34.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text></svg></div><ol class=\"subq\"><li>AO = 5. BD = ?</li><li>BD = 18. OC = ?</li><li>BO = 7. AC = ?</li></ol>","subs":[{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"14","var":[],"show":"14"}],"sym":"","h":["Подумай: «Точка O — пересечение диагоналей. Если AO = 6, чему равна BD?»","Точка O делит диагональ AC пополам, поэтому AC = 12. Диагонали прямоугольника равны. Значит, BD тоже равна 12."]},{"n":197,"lab":"19.6","blk":"h","cls":8,"topic":"Диагонали прямоугольника","err":"Складывает длины сторон, чтобы найти диагональ","type":"sub","q":"<p>Найди диагональ прямоугольника по его сторонам.</p><ol class=\"subq\"><li>3 и 4</li><li>5 и 12</li><li>8 и 15</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"13","var":[],"show":"13"},{"k":"e","v":"17","var":[],"show":"17"}],"sym":"","h":["Подумай: «Стороны прямоугольника 6 и 8. Чему равна диагональ?»","Диагональ делит прямоугольник на два прямоугольных треугольника. В каждом она служит гипотенузой. Её квадрат равен 6² + 8² = 100, а сама диагональ равна 10."]},{"n":198,"lab":"21.5","blk":"h","cls":8,"topic":"Признаки прямоугольника и ромба","err":"Считает равные диагонали признаком для всех фигур","type":"sub","q":"<p>Будет ли фигура прямоугольником при равных диагоналях?.</p><ol class=\"subq\"><li>Параллелограмм</li><li>Равнобедр. трапеция</li><li>Четырёхугольник</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Данных мало"],"show":"Данных мало"}],"sym":"","h":["Подумай: «У четырёхугольника равны диагонали. Это точно прямоугольник?»","Равные диагонали есть и у равнобедренной трапеции. Чтобы применить признак прямоугольника, сначала установи, что перед тобой параллелограмм."]},{"n":199,"lab":"21.6","blk":"h","cls":8,"topic":"Признаки прямоугольника и ромба","err":"Считает перпендикулярные диагонали достаточными","type":"sub","q":"<p>Будет ли фигура ромбом при перпендикулярных диагоналях?.</p><ol class=\"subq\"><li>Параллелограмм</li><li>Прямоугольник</li><li>Четырёхугольник</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Да, это квадрат","Да"],"show":"Да, это квадрат"},{"k":"t","v":["Данных мало"],"show":"Данных мало"}],"sym":"","h":["Подумай: «Если диагонали четырёхугольника перпендикулярны, это ромб?»","Перпендикулярные диагонали бывают и у фигур с разными сторонами. Признак ромба применяем, когда уже известно, что четырёхугольник — параллелограмм."]},{"n":200,"lab":"25.2","blk":"h","cls":8,"topic":"Нулевая и отрицательная степени","err":"Принимает отрицательный показатель за минус","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>3⁻²</li><li>5⁻¹</li><li>(−2)⁻³</li></ol>","subs":[{"k":"e","v":"1/9","var":[],"show":"1/9"},{"k":"e","v":"1/5","var":[],"show":"1/5"},{"k":"e","v":"−1/8","var":[],"show":"−1/8"}],"sym":"²³","h":["Подумай: «Чему равно 2⁻³: −8 или одна восьмая?»","Отрицательный показатель означает обратную величину. Сначала находим 2³ = 8. Затем берём обратное число. Поэтому результат равен одной восьмой."]},{"n":201,"lab":"26.3","blk":"h","cls":8,"topic":"Медиана в прямоугольном треугольнике","err":"Делит медиану пополам, когда ищет гипотенузу","type":"sub","q":"<p>Найди гипотенузу по медиане m к ней.</p><ol class=\"subq\"><li>m = 4 см</li><li>m = 6,5 см</li><li>m = 9 см</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8 см"},{"k":"e","v":"13","var":[],"show":"13 см"},{"k":"e","v":"18","var":[],"show":"18 см"}],"sym":"","h":["Подумай: «Медиана к гипотенузе равна 7,5 см. Чему равна гипотенуза?»","Середина гипотенузы равноудалена от трёх вершин. Поэтому медиана к гипотенузе равна половине гипотенузы. Умножаем длину медианы на 2 и получаем 15 см."]},{"n":202,"lab":"26.4","blk":"h","cls":8,"topic":"Медиана в прямоугольном треугольнике","err":"Переносит свойство на медиану к катету","type":"sub","q":"<p>Всегда ли медиана равна половине указанной стороны?.</p><ol class=\"subq\"><li>К гипотенузе</li><li>К первому катету</li><li>Ко второму катету</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «Медиана к катету равна 5 см. Значит ли это, что катет равен 10 см?»","Медиана делит пополам сторону, к которой проведена. Сам отрезок медианы равен половине этой стороны в специальном случае: когда сторона — гипотенуза."]},{"n":203,"lab":"27.3","blk":"h","cls":8,"topic":"Системы линейных неравенств","err":"Объединяет решения вместо пересечения","type":"sub","q":"<p>Реши систему неравенств.</p><ol class=\"subq\"><li>x &gt; 2 и x &lt; 6</li><li>x ≥ 0 и x &lt; 3</li><li>x &gt; −2 и x ≤ 5</li></ol>","subs":[{"k":"t","v":["(2; 6)","2; 6"],"show":"(2; 6)"},{"k":"t","v":["[0; 3)"],"show":"[0; 3)"},{"k":"t","v":["(−2; 5]"],"show":"(−2; 5]"}],"sym":"≤≥","h":["Подумай: «В системе x &gt; 1 и x &lt; 4. Подходят ли числа 0, 2 и 5?»","Решение системы выполняет оба неравенства сразу. Число 0 не больше 1, а число 5 не меньше 4. Подходят только числа между 1 и 4."]},{"n":204,"lab":"27.4","blk":"h","cls":8,"topic":"Системы линейных неравенств","err":"Оставляет промежуток без общих точек","type":"sub","q":"<p>Реши систему неравенств.</p><ol class=\"subq\"><li>x &gt; 3 и x &lt; 2</li><li>x ≥ 2 и x ≤ 2</li><li>x &gt; 2 и x ≤ 2</li></ol>","subs":[{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"},{"k":"e","v":"2","var":[],"show":"x = 2"},{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"}],"sym":"≤≥","h":["Подумай: «Есть ли число, которое одновременно больше 4 и меньше 1?»","Решения x &gt; 4 лежат правее 4. Решения x &lt; 1 лежат левее 1. Общих точек нет, поэтому система не имеет решений."]},{"n":205,"lab":"27.5","blk":"h","cls":8,"topic":"Средняя линия треугольника","err":"Берёт полусумму сторон треугольника","type":"sub","q":"<p>Найди среднюю линию MN, параллельную BC.</p><ol class=\"subq\"><li>BC = 10</li><li>BC = 18</li><li>BC = 25</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"12,5","var":[],"show":"12,5"}],"sym":"","h":["Подумай: «M и N — середины AB и AC. Как найти MN, если BC = 14?»","Средняя линия соединяет середины двух сторон. Она параллельна третьей стороне BC и равна её половине. Поэтому MN = 14 : 2 = 7."]},{"n":206,"lab":"27.6","blk":"h","cls":8,"topic":"Средняя линия треугольника","err":"Делит среднюю линию пополам при поиске стороны","type":"sub","q":"<p>Найди сторону BC, параллельную средней линии MN.</p><ol class=\"subq\"><li>MN = 4</li><li>MN = 7,5</li><li>MN = 11</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"22","var":[],"show":"22"}],"sym":"","h":["Подумай: «Средняя линия MN равна 6. Чему равна параллельная сторона BC?»","MN составляет половину стороны BC. Чтобы восстановить всю сторону, берём две такие половины. Получаем BC = 2 · 6 = 12."]},{"n":207,"lab":"28.3","blk":"h","cls":8,"topic":"Свойства квадратного корня","err":"Убирает корень и квадрат без проверки знака","type":"sub","q":"<p>Вычисли.</p><ol class=\"subq\"><li>√((−5)²)</li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">9²</span></span></li><li>√((−12)²)</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"12","var":[],"show":"12"}],"sym":"√²","h":["Подумай: «Чему равно √((−7)²)? Можно ли ответить −7?»","Сначала возводим −7 в квадрат и получаем 49. Арифметический квадратный корень из 49 равен 7. Общее правило: корень из a² равен модулю a."]},{"n":208,"lab":"28.4","blk":"h","cls":8,"topic":"Свойства квадратного корня","err":"Выносит квадратный множитель без корня","type":"sub","q":"<p>Вынеси множитель из-под корня.</p><ol class=\"subq\"><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">50</span></span></li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">108</span></span></li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">98</span></span></li></ol>","subs":[{"k":"e","v":"5√2","var":[],"show":"5√2"},{"k":"e","v":"6√3","var":[],"show":"6√3"},{"k":"e","v":"7√2","var":[],"show":"7√2"}],"sym":"√","h":["Подумай: «Упрости <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">72</span></span>. Какой квадратный множитель можно выделить?»","Разложим 72 на 36 · 2. Из 36 извлекаем корень 6. Число 2 остаётся под корнем. Проверяем: квадрат числа 6<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">2</span></span> равен 36 · 2 = 72."],"flag":{"rootout":true}},{"n":209,"lab":"29.5","blk":"h","cls":8,"topic":"Хорды окружности","err":"Путает хорду с её половиной","type":"sub","q":"<p>Найди указанный отрезок по рисунку.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"39.6 -2.0 81.4 74.5\" width=\"179\" height=\"164\" role=\"img\" aria-label=\"Рисунок к заданию\"><circle cx=\"81.0\" cy=\"29.0\" r=\"23.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.6,42.8 L99.4,42.8 M81.0,29.0 L81.0,42.8\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M81.0,38.8 L85.0,38.8 L85.0,42.8\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"75.0\" y=\"23.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text><text x=\"48.6\" y=\"41.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"105.4\" y=\"44.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"68.0\" y=\"61.8\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">M</text></svg></div><ol class=\"subq\"><li>AM = 3 см. AB = ?</li><li>MB = 7 см. AB = ?</li><li>AB = 18 см. AM = ?</li></ol>","subs":[{"k":"t","v":["AB = 6 см"],"show":"AB = 6 см"},{"k":"t","v":["AB = 14 см"],"show":"AB = 14 см"},{"k":"t","v":["AM = 9 см"],"show":"AM = 9 см"}],"sym":"","h":["Подумай: «OM — перпендикуляр к хорде AB. AM = 5 см. Чему равна AB?»","Перпендикуляр из центра окружности к хорде делит её пополам. Значит, AM = MB. Вся хорда состоит из двух отрезков по 5 см. Получаем AB = 10 см."]},{"n":210,"lab":"29.6","blk":"h","cls":8,"topic":"Хорды окружности","err":"Принимает расстояние до хорды за радиус","type":"sub","q":"<p>Найди длину хорды AB по радиусу r и расстоянию OM.</p><ol class=\"subq\"><li>r = 5, OM = 3</li><li>r = 13, OM = 5</li><li>r = 17, OM = 8</li></ol>","subs":[{"k":"e","v":"8","var":[],"show":"8"},{"k":"e","v":"24","var":[],"show":"24"},{"k":"e","v":"30","var":[],"show":"30"}],"sym":"","h":["Подумай: «Радиус 10 см, расстояние от центра до хорды 6 см. Как найти хорду?»","В треугольнике OMA радиус OA служит гипотенузой. Расстояние OM — катет. По теореме Пифагора получаем AM² = 100 − 36 = 64. Половина хорды равна 8 см, вся хорда 16 см."]},{"n":211,"lab":"30.5","blk":"h","cls":8,"topic":"Вписанная окружность","err":"Ищет центр вписанной окружности на медианах","type":"sub","q":"<p>Обязательно ли пересечение этих линий даёт центр вписанной окружности?.</p><ol class=\"subq\"><li>Медианы</li><li>Высоты</li><li>Биссектрисы</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"}],"sym":"","h":["Подумай: «Какие линии нужно провести, чтобы найти центр вписанной окружности?»","Центр вписанной окружности равноудалён от сторон. Биссектриса угла состоит из точек, равноудалённых от его сторон. Поэтому центр лежит на пересечении биссектрис."]},{"n":212,"lab":"30.6","blk":"h","cls":8,"topic":"Вписанная окружность","err":"Считает отрезок до вершины радиусом","type":"sub","q":"<p>Назови радиус к точке касания, если центр O.</p><ol class=\"subq\"><li>Касание в K</li><li>Касание в M</li><li>Касание в N</li></ol>","subs":[{"k":"t","v":["OK"],"show":"OK"},{"k":"t","v":["OM"],"show":"OM"},{"k":"t","v":["ON"],"show":"ON"}],"sym":"","h":["Подумай: «Окружность с центром O касается AB в T. Что равно радиусу: OA или OT?»","Радиус соединяет центр с точкой окружности. Точка T лежит на окружности и на стороне AB. Радиус OT перпендикулярен стороне AB в точке касания."]},{"n":213,"lab":"31.5","blk":"h","cls":8,"topic":"Описанная окружность","err":"Ищет центр окружности на биссектрисах","type":"sub","q":"<p>Пересечение каких линий всегда даёт центр окружности?.</p><ol class=\"subq\"><li>Биссектрисы</li><li>Серединные перпенд.</li><li>Медианы</li></ol>","subs":[{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"}],"sym":"","h":["Подумай: «По каким линиям найти центр окружности, проходящей через A, B и C?»","Центр равноудалён от трёх вершин. Если OA = OB, точка O лежит на серединном перпендикуляре к AB. Достаточно пересечь два таких перпендикуляра."]},{"n":214,"lab":"31.6","blk":"h","cls":8,"topic":"Описанная окружность","err":"Помещает центр внутрь прямоугольного треугольника","type":"sub","q":"<p>Найди радиус, если AB — гипотенуза.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"36.0 -13.6 85.6 73.6\" width=\"188\" height=\"162\" role=\"img\" aria-label=\"Рисунок к заданию\"><circle cx=\"79.0\" cy=\"30.0\" r=\"22.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M57.0,30.0 L79.0,8.0 L101.0,30.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M57.0,30.0 L101.0,30.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M76.0,11.0 L79.0,14.0 L82.0,11.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"45.0\" y=\"33.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"106.0\" y=\"33.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"79.0\" y=\"3.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"76.0\" y=\"41.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text></svg></div><ol class=\"subq\"><li>AB = 10</li><li>AB = 13</li><li>AB = 24</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"6,5","var":[],"show":"6,5"},{"k":"e","v":"12","var":[],"show":"12"}],"sym":"","h":["Подумай: «Угол C прямой. Где центр описанной окружности треугольника ABC?»","В прямоугольном треугольнике середина гипотенузы равноудалена от трёх вершин. Здесь гипотенуза AB. Центр лежит на AB, а радиус равен её половине."]},{"n":215,"lab":"32.5","blk":"h","cls":8,"topic":"Площадь и высота ромба","err":"Возводит сторону ромба в квадрат","type":"sub","q":"<p>Найди площадь по стороне a и высоте h в сантиметрах.</p><ol class=\"subq\"><li>a = 6, h = 4</li><li>a = 9, h = 5</li><li>a = 12, h = 7</li></ol>","subs":[{"k":"e","v":"24","var":[],"show":"24 см²"},{"k":"e","v":"45","var":[],"show":"45 см²"},{"k":"e","v":"84","var":[],"show":"84 см²"}],"sym":"²","h":["Подумай: «Сторона ромба равна 5 см, высота 4 см. Чему равна площадь?»","Ромб — параллелограмм с равными сторонами. Его площадь равна произведению стороны на высоту к ней. В этом примере 5 · 4 = 20 см²."]},{"n":216,"lab":"32.6","blk":"h","cls":8,"topic":"Площадь и высота ромба","err":"Использует формулу с диагоналями для высоты","type":"sub","q":"<p>Найди высоту по площади S в см² и стороне a в см.</p><ol class=\"subq\"><li>S = 30, a = 6</li><li>S = 48, a = 8</li><li>S = 63, a = 9</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5 см"},{"k":"e","v":"6","var":[],"show":"6 см"},{"k":"e","v":"7","var":[],"show":"7 см"}],"sym":"²","h":["Подумай: «Площадь ромба 36 см², сторона 9 см. Как найти высоту?»","Площадь равна произведению стороны на высоту: S = a · h. В равенстве 36 = 9 · h ищем неизвестный множитель. Делим площадь на сторону: 36 : 9 = 4 см."]},{"n":217,"lab":"33.4","blk":"h","cls":8,"topic":"Уравнения с произведением","err":"Приравнивает множители к нулю слишком рано","type":"sub","q":"<p>Приведи к квадратному уравнению и реши.</p><ol class=\"subq\"><li>(x − 1)(x + 2) = 4</li><li>(x − 3)(x + 1) = 5</li><li>(x + 1)(x + 2) = 6</li></ol>","subs":[{"k":"set","v":["−3","2"],"show":"−3 и 2"},{"k":"set","v":["−2","4"],"show":"−2 и 4"},{"k":"set","v":["−4","1"],"show":"−4 и 1"}],"sym":"","h":["Подумай: «Как решить (x − 2)(x + 3) = 5? Подходит ли x = 2?»","При x = 2 слева 0, справа 5. Сначала раскрываем скобки и переносим 5 влево: x² + x − 11 = 0. Полученное квадратное уравнение решаем по дискриминанту."]},{"n":218,"lab":"34.1","blk":"h","cls":8,"topic":"Круги Эйлера","err":"Дважды считает тех, кто входит в обе группы","type":"sub","q":"<p>Найди число участников хотя бы одного кружка.</p><ol class=\"subq\"><li>12, 9, оба 3</li><li>15, 11, оба 5</li><li>8, 10, оба 2</li></ol>","subs":[{"k":"e","v":"18","var":[],"show":"18"},{"k":"e","v":"21","var":[],"show":"21"},{"k":"e","v":"16","var":[],"show":"16"}],"sym":"","h":["Подумай: «Шахматы: 12, танцы: 10, оба кружка: 4. Сколько ходят хотя бы на один?»","В сумме 12 + 10 общие четыре человека учтены дважды. Вычитаем их один раз. Получаем 18 человек. На схеме можно сложить три отдельные области: 8 + 4 + 6."]},{"n":219,"lab":"34.2","blk":"h","cls":8,"topic":"Круги Эйлера","err":"Путает «ровно один» и «хотя бы один»","type":"sub","q":"<p>Найди число участников ровно одного кружка.</p><ol class=\"subq\"><li>12, 9, оба 3</li><li>15, 11, оба 5</li><li>8, 10, оба 2</li></ol>","subs":[{"k":"e","v":"15","var":[],"show":"15"},{"k":"e","v":"16","var":[],"show":"16"},{"k":"e","v":"14","var":[],"show":"14"}],"sym":"","h":["Подумай: «Шахматы: 12, танцы: 10, оба кружка: 4. Сколько ходят ровно на один?»","Только на шахматы ходят 12 − 4 = 8 человек. Только на танцы ходят 10 − 4 = 6 человек. Складываем 8 и 6. Общая часть здесь не входит в ответ."]},{"n":220,"lab":"34.3","blk":"h","cls":8,"topic":"Дискриминант квадратного уравнения","err":"Записывает два корня при D = 0","type":"sub","q":"<p>Найди корни.</p><ol class=\"subq\"><li>x² − 4x + 4 = 0</li><li>x² + 10x + 25 = 0</li><li>4x² − 4x + 1 = 0</li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"−5","var":[],"show":"−5"},{"k":"e","v":"1/2","var":[],"show":"1/2"}],"sym":"²","h":["Подумай: «Сколько различных корней у уравнения x² − 6x + 9 = 0?»","Дискриминант равен 36 − 36 = 0. В формуле корней прибавление и вычитание нуля дают одно и то же число. Здесь единственный корень 3."]},{"n":221,"lab":"34.4","blk":"h","cls":8,"topic":"Дискриминант квадратного уравнения","err":"Берёт корень из отрицательного дискриминанта","type":"sub","q":"<p>Вычисли D и определи, есть ли действительные корни.</p><ol class=\"subq\"><li>x² + 2x + 3 = 0</li><li>x² − 6x + 10 = 0</li><li>2x² + 1 = 0</li></ol>","subs":[{"k":"t","v":["D = −8, корней нет","D = −8","−8"],"show":"D = −8, корней нет"},{"k":"t","v":["D = −4, корней нет","D = −4","−4"],"show":"D = −4, корней нет"},{"k":"t","v":["D = −8, корней нет","D = −8","−8"],"show":"D = −8, корней нет"}],"sym":"²","h":["Подумай: «Сколько действительных корней у x² + 2x + 5 = 0?»","Считаем D: 2² − 4 · 1 · 5 = −16. Действительного квадратного корня из −16 нет. Значит, у уравнения нет действительных корней."]},{"n":222,"lab":"34.5","blk":"h","cls":8,"topic":"Углы многоугольника","err":"Умножает число сторон на 180°","type":"sub","q":"<p>Найди сумму внутренних углов выпуклого многоугольника.</p><ol class=\"subq\"><li>Четырёхугольник</li><li>Шестиугольник</li><li>Восьмиугольник</li></ol>","subs":[{"k":"e","v":"360","var":[],"show":"360°"},{"k":"e","v":"720","var":[],"show":"720°"},{"k":"e","v":"1080","var":[],"show":"1080°"}],"sym":"°","h":["Подумай: «Какова сумма внутренних углов выпуклого пятиугольника?»","Проведём диагонали из одной вершины. Получатся три треугольника. Сумма их углов и есть сумма углов пятиугольника: (5 − 2) · 180° = 540°."]},{"n":223,"lab":"34.6","blk":"h","cls":8,"topic":"Углы многоугольника","err":"Принимает сумму углов за один угол","type":"sub","q":"<p>Найди внутренний угол правильного многоугольника.</p><ol class=\"subq\"><li>Пятиугольник</li><li>Восьмиугольник</li><li>Десятиугольник</li></ol>","subs":[{"k":"e","v":"108","var":[],"show":"108°"},{"k":"e","v":"135","var":[],"show":"135°"},{"k":"e","v":"144","var":[],"show":"144°"}],"sym":"°","h":["Подумай: «Каков один внутренний угол правильного шестиугольника?»","Сначала находим сумму всех углов: (6 − 2) · 180° = 720°. У правильного шестиугольника все шесть углов равны. Делим 720° на 6 и получаем 120°."]},{"n":224,"lab":"35.3","blk":"h","cls":8,"topic":"Допустимые значения переменной","err":"Требует, чтобы под корнем было строго больше нуля","type":"sub","q":"<p>Найди допустимые значения x.</p><ol class=\"subq\"><li>Корень из x − 2</li><li>Корень из x + 4</li><li>Корень из 7 − x</li></ol>","subs":[{"k":"t","v":["x ≥ 2"],"show":"x ≥ 2"},{"k":"t","v":["x ≥ −4"],"show":"x ≥ −4"},{"k":"t","v":["x ≤ 7"],"show":"x ≤ 7"}],"sym":"≤≥","h":["Подумай: «При каком x существует корень из x − 5? Подходит ли x = 5?»","Корень существует, если подкоренное выражение неотрицательно. При x = 5 получаем корень из нуля. Поэтому решаем x − 5 ≥ 0 и включаем границу."]},{"n":225,"lab":"35.4","blk":"h","cls":8,"topic":"Допустимые значения переменной","err":"Допускает нулевой корень в знаменателе","type":"sub","q":"<p>Найди допустимые x, если корень стоит в знаменателе.</p><ol class=\"subq\"><li>Корень из x − 2</li><li>Корень из x + 5</li><li>Корень из 4 − x</li></ol>","subs":[{"k":"t","v":["x > 2",">"],"show":"x > 2"},{"k":"t","v":["x > −5",">"],"show":"x > −5"},{"k":"t","v":["x < 4","<"],"show":"x < 4"}],"sym":"","h":["Подумай: «Если в знаменателе корень из x − 3, подходит ли x = 3?»","Корень в знаменателе должен существовать и быть отличным от нуля. При x = 3 знаменатель равен нулю. Значит, подкоренное выражение должно быть строго больше 0."]},{"n":226,"lab":"35.5","blk":"h","cls":8,"topic":"Теорема о биссектрисе треугольника","err":"Приравнивает части стороны у биссектрисы","type":"sub","q":"<p>Даны AB, AC и BC. Найди BD и DC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"18.0 -12.5 113.6 84.2\" width=\"250\" height=\"185\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M57.1,10.1 L37.0,49.0 M57.1,10.1 L110.0,49.0 M37.0,49.0 L110.0,49.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M57.1,10.1 L66.2,49.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M53.0,19.2 C54.8,20.0 56.9,20.3 58.8,19.9\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M59.9,19.7 C61.8,19.1 63.5,18.0 64.8,16.4\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"50.1\" y=\"4.1\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"27.0\" y=\"51.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"116.0\" y=\"51.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"60.2\" y=\"61.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>7, 14, 15</li><li>8, 12, 15</li><li>10, 15, 20</li></ol>","subs":[{"k":"set","v":["5","10"],"show":"5 и 10"},{"k":"set","v":["6","9"],"show":"6 и 9"},{"k":"set","v":["8","12"],"show":"8 и 12"}],"sym":"","h":["Подумай: «AD — биссектриса, AB = 6, AC = 9, BC = 10. Как найти BD и DC?»","Биссектриса делит противоположную сторону в отношении прилежащих сторон: BD : DC = 6 : 9 = 2 : 3. На пять долей приходится 10. Получаем отрезки 4 и 6."]},{"n":227,"lab":"35.6","blk":"h","cls":8,"topic":"Теорема о биссектрисе треугольника","err":"Переворачивает отношение отрезков","type":"sub","q":"<p>Даны AB, AC и BD. Найди DC.</p><ol class=\"subq\"><li>6, 9, 4</li><li>8, 12, 6</li><li>5, 10, 4</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"8","var":[],"show":"8"}],"sym":"","h":["Подумай: «AD — биссектриса. AB = 4, AC = 6, BD = 3. Чему равен DC?»","Отрезок BD примыкает к вершине B, как и сторона AB. Отрезок DC примыкает к C, как и сторона AC. Поэтому 3 : DC = 4 : 6. Отсюда DC = 4,5."]},{"n":228,"lab":"36.3","blk":"h","cls":8,"topic":"Относительная частота события","err":"Принимает число успехов за относительную частоту","type":"sub","q":"<p>Запиши относительную частоту десятичной дробью.</p><ol class=\"subq\"><li>3 из 10</li><li>7 из 20</li><li>12 из 25</li></ol>","subs":[{"k":"e","v":"0,3","var":[],"show":"0,3"},{"k":"e","v":"0,35","var":[],"show":"0,35"},{"k":"e","v":"0,48","var":[],"show":"0,48"}],"sym":"","h":["Подумай: «Из 20 бросков монеты орёл выпал 8 раз. Какова его частота в долях?»","Восемь — число выпадений орла. Относительная частота — доля бросков с орлом. Делим 8 на общее число бросков, то есть на 20."],"flag":{"dec":true}},{"n":229,"lab":"36.4","blk":"h","cls":8,"topic":"Относительная частота события","err":"Усредняет частоты серий разного размера","type":"sub","q":"<p>Найди общую относительную частоту двух серий.</p><ol class=\"subq\"><li>2 из 10, 8 из 30</li><li>5 из 10, 13 из 30</li><li>6 из 10, 4 из 15</li></ol>","subs":[{"k":"e","v":"0,25","var":[],"show":"0,25"},{"k":"e","v":"0,45","var":[],"show":"0,45"},{"k":"e","v":"0,4","var":[],"show":"0,4"}],"sym":"","h":["Подумай: «Орёл выпал 4 раза из 10 и 6 раз из 30. Какова общая частота?»","Складываем число выпадений: 4 + 6 = 10. Складываем число бросков: 10 + 30 = 40. Для общей частоты делим 10 на 40 и получаем 0,25."]},{"n":230,"lab":"37.5","blk":"h","cls":8,"topic":"Треугольники с общей высотой","err":"Сравнивает площади по наклонным сторонам","type":"sub","q":"<p>Во сколько раз площадь DBC больше площади DAB?.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"9.0 -11.6 159.6 80.3\" width=\"300\" height=\"151\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M29.0,46.0 L53.0,10.0 L149.0,46.0 L29.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M53.0,10.0 L69.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M53.0,10.0 L53.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-dasharray=\"4 3\"/><text x=\"18.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"63.0\" y=\"58.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"153.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"47.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>AB = 2, BC = 8</li><li>AB = 4, BC = 6</li><li>AB = 5, BC = 15</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"1,5","var":[],"show":"1,5"},{"k":"e","v":"3","var":[],"show":"3"}],"sym":"","h":["Подумай: «AB = 3, BC = 6. Во сколько раз площадь DBC больше площади DAB?»","Основания AB и BC лежат на одной прямой. У треугольников одна высота из D к этой прямой. Поэтому отношение площадей равно 6 : 3 = 2."]},{"n":231,"lab":"37.6","blk":"h","cls":8,"topic":"Треугольники с общей высотой","err":"Делит площадь пополам при любом разбиении","type":"sub","q":"<p>Какую долю площади DAC занимает DAB?.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"9.0 -11.6 159.6 80.3\" width=\"300\" height=\"151\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M29.0,46.0 L53.0,10.0 L149.0,46.0 L29.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M53.0,10.0 L77.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M53.0,10.0 L53.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-dasharray=\"4 3\"/><text x=\"18.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"71.0\" y=\"58.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"153.0\" y=\"49.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"47.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>AB : BC = 1 : 3</li><li>AB : BC = 3 : 4</li><li>AB : BC = 2 : 5</li></ol>","subs":[{"k":"e","v":"1/4","var":[],"show":"1/4"},{"k":"e","v":"3/7","var":[],"show":"3/7"},{"k":"e","v":"2/7","var":[],"show":"2/7"}],"sym":"","h":["Подумай: «AB : BC = 2 : 3. Какую долю площади DAC занимает DAB на рисунке?»","Площади частей относятся как их основания: 2 : 3. Всему треугольнику соответствует 5 долей площади. Меньшей части DAB соответствуют 2 из 5 долей."]},{"n":232,"lab":"39.3","blk":"h","cls":8,"topic":"Выделение квадрата двучлена","err":"Берёт весь коэффициент внутрь квадрата","type":"sub","q":"<p>Выдели квадрат двучлена.</p><ol class=\"subq\"><li>x² + 4x + 7</li><li>x² − 8x + 20</li><li>x² + 10x + 27</li></ol>","subs":[{"k":"e","v":"(x + 2)² + 3","var":[],"show":"(x + 2)² + 3"},{"k":"e","v":"(x − 4)² + 4","var":[],"show":"(x − 4)² + 4"},{"k":"e","v":"(x + 5)² + 2","var":[],"show":"(x + 5)² + 2"}],"sym":"²","h":["Подумай: «Как выделить квадрат в x² + 6x + 11? Какое число взять в скобки?»","В квадрате (x + p)² среднее слагаемое равно 2px. Чтобы получить 6x, берём p = 3. Из 11 вычитаем 9, уже учтённые в квадрате. Остаётся 2."],"flag":{"par":true}},{"n":233,"lab":"39.4","blk":"h","cls":8,"topic":"Выделение квадрата двучлена","err":"Забывает компенсировать добавленный квадрат","type":"sub","q":"<p>Выдели квадрат двучлена.</p><ol class=\"subq\"><li>x² + 2x</li><li>x² − 6x</li><li>x² + 12x</li></ol>","subs":[{"k":"e","v":"(x + 1)² − 1","var":[],"show":"(x + 1)² − 1"},{"k":"e","v":"(x − 3)² − 9","var":[],"show":"(x − 3)² − 9"},{"k":"e","v":"(x + 6)² − 36","var":[],"show":"(x + 6)² − 36"}],"sym":"²","h":["Подумай: «Верно ли x² − 4x = (x − 2)²? Что изменилось справа?»","В квадрате (x − 2)² появляется лишнее слагаемое 4. Вычитаем его, чтобы сохранить исходное выражение. Получаем x² − 4x = (x − 2)² − 4."],"flag":{"par":true}},{"n":234,"lab":"39.5","blk":"h","cls":8,"topic":"Площадь параллелограмма","err":"Перемножает две соседние стороны","type":"sub","q":"<p>Найди площадь. Основание и высота даны в см.</p><ol class=\"subq\"><li>a = 7, h = 4</li><li>a = 9, h = 5</li><li>a = 12, h = 3</li></ol>","subs":[{"k":"e","v":"28","var":[],"show":"28 см²"},{"k":"e","v":"45","var":[],"show":"45 см²"},{"k":"e","v":"36","var":[],"show":"36 см²"}],"sym":"²","h":["Подумай: «Стороны 8 и 5 см, высота к стороне 8 см равна 3 см. Найди площадь.»","Площадь равна произведению основания на высоту к нему. Высота перпендикулярна основанию. На рисунке она равна 3 см. Умножаем 8 на 3 и получаем 24 см²."]},{"n":235,"lab":"39.6","blk":"h","cls":8,"topic":"Площадь параллелограмма","err":"Берёт высоту к другой стороне","type":"sub","q":"<p>Найди высоту. Площадь дана в см², основание в см.</p><ol class=\"subq\"><li>S = 18, a = 6</li><li>S = 30, a = 8</li><li>S = 40, a = 5</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3 см"},{"k":"e","v":"3,75","var":[],"show":"3,75 см"},{"k":"e","v":"8","var":[],"show":"8 см"}],"sym":"²","h":["Подумай: «Площадь 24 см², стороны 8 и 5 см. Найди высоту к стороне 5 см.»","Для высоты к стороне 5 см основание равно 5 см. Записываем 24 = 5 · h. Делим 24 на 5. Получаем 4,8 см. К стороне 8 см высота равна 3 см."]},{"n":236,"lab":"40.5","blk":"h","cls":8,"topic":"Преобразование выражений с корнями","err":"Складывает числа под одинаковыми корнями","type":"sub","q":"<p>Приведи подобные слагаемые.</p><ol class=\"subq\"><li>3<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">2</span></span> + 4<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">2</span></span></li><li>8<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> − 2<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span></li><li>2<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span> + 6<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span></li></ol>","subs":[{"k":"e","v":"7√2","var":[],"show":"7√2"},{"k":"e","v":"6√5","var":[],"show":"6√5"},{"k":"e","v":"8√7","var":[],"show":"8√7"}],"sym":"√","h":["Подумай: «Упрости 2<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> + 5<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span>. Что здесь повторяется?»","Оба слагаемых содержат один и тот же множитель <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span>. Складываем коэффициенты 2 и 5, а <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> сохраняем. Получаем семь корней из трёх: 7<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span>."],"flag":{"nopar":true}},{"n":237,"lab":"40.6","blk":"h","cls":8,"topic":"Преобразование выражений с корнями","err":"Раскрывает сопряжённые скобки как квадрат","type":"sub","q":"<p>Упрости произведение.</p><ol class=\"subq\"><li>(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span> − 2)(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span> + 2)</li><li>(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">6</span></span> − 1)(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">6</span></span> + 1)</li><li>(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">13</span></span> − 3)(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">13</span></span> + 3)</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"4","var":[],"show":"4"}],"sym":"√","h":["Подумай: «Упрости (<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> − 2)(<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> + 2). Какие слагаемые сократятся?»","Скобки отличаются знаком второго слагаемого. При раскрытии получаем −2<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> и +2<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span>. Их сумма равна нулю. Остаётся разность квадратов: 5 − 4 = 1."]},{"n":238,"lab":"41.3","blk":"h","cls":8,"topic":"Вероятность при двух бросках","err":"Считает ОР и РО одним исходом","type":"sub","q":"<p>Найди вероятность при двух бросках честной монеты.</p><ol class=\"subq\"><li>Орёл дважды</li><li>Решка дважды</li><li>Хотя бы один орёл</li></ol>","subs":[{"k":"e","v":"1/4","var":[],"show":"1/4"},{"k":"e","v":"1/4","var":[],"show":"1/4"},{"k":"e","v":"3/4","var":[],"show":"3/4"}],"sym":"","h":["Подумай: «Два броска честной монеты. Какова вероятность ровно одного орла?»","В четырёх равновероятных исходах важен порядок. Орёл на первом броске и орёл на втором дают два исхода. Ровно один орёл выпадает в двух случаях из четырёх."]},{"n":239,"lab":"41.4","blk":"h","cls":8,"topic":"Вероятность при двух бросках","err":"Складывает вероятности двух успехов подряд","type":"sub","q":"<p>Найди вероятность при двух бросках честного кубика.</p><ol class=\"subq\"><li>Две единицы</li><li>Сначала 1, потом 6</li><li>Одинаковые числа</li></ol>","subs":[{"k":"e","v":"1/36","var":[],"show":"1/36"},{"k":"e","v":"1/36","var":[],"show":"1/36"},{"k":"e","v":"1/6","var":[],"show":"1/6"}],"sym":"","h":["Подумай: «Честный кубик бросают дважды. Какова вероятность двух шестёрок?»","Для каждой пары результатов есть 6 вариантов первого броска и 6 вариантов второго. Всего 6 · 6 = 36 пар. Из них условию отвечает одна пара: (6; 6)."]},{"n":240,"lab":"41.5","blk":"h","cls":8,"topic":"Диагонали квадрата","err":"Принимает диагональ квадрата за его сторону","type":"sub","q":"<p>Найди длину диагонали квадрата.</p><ol class=\"subq\"><li>Сторона 3 см</li><li>Сторона 6 см</li><li>Сторона 10 см</li></ol>","subs":[{"k":"e","v":"3√2","var":[],"show":"3√2 см"},{"k":"e","v":"6√2","var":[],"show":"6√2 см"},{"k":"e","v":"10√2","var":[],"show":"10√2 см"}],"sym":"√","h":["Подумай: «Сторона квадрата 5 см. Как найти длину диагонали?»","Диагональ — гипотенуза прямоугольного треугольника. Оба катета равны стороне квадрата. По теореме Пифагора квадрат диагонали равен 25 + 25 = 50."]},{"n":241,"lab":"41.6","blk":"h","cls":8,"topic":"Диагонали квадрата","err":"Считает угол диагонали со стороной прямым","type":"sub","q":"<p>Найди меньший угол между отрезками квадрата ABCD.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"32.0 -4.6 74.6 67.3\" width=\"164\" height=\"148\" role=\"img\" aria-label=\"Рисунок к заданию\"><rect x=\"52.0\" y=\"12.0\" width=\"35.0\" height=\"35.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M52.0,47.0 L87.0,12.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M52.0,12.0 L87.0,47.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M62.0,47.0 C62.0,44.3 60.9,41.8 59.1,39.9\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"41.0\" y=\"52.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"91.0\" y=\"52.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"91.0\" y=\"12.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"41.0\" y=\"12.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>AC и AB</li><li>AC и BD</li><li>AB и BC</li></ol>","subs":[{"k":"e","v":"45","var":[],"show":"45°"},{"k":"e","v":"90","var":[],"show":"90°"},{"k":"e","v":"90","var":[],"show":"90°"}],"sym":"°","h":["Подумай: «Какой угол образуют диагональ AC и сторона AB квадрата?»","Диагональ делит прямой угол A пополам. Поэтому угол между диагональю и стороной равен 45°. Прямой угол образуют две диагонали между собой."]},{"n":242,"lab":"42.3","blk":"h","cls":8,"topic":"Стандартный вид числа","err":"Оставляет перед запятой больше одной цифры","type":"sub","q":"<p>Запиши в стандартном виде.</p><ol class=\"subq\"><li>38 000</li><li>560 000</li><li>7200</li></ol>","subs":[{"k":"e","v":"3,8 · 10⁴","var":[],"show":"3,8 · 10⁴"},{"k":"e","v":"5,6 · 10⁵","var":[],"show":"5,6 · 10⁵"},{"k":"e","v":"7,2 · 10³","var":[],"show":"7,2 · 10³"}],"sym":"³","h":["Подумай: «Как записать 47 000 в стандартном виде? Подойдёт ли 47 · 10³?»","В стандартной записи положительного числа множитель перед степенью десяти не меньше 1 и меньше 10. Переносим запятую на четыре разряда: 47 000 = 4,7 · 10⁴."]},{"n":243,"lab":"42.4","blk":"h","cls":8,"topic":"Стандартный вид числа","err":"Ставит плюс у показателя для малого числа","type":"sub","q":"<p>Запиши в стандартном виде.</p><ol class=\"subq\"><li>0,045</li><li>0,00081</li><li>0,9</li></ol>","subs":[{"k":"e","v":"4,5 · 10⁻²","var":[],"show":"4,5 · 10⁻²"},{"k":"e","v":"8,1 · 10⁻⁴","var":[],"show":"8,1 · 10⁻⁴"},{"k":"e","v":"9 · 10⁻¹","var":[],"show":"9 · 10⁻¹"}],"sym":"²","h":["Подумай: «Как записать 0,0062 в стандартном виде?»","Переносим запятую на три разряда вправо и получаем 6,2. Чтобы вернуться к 0,0062, делим 6,2 на 1000. Деление на 1000 заменяем умножением на 10⁻³."]},{"n":244,"lab":"42.5","blk":"h","cls":8,"topic":"Проекции катетов на гипотенузу","err":"Берёт не ту проекцию катета","type":"sub","q":"<p>Назови проекцию отрезка на AB.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"12.0 -11.6 107.6 81.3\" width=\"237\" height=\"179\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M30.0,46.0 L57.0,10.0 L105.0,46.0 L30.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M30.0,46.0 L57.0,46.0 L57.0,10.0 M57.0,41.0 L62.0,41.0 L62.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"21.0\" y=\"59.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"104.0\" y=\"57.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"53.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"51.0\" y=\"59.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">H</text></svg></div><ol class=\"subq\"><li>Проекция AC</li><li>Проекция BC</li><li>Проекция CH</li></ol>","subs":[{"k":"t","v":["AH"],"show":"AH"},{"k":"t","v":["BH"],"show":"BH"},{"k":"t","v":["Точка H"],"show":"Точка H"}],"sym":"","h":["Подумай: «В ABC угол C прямой, CH — высота. Какова проекция AC на AB?»","Точка A уже лежит на гипотенузе AB. Точка C проецируется в H. Значит, проекция AC — AH. Для катета CB проекция будет HB."]},{"n":245,"lab":"42.6","blk":"h","cls":8,"topic":"Проекции катетов на гипотенузу","err":"Приравнивает катет к его проекции","type":"sub","q":"<p>Найди катет AC по гипотенузе AB и проекции AH.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"12.0 -11.6 107.6 81.3\" width=\"237\" height=\"179\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M30.0,46.0 L57.0,10.0 L105.0,46.0 L30.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M30.0,46.0 L57.0,46.0 L57.0,10.0 M57.0,41.0 L62.0,41.0 L62.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"21.0\" y=\"59.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"104.0\" y=\"57.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"53.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"51.0\" y=\"59.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">H</text></svg></div><ol class=\"subq\"><li>AB = 10, AH = 3,6</li><li>AB = 20, AH = 5</li><li>AB = 25, AH = 16</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"20","var":[],"show":"20"}],"sym":"","h":["Подумай: «Гипотенуза AB = 25, проекция AH = 9. Чему равен катет AC?»","Квадрат катета равен произведению гипотенузы на проекцию этого катета: AC² = AB · AH. Получаем AC² = 225, а значит, AC = 15."]},{"n":246,"lab":"43.5","blk":"h","cls":8,"topic":"Диагонали равнобедренной трапеции","err":"Путает диагональ трапеции с боковой стороной","type":"sub","q":"<p>Найди длину диагонали.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"-6.0 -10.6 118.6 71.3\" width=\"261\" height=\"157\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M13.0,45.0 L29.0,13.0 L77.0,13.0 L93.0,45.0 L13.0,45.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M13.0,45.0 L77.0,13.0 M29.0,13.0 L93.0,45.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"3.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"18.0\" y=\"6.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"81.0\" y=\"9.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"97.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>AC = 9. BD = ?</li><li>BD = 14. AC = ?</li><li>AC + BD = 24. AC = ?</li></ol>","subs":[{"k":"e","v":"9","var":[],"show":"9"},{"k":"e","v":"14","var":[],"show":"14"},{"k":"e","v":"12","var":[],"show":"12"}],"sym":"","h":["Подумай: «В равнобедренной трапеции AC = 13. Чему равна BD?»","Диагонали соединяют противоположные вершины. У равнобедренной трапеции диагонали равны: AC = BD. Боковые стороны образуют другую пару равных отрезков."]},{"n":247,"lab":"43.6","blk":"h","cls":8,"topic":"Диагонали равнобедренной трапеции","err":"Делит диагонали трапеции пополам","type":"sub","q":"<p>Найди отношение AO : OC.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"-6.0 -10.6 118.6 71.3\" width=\"261\" height=\"157\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M13.0,45.0 L29.0,13.0 L77.0,13.0 L93.0,45.0 L13.0,45.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M13.0,45.0 L77.0,13.0 M29.0,13.0 L93.0,45.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"3.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"18.0\" y=\"6.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"81.0\" y=\"9.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"97.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text><text x=\"49.0\" y=\"39.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">O</text></svg></div><ol class=\"subq\"><li>AD = 12, BC = 4</li><li>AD = 15, BC = 10</li><li>AD = 14, BC = 8</li></ol>","subs":[{"k":"t","v":["3 : 1"],"show":"3 : 1"},{"k":"t","v":["3 : 2"],"show":"3 : 2"},{"k":"t","v":["7 : 4"],"show":"7 : 4"}],"sym":"","h":["Подумай: «Основания трапеции 10 и 6. Делит ли точка O диагонали пополам?»","Равные диагонали могут пересекаться вне своих середин. Отрезки AO и OC относятся как основания AD и BC. Здесь AO : OC = 10 : 6, поэтому AO длиннее OC."]},{"n":248,"lab":"44.1","blk":"h","cls":8,"topic":"Числовые промежутки","err":"Ставит квадратную скобку у бесконечности","type":"sub","q":"<p>Запиши числовой промежуток.</p><ol class=\"subq\"><li>x ≥ 3</li><li>x ≤ 0</li><li>x &gt; −2</li></ol>","subs":[{"k":"t","v":["[3; +∞)"],"show":"[3; +∞)"},{"k":"t","v":["(−∞; 0]"],"show":"(−∞; 0]"},{"k":"t","v":["(−2; +∞)"],"show":"(−2; +∞)"}],"sym":"≤≥∞","h":["Подумай: «Как записать все x ≥ 2? Какую скобку поставить у +∞?»","Число 2 входит в промежуток, поэтому слева скобка квадратная. Знак +∞ показывает, что верхней границы нет. Около бесконечности всегда ставим круглую скобку."]},{"n":249,"lab":"44.2","blk":"h","cls":8,"topic":"Числовые промежутки","err":"Записывает прямую с выколотой точкой целиком","type":"sub","q":"<p>Запиши объединение двух промежутков.</p><ol class=\"subq\"><li>Все числа, кроме 0</li><li>Все числа, кроме −3</li><li>Все числа, кроме 5</li></ol>","subs":[{"k":"t","v":["(−∞; 0) ∪ (0; +∞)"],"show":"(−∞; 0) ∪ (0; +∞)"},{"k":"t","v":["(−∞; −3) ∪ (−3; +∞)"],"show":"(−∞; −3) ∪ (−3; +∞)"},{"k":"t","v":["(−∞; 5) ∪ (5; +∞)"],"show":"(−∞; 5) ∪ (5; +∞)"}],"sym":"∞","h":["Подумай: «Как записать все числа, кроме 2, с помощью промежутков?»","Все числа левее 2 образуют один промежуток. Все числа правее 2 образуют другой промежуток. Объединяем их, оставляя обе скобки у 2 круглыми."]},{"n":250,"lab":"45.3","blk":"h","cls":8,"topic":"Сложение и вычитание рациональных дробей","err":"Складывает знаменатели с переменной","type":"sub","q":"<p>Упрости при ненулевых знаменателях.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>x</span></span> + <span class=\"fr\"><span>4</span><span>x</span></span></li><li><span class=\"fr\"><span>7</span><span>y</span></span> − <span class=\"fr\"><span>2</span><span>y</span></span></li><li><span class=\"fr\"><span>2</span><span>a</span></span> + <span class=\"fr\"><span>6</span><span>a</span></span></li></ol>","subs":[{"k":"e","v":"5/x","var":[],"show":"5/x"},{"k":"e","v":"5/y","var":[],"show":"5/y"},{"k":"e","v":"8/a","var":[],"show":"8/a"}],"sym":"","h":["Подумай: «Как сложить <span class=\"fr\"><span>2</span><span>x</span></span> и <span class=\"fr\"><span>3</span><span>x</span></span>, если x ≠ 0?»","Знаменатели уже одинаковые. Оба слагаемых записаны в долях с одним знаменателем. Складываем только числители: 2 + 3 = 5."]},{"n":251,"lab":"45.4","blk":"h","cls":8,"topic":"Сложение и вычитание рациональных дробей","err":"Домножает только знаменатель","type":"sub","q":"<p>Упрости при ненулевых знаменателях.</p><ol class=\"subq\"><li><span class=\"fr\"><span>1</span><span>x</span></span> + <span class=\"fr\"><span>1</span><span>3x</span></span></li><li><span class=\"fr\"><span>1</span><span>y</span></span> − <span class=\"fr\"><span>1</span><span>4y</span></span></li><li><span class=\"fr\"><span>1</span><span>a</span></span> + <span class=\"fr\"><span>3</span><span>2a</span></span></li></ol>","subs":[{"k":"e","v":"4/(3x)","var":[],"show":"4/(3x)"},{"k":"e","v":"3/(4y)","var":[],"show":"3/(4y)"},{"k":"e","v":"5/(2a)","var":[],"show":"5/(2a)"}],"sym":"","h":["Подумай: «Как добавить <span class=\"fr\"><span>1</span><span>x</span></span> к <span class=\"fr\"><span>1</span><span>2x</span></span>, если x ≠ 0?»","Общий знаменатель равен 2x. Первую дробь умножаем на <span class=\"fr\"><span>2</span><span>2</span></span>, поэтому в её числителе появляется 2. Теперь складываем числители: 2 + 1 = 3."]},{"n":252,"lab":"46.3","blk":"h","cls":8,"topic":"Умножение и деление рациональных дробей","err":"Сокращает слагаемое вместо множителя","type":"sub","q":"<p>Упрости при ненулевых знаменателях.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x+1</span><span>3</span></span> · <span class=\"fr\"><span>6</span><span>x</span></span></li><li><span class=\"fr\"><span>y−2</span><span>4</span></span> · <span class=\"fr\"><span>8</span><span>y</span></span></li><li><span class=\"fr\"><span>a+5</span><span>5</span></span> · <span class=\"fr\"><span>15</span><span>a</span></span></li></ol>","subs":[{"k":"e","v":"(2(x+1))/x","var":[],"show":"(2(x+1))/x"},{"k":"e","v":"(2(y−2))/y","var":[],"show":"(2(y−2))/y"},{"k":"e","v":"(3(a+5))/a","var":[],"show":"(3(a+5))/a"}],"sym":"","h":["Подумай: «Можно ли сразу сократить x в произведении <span class=\"fr\"><span>x+3</span><span>2</span></span> · <span class=\"fr\"><span>4</span><span>x</span></span>?»","В числителе x + 3 число x входит в сумму. Сокращаем общие множители целиком: 4 и 2 дают 2. Получаем дробь с числителем 2(x + 3) и знаменателем x."]},{"n":253,"lab":"46.4","blk":"h","cls":8,"topic":"Умножение и деление рациональных дробей","err":"Забывает, что делитель не может быть нулём","type":"sub","q":"<p>Укажи, когда делитель равен нулю, и исключи это значение.</p><ol class=\"subq\"><li><span class=\"fr\"><span>x</span><span>2</span></span> : <span class=\"fr\"><span>x−3</span><span>5</span></span></li><li><span class=\"fr\"><span>y</span><span>3</span></span> : <span class=\"fr\"><span>y+2</span><span>4</span></span></li><li><span class=\"fr\"><span>a</span><span>7</span></span> : <span class=\"fr\"><span>2a</span><span>3</span></span></li></ol>","subs":[{"k":"t","v":["x ≠ 3"],"show":"x ≠ 3"},{"k":"t","v":["y ≠ −2"],"show":"y ≠ −2"},{"k":"t","v":["a ≠ 0"],"show":"a ≠ 0"}],"sym":"≠","h":["Подумай: «После деления <span class=\"fr\"><span>x</span><span>2</span></span> : <span class=\"fr\"><span>x−1</span><span>3</span></span> подходит ли x = 1?»","При x = 1 вторая дробь равна нулю. Делить на ноль нельзя. Исключаем x = 1 до преобразований. Затем умножаем первую дробь на обратную ко второй."]},{"n":254,"lab":"47.5","blk":"h","cls":8,"topic":"Процентные изменения","err":"Путает проценты и процентные пункты","type":"sub","q":"<p>Найди рост в процентных пунктах.</p><ol class=\"subq\"><li>12% → 16%</li><li>30% → 35%</li><li>46% → 50%</li></ol>","subs":[{"k":"e","v":"4","var":[],"show":"4 п. п."},{"k":"e","v":"5","var":[],"show":"5 п. п."},{"k":"e","v":"4","var":[],"show":"4 п. п."}],"sym":"","h":["Подумай: «Доля выросла с 20% до 25%. На сколько процентных пунктов?»","Разность двух долей в процентах выражаем в процентных пунктах: 25 − 20 = 5. Для относительного роста делим разность на исходное значение: 5 : 20 = 0,25, или 25%."]},{"n":255,"lab":"48.3","blk":"h","cls":8,"topic":"Освобождение знаменателя от корня","err":"Убирает корень только в знаменателе","type":"sub","q":"<p>Избавься от корня в знаменателе.</p><ol class=\"subq\"><li>1/<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span></li><li>2/<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span></li><li>3/<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">2</span></span></li></ol>","subs":[{"k":"e","v":"√3/3","var":[],"show":"√3/3"},{"k":"e","v":"(2√7)/7","var":[],"show":"(2√7)/7"},{"k":"e","v":"(3√2)/2","var":[],"show":"(3√2)/2"}],"sym":"√","h":["Подумай: «Как записать 1/<span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> без корня в знаменателе?»","Умножаем числитель и знаменатель на один и тот же <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span>. В знаменателе получается <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> · <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> = 5. Числитель тоже меняется: 1 · <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> = <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span>."],"flag":{"noroot":true}},{"n":256,"lab":"48.4","blk":"h","cls":8,"topic":"Освобождение знаменателя от корня","err":"Выбирает скобку с прежним знаком","type":"sub","q":"<p>Назови множитель для числителя и знаменателя.</p><ol class=\"subq\"><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">5</span></span> + 2</li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">7</span></span> − 2</li><li><span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">2</span></span> + 3</li></ol>","subs":[{"k":"e","v":"√5 − 2","var":[],"show":"√5 − 2"},{"k":"e","v":"√7 + 2","var":[],"show":"√7 + 2"},{"k":"e","v":"√2 − 3","var":[],"show":"√2 − 3"}],"sym":"√","h":["Подумай: «На что домножить знаменатель <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> + 1, чтобы убрать корень?»","Берём <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> − 1. При умножении суммы на разность слагаемые с <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> сокращаются. В знаменателе остаётся 2. На <span class=\"rt\"><span class=\"rs\">√</span><span class=\"rv\">3</span></span> − 1 умножаем и числитель."]},{"n":257,"lab":"48.5","blk":"h","cls":8,"topic":"Углы трапеции","err":"Считает равными углы при боковой стороне","type":"sub","q":"<p>В трапеции AD ∥ BC. Найди угол B по углу A.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"16.0 -8.6 138.6 69.3\" width=\"300\" height=\"150\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M37.0,46.0 L134.0,46.0 L122.4,14.0 L48.6,14.0 L37.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"25.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"37.6\" y=\"8.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"125.4\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"139.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>∠A = 50°</li><li>∠A = 115°</li><li>∠A = 83°</li></ol>","subs":[{"k":"e","v":"130","var":[],"show":"130°"},{"k":"e","v":"65","var":[],"show":"65°"},{"k":"e","v":"97","var":[],"show":"97°"}],"sym":"°","h":["Подумай: «В трапеции AD ∥ BC, угол A равен 70°. Каков угол B?»","Углы A и B лежат между основаниями по одну сторону от секущей AB. В сумме они дают 180°. Значит, угол B равен 110°."]},{"n":258,"lab":"48.6","blk":"h","cls":8,"topic":"Углы трапеции","err":"Переносит равенство углов на разные основания","type":"sub","q":"<p>Найди угол D в равнобедренной трапеции по углу A.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"16.0 -8.6 138.6 69.3\" width=\"300\" height=\"150\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M37.0,46.0 L134.0,46.0 L123.6,14.0 L47.4,14.0 L37.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"25.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"36.4\" y=\"8.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"126.6\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text><text x=\"139.0\" y=\"50.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">D</text></svg></div><ol class=\"subq\"><li>∠A = 64°</li><li>∠A = 82°</li><li>∠A = 53°</li></ol>","subs":[{"k":"e","v":"64","var":[],"show":"64°"},{"k":"e","v":"82","var":[],"show":"82°"},{"k":"e","v":"53","var":[],"show":"53°"}],"sym":"°","h":["Подумай: «В равнобедренной трапеции AD ∥ BC, угол A равен 72°. Каков D?»","Углы A и D лежат при одном основании AD, поэтому равны. Углы B и C лежат при другом основании. Их величина равна 180° − 72° = 108°."]},{"n":259,"lab":"03.2","blk":"h","cls":9,"topic":"Проценты","err":"Считает скидку от первоначальной цены дважды","type":"sub","q":"<p>Найди цену после двух скидок.</p><ol class=\"subq\"><li>200 ₽, дважды 10%</li><li>400 ₽, дважды 25%</li><li>800 ₽, дважды 50%</li></ol>","subs":[{"k":"e","v":"162","var":[],"show":"162 ₽"},{"k":"e","v":"225","var":[],"show":"225 ₽"},{"k":"e","v":"200","var":[],"show":"200 ₽"}],"sym":"","h":["Подумай: «Цена 500 ₽. Две скидки по 10% подряд. От какой цены вторая?»","После первой скидки цена стала 450 ₽. Теперь 450 ₽ составляют 100% для второго расчёта. 10% от 450 ₽ равны 45 ₽."]},{"n":260,"lab":"05.3","blk":"h","cls":9,"topic":"Арифметическая прогрессия","err":"Отсчитывает n шагов вместо n − 1","type":"sub","q":"<p>Найди указанный член.</p><ol class=\"subq\"><li>a₁ = 2, d = 4, a₅</li><li>a₁ = 9, d = −2, a₆</li><li>a₁ = −3, d = 5, a₄</li></ol>","subs":[{"k":"e","v":"18","var":[],"show":"18"},{"k":"e","v":"−1","var":[],"show":"−1"},{"k":"e","v":"12","var":[],"show":"12"}],"sym":"","h":["Подумай: «Первый член 4, разность 3. Сколько прибавлений до a₄?»","Первый член уже дан. До четвёртого члена три перехода. От a₁ до aₙ делаем n − 1 переходов. Каждый меняет значение на разность d."]},{"n":261,"lab":"05.4","blk":"h","cls":9,"topic":"Арифметическая прогрессия","err":"Принимает последний член за сумму","type":"sub","q":"<p>Найди a₄ и S₄ в каждой прогрессии.</p><ol class=\"subq\"><li>1, 4, 7, 10</li><li>9, 7, 5, 3</li><li>−5, −2, 1, 4</li></ol>","subs":[{"k":"nums","v":["10","22"],"show":"a₄ = 10, S₄ = 22"},{"k":"nums","v":["3","24"],"show":"a₄ = 3, S₄ = 24"},{"k":"nums","v":["4","−2"],"show":"a₄ = 4, S₄ = −2"}],"sym":"","h":["Подумай: «Найди a₄ и S₄ для прогрессии 2, 5, 8, 11, …».","Четвёртый член a₄ равен 11. Чтобы найти S₄, складываем первые четыре члена. Для проверки можно собрать две пары с одинаковой суммой: 2 + 11 и 5 + 8."]},{"n":262,"lab":"06.3","blk":"h","cls":9,"topic":"Парабола","err":"Ошибается в знаке координаты вершины","type":"sub","q":"<p>Найди координаты вершины.</p><ol class=\"subq\"><li>y = (x − 4)² + 1</li><li>y = (x + 2)² − 3</li><li>y = (x + 1)² + 5</li></ol>","subs":[{"k":"t","v":["(4; 1)","4; 1"],"show":"(4; 1)"},{"k":"t","v":["(−2; −3)","−2; −3"],"show":"(−2; −3)"},{"k":"t","v":["(−1; 5)","−1; 5"],"show":"(−1; 5)"}],"sym":"²","h":["Подумай: «Где вершина параболы y = (x − 3)² + 2?»","Квадрат принимает наименьшее значение, когда скобка равна нулю. При x = 3 получаем y = 2. Вершина (3; 2)."]},{"n":263,"lab":"06.4","blk":"h","cls":9,"topic":"Парабола","err":"Судит о направлении ветвей по знаку c","type":"sub","q":"<p>Куда направлены ветви параболы?.</p><ol class=\"subq\"><li>y = 2x² − 3</li><li>y = −x² + 5</li><li>y = −3x² − 2</li></ol>","subs":[{"k":"t","v":["Вверх"],"show":"Вверх"},{"k":"t","v":["Вниз"],"show":"Вниз"},{"k":"t","v":["Вниз"],"show":"Вниз"}],"sym":"²","h":["Подумай: «Куда направлены ветви параболы y = −x² + 4?»","Смотрим на коэффициент при x². Если a &gt; 0, ветви идут вверх. Если a &lt; 0, вниз. Здесь a = −1."]},{"n":264,"lab":"07.5","blk":"h","cls":9,"topic":"Окружность и круг","err":"Подставляет диаметр вместо радиуса","type":"sub","q":"<p>Найди площадь круга по диаметру.</p><ol class=\"subq\"><li>d = 6 см</li><li>d = 12 см</li><li>d = 14 см</li></ol>","subs":[{"k":"e","v":"9π","var":[],"show":"9π см²"},{"k":"e","v":"36π","var":[],"show":"36π см²"},{"k":"e","v":"49π","var":[],"show":"49π см²"}],"sym":"π²","h":["Подумай: «Диаметр круга равен 10 см. Как найти площадь круга?»","Радиус идёт от центра до окружности. Он равен половине диаметра. Сначала находим r = 10 : 2 = 5 см. В формулу площади S = πr² подставляем 5."]},{"n":265,"lab":"08.3","blk":"h","cls":9,"topic":"Геометрическая прогрессия","err":"Ищет знаменатель прогрессии вычитанием","type":"sub","q":"<p>Найди знаменатель каждой прогрессии.</p><ol class=\"subq\"><li>2, 6, 18</li><li>16, 8, 4</li><li>3, −6, 12</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"q = 3"},{"k":"e","v":"1/2","var":[],"show":"q = 1/2"},{"k":"e","v":"−2","var":[],"show":"q = −2"}],"sym":"","h":["Подумай: «Даны 3, 6, 12, 24. На какое число умножается каждый член?»","В геометрической прогрессии каждый следующий член получаем умножением на одно и то же число q. Чтобы найти q, делим следующий член на предыдущий."]},{"n":266,"lab":"08.4","blk":"h","cls":9,"topic":"Геометрическая прогрессия","err":"Умножает на q в степени n","type":"sub","q":"<p>Найди указанный член прогрессии.</p><ol class=\"subq\"><li>b₁ = 4, q = 2, b₅</li><li>b₁ = 3, q = −2, b₄</li><li>b₁ = 81, q = <span class=\"fr\"><span>1</span><span>3</span></span>, b₃</li></ol>","subs":[{"k":"e","v":"64","var":[],"show":"64"},{"k":"e","v":"−24","var":[],"show":"−24"},{"k":"e","v":"9","var":[],"show":"9"}],"sym":"","h":["Подумай: «Если b₁ = 2 и q = 3, сколько умножений нужно до b₄?»","Первый член уже дан. До b₄ нужно три умножения на 3. До члена с номером n нужно n − 1 умножений. Поэтому bₙ = b₁ · qⁿ⁻¹."]},{"n":267,"lab":"10.2","blk":"h","cls":9,"topic":"Чтение графиков","err":"Ищет нуль функции на оси y","type":"sub","q":"<p>Прочитай по графику.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"43.0 -5.6 147.6 64.6\" width=\"300\" height=\"131\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M54.9,29.0 L170.6,29.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M64.0,51.0 L64.0,7.4\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M90.0,31.0 L90.0,27.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M116.0,31.0 L116.0,27.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M142.0,31.0 L142.0,27.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M59.6,48.5 L157.6,14.6\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"175.0\" y=\"31.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">x</text><text x=\"67.0\" y=\"11.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">y</text><text x=\"52.0\" y=\"41.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">0</text><text x=\"97.0\" y=\"47.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">1</text><text x=\"108.0\" y=\"44.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">2</text><text x=\"134.0\" y=\"44.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">3</text></svg></div><ol class=\"subq\"><li>Нуль функции</li><li>Точка на оси x</li><li>Значение f(2)</li></ol>","subs":[{"k":"e","v":"2","var":[],"show":"2"},{"k":"t","v":["(2; 0)","2; 0"],"show":"(2; 0)"},{"k":"e","v":"0","var":[],"show":"0"}],"sym":"","h":["Подумай: «При каком x значение функции на рисунке равно нулю?»","Нуль функции — значение x, при котором y = 0. Точка с y = 0 лежит на горизонтальной оси. Находим пересечение графика с этой осью и читаем x."]},{"n":268,"lab":"12.3","blk":"h","cls":9,"topic":"Биквадратные уравнения","err":"Принимает значения t за корни уравнения","type":"sub","q":"<p>Реши уравнение заменой t = x².</p><ol class=\"subq\"><li>x⁴ − 5x² + 4 = 0</li><li>x⁴ − 13x² + 36 = 0</li><li>x⁴ − 17x² + 16 = 0</li></ol>","subs":[{"k":"set","v":["−2","−1","1","2"],"show":"−2, −1, 1, 2"},{"k":"set","v":["−3","−2","2","3"],"show":"−3, −2, 2, 3"},{"k":"set","v":["−4","−1","1","4"],"show":"−4, −1, 1, 4"}],"sym":"²","h":["Подумай: «После замены t = x² получили t = 4 и t = 9. Чему равен x?»","Каждое найденное t подставляем обратно в t = x². Из x² = 4 получаем −2 и 2, из x² = 9 получаем −3 и 3. Так находим четыре корня исходного уравнения."]},{"n":269,"lab":"12.4","blk":"h","cls":9,"topic":"Биквадратные уравнения","err":"Берёт корень из отрицательного t","type":"sub","q":"<p>Найди x, если t = x² и даны возможные значения t.</p><ol class=\"subq\"><li>t = −1 или 4</li><li>t = −4 или 0</li><li>t = −9 или −1</li></ol>","subs":[{"k":"set","v":["−2","2"],"show":"−2 и 2"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"}],"sym":"²","h":["Подумай: «Если t = x², какие из значений t = −1 и t = 9 подходят?»","Квадрат действительного числа неотрицателен. Уравнение x² = −1 решений не имеет. Из x² = 9 получаем два числа: −3 и 3. Если t = 0, то x = 0."]},{"n":270,"lab":"14.3","blk":"h","cls":9,"topic":"Метод координат","err":"Складывает координаты при поиске расстояния","type":"sub","q":"<p>Найди расстояние между точками.</p><ol class=\"subq\"><li>(1; 1) и (4; 5)</li><li>(−2; 3) и (4; 11)</li><li>(−1; 4) и (−1; −3)</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"7","var":[],"show":"7"}],"sym":"","h":["Подумай: «Как найти длину отрезка между A(1; 2) и B(4; 6)?»","По горизонтали от A до B нужно пройти 4 − 1 = 3 единицы. По вертикали 6 − 2 = 4 единицы. Это катеты. Длина AB равна 5 по теореме Пифагора."]},{"n":271,"lab":"14.4","blk":"h","cls":9,"topic":"Метод координат","err":"Делит пополам только одну координату","type":"sub","q":"<p>Найди координаты середины отрезка.</p><ol class=\"subq\"><li>(0; 2) и (6; 8)</li><li>(−4; 1) и (2; 7)</li><li>(−3; 5) и (3; −1)</li></ol>","subs":[{"k":"t","v":["(3; 5)","3; 5"],"show":"(3; 5)"},{"k":"t","v":["(−1; 4)","−1; 4"],"show":"(−1; 4)"},{"k":"t","v":["(0; 2)","0; 2"],"show":"(0; 2)"}],"sym":"","h":["Подумай: «Где середина отрезка с концами A(2; 2) и B(8; 6)?»","По оси x середина между 2 и 8 равна 5. По оси y середина между 2 и 6 равна 4. Находим среднее арифметическое отдельно для каждой оси."]},{"n":272,"lab":"19.3","blk":"h","cls":9,"topic":"Координаты векторов","err":"Вычитает координаты конца из координат начала","type":"sub","q":"<p>Найди координаты вектора AB.</p><ol class=\"subq\"><li>A(2; 1), B(5; 3)</li><li>A(−1; 4), B(2; 0)</li><li>A(3; 5), B(1; 5)</li></ol>","subs":[{"k":"t","v":["(3; 2)","3; 2"],"show":"(3; 2)"},{"k":"t","v":["(3; −4)","3; −4"],"show":"(3; −4)"},{"k":"t","v":["(−2; 0)","−2; 0"],"show":"(−2; 0)"}],"sym":"","h":["Подумай: «Найди координаты вектора AB: A(1; 2), B(4; 1)».","Координаты вектора показывают, как перейти из A в B. Из координат конца вычитаем координаты начала: по горизонтали 4 − 1 = 3, по вертикали 1 − 2 = −1."]},{"n":273,"lab":"19.4","blk":"h","cls":9,"topic":"Координаты векторов","err":"Складывает все четыре координаты векторов","type":"sub","q":"<p>Сложи векторы.</p><ol class=\"subq\"><li>(1; 2) + (3; 5)</li><li>(−2; 7) + (5; −1)</li><li>(4; −3) + (−4; 2)</li></ol>","subs":[{"k":"t","v":["(4; 7)","4; 7"],"show":"(4; 7)"},{"k":"t","v":["(3; 6)","3; 6"],"show":"(3; 6)"},{"k":"t","v":["(0; −1)","0; −1"],"show":"(0; −1)"}],"sym":"","h":["Подумай: «Как сложить векторы (2; −1) и (3; 4)?»","Сложение даёт вектор с двумя координатами. Сначала складываем первые координаты, потом вторые. Получаем (2 + 3; −1 + 4) = (5; 3)."]},{"n":274,"lab":"20.5","blk":"h","cls":9,"topic":"Теорема косинусов","err":"Берёт угол напротив известной стороны","type":"sub","q":"<p>Назови третью сторону по двум сторонам и углу между ними.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"19.0 -4.6 116.6 70.3\" width=\"257\" height=\"155\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M60.0,44.0 L39.0,13.0 M60.0,44.0 L115.0,44.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M39.0,13.0 L115.0,44.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M69.0,44.0 C69.0,40.7 67.2,37.6 64.2,36.0 C61.3,34.5 57.7,34.7 55.0,36.5\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"55.0\" y=\"55.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"28.0\" y=\"12.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"120.0\" y=\"46.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>AB, BC, угол B</li><li>AC, BC, угол C</li><li>AB, AC, угол A</li></ol>","subs":[{"k":"t","v":["AC"],"show":"AC"},{"k":"t","v":["AB"],"show":"AB"},{"k":"t","v":["BC"],"show":"BC"}],"sym":"","h":["Подумай: «Известны AB, AC и угол A. Какую сторону найдём по этим данным?»","Стороны AB и AC образуют угол A. В формуле берём косинус именно этого угла. Сторона, которую ищем, лежит напротив A: это BC."]},{"n":275,"lab":"20.6","blk":"h","cls":9,"topic":"Теорема косинусов","err":"Теряет второй минус при тупом угле","type":"sub","q":"<p>Найди квадрат третьей стороны по двум сторонам и углу между ними.</p><ol class=\"subq\"><li>2 и 3, 120°</li><li>3 и 4, 120°</li><li>4 и 5, 120°</li></ol>","subs":[{"k":"e","v":"19","var":[],"show":"19"},{"k":"e","v":"37","var":[],"show":"37"},{"k":"e","v":"61","var":[],"show":"61"}],"sym":"°","h":["Подумай: «Стороны 3 и 5 образуют угол 120°. Чему равен квадрат третьей?»","Косинус 120° равен минус одной второй. В формуле вычитаем отрицательное число, поэтому прибавляем 15. Квадрат третьей стороны равен 9 + 25 + 15 = 49."]},{"n":276,"lab":"21.4","blk":"h","cls":9,"topic":"Графическое решение уравнений","err":"Пропускает вторую точку пересечения","type":"sub","q":"<p>Реши графически.</p><ol class=\"subq\"><li>x² = 9</li><li>x² = 0</li><li>x² = −1</li></ol>","subs":[{"k":"set","v":["−3","3"],"show":"−3 и 3"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"t","v":["Нет решений","Нет","Нет решений","Решений нет","Нет","Корней нет"],"show":"Нет решений"}],"sym":"²","h":["Подумай: «Сколько решений у x² = 4? Посмотри на пересечения графиков».","На пересечениях графиков y = x² и y = 4 выполняется равенство x² = 4. Здесь две точки: (−2; 4) и (2; 4). Их абсциссы дают два корня уравнения."]},{"n":277,"lab":"22.3","blk":"h","cls":9,"topic":"Скалярное произведение векторов","err":"Записывает произведение векторов как пару","type":"sub","q":"<p>Найди скалярное произведение.</p><ol class=\"subq\"><li>(1; 2) и (3; 4)</li><li>(2; −3) и (4; 2)</li><li>(−2; 5) и (3; 1)</li></ol>","subs":[{"k":"e","v":"11","var":[],"show":"11"},{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"−1","var":[],"show":"−1"}],"sym":"","h":["Подумай: «Найди скалярное произведение векторов (2; 3) и (4; −1)».","Умножаем первые координаты, затем вторые. Складываем произведения. Здесь 2 · 4 + 3 · (−1) = 5. Скалярное произведение — одно число."]},{"n":278,"lab":"22.4","blk":"h","cls":9,"topic":"Скалярное произведение векторов","err":"Ищет равенство координат вместо нуля","type":"sub","q":"<p>Проверь, перпендикулярны ли векторы.</p><ol class=\"subq\"><li>(1; 3) и (3; −1)</li><li>(2; 1) и (2; −1)</li><li>(4; 0) и (0; −3)</li></ol>","subs":[{"k":"t","v":["Да"],"show":"Да"},{"k":"t","v":["Нет"],"show":"Нет"},{"k":"t","v":["Да"],"show":"Да"}],"sym":"","h":["Подумай: «Перпендикулярны ли ненулевые векторы (2; 1) и (1; −2)?»","Считаем скалярное произведение: 2 · 1 + 1 · (−2) = 0. Если скалярное произведение двух ненулевых векторов равно нулю, векторы перпендикулярны."]},{"n":279,"lab":"23.6","blk":"h","cls":9,"topic":"Длина окружности и дуги","err":"Принимает меру дуги в градусах за её длину","type":"sub","q":"<p>Найди длину дуги по углу и длине окружности C.</p><ol class=\"subq\"><li>90° при C = 40 см</li><li>120° при C = 30 см</li><li>60° при C = 48 см</li></ol>","subs":[{"k":"e","v":"10","var":[],"show":"10 см"},{"k":"e","v":"10","var":[],"show":"10 см"},{"k":"e","v":"8","var":[],"show":"8 см"}],"sym":"°","h":["Подумай: «Длина окружности 24 см. Какова длина дуги в 90°?»","Полная окружность соответствует 360°. Дуга в 90° занимает четверть окружности. Значит, её длина равна четверти от 24 см, то есть 6 см."]},{"n":280,"lab":"24.5","blk":"h","cls":9,"topic":"Теорема синусов","err":"Ставит рядом сторону и прилежащий угол","type":"sub","q":"<p>Запиши знаменатель в теореме синусов.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"15.0 -11.6 127.6 70.3\" width=\"281\" height=\"155\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M72.0,11.0 L35.0,46.0 M72.0,11.0 L123.0,46.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M35.0,46.0 L123.0,46.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"66.0\" y=\"5.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"24.0\" y=\"48.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"127.0\" y=\"48.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>Сторона AB</li><li>Сторона AC</li><li>Сторона BC</li></ol>","subs":[{"k":"t","v":["sin C"],"show":"sin C"},{"k":"t","v":["sin B"],"show":"sin B"},{"k":"t","v":["sin A"],"show":"sin A"}],"sym":"","h":["Подумай: «В треугольнике ABC синус какого угла пишем под стороной BC?»","В теореме синусов каждой стороне соответствует противолежащий угол. Сторона BC лежит напротив A. Поэтому делим BC на sin A."]},{"n":281,"lab":"24.6","blk":"h","cls":9,"topic":"Теорема синусов","err":"Переворачивает отношение синусов","type":"sub","q":"<p>Найди сторону b. В каждом пункте даны a, A и B по порядку.</p><ol class=\"subq\"><li>4, 30°, 60°</li><li>8, 90°, 30°</li><li>5, 45°, 45°</li></ol>","subs":[{"k":"e","v":"4√3","var":[],"show":"4√3"},{"k":"e","v":"4","var":[],"show":"4"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"√°","h":["Подумай: «a = 6, A = 30°, B = 60°. Как найти сторону b?»","Пишем равенство отношений: a к sin A равно b к sin B. Умножаем обе части на sin B. Значит, b равно a, умноженному на sin B и делённому на sin A."]},{"n":282,"lab":"28.5","blk":"h","cls":9,"topic":"Площадь сектора","err":"Берёт полный круг вместо сектора","type":"sub","q":"<p>Найди площадь сектора.</p><ol class=\"subq\"><li>r = 4 см, угол 90°</li><li>r = 6 см, угол 60°</li><li>r = 9 см, угол 120°</li></ol>","subs":[{"k":"e","v":"4π","var":[],"show":"4π см²"},{"k":"e","v":"6π","var":[],"show":"6π см²"},{"k":"e","v":"27π","var":[],"show":"27π см²"}],"sym":"π²°","h":["Подумай: «Радиус 6 см, угол сектора 90°. Чему равна площадь сектора?»","Полный круг соответствует 360°. Угол 90° составляет четверть полного угла. Берём четверть площади круга. Получаем 36π : 4 = 9π см²."]},{"n":283,"lab":"28.6","blk":"h","cls":9,"topic":"Площадь сектора","err":"Применяет формулу длины дуги для площади","type":"sub","q":"<p>Найди площадь сектора.</p><ol class=\"subq\"><li>r = 8 см, угол 90°</li><li>r = 5 см, угол 180°</li><li>r = 12 см, угол 60°</li></ol>","subs":[{"k":"e","v":"16π","var":[],"show":"16π см²"},{"k":"e","v":"12,5π","var":[],"show":"12,5π см²"},{"k":"e","v":"24π","var":[],"show":"24π см²"}],"sym":"π²°","h":["Подумай: «Для сектора с r = 3 см и углом 120° какую формулу берём?»","Площадь сектора измеряем в квадратных единицах. Берём долю от площади круга πr². При угле 120° это треть: 9π : 3 = 3π см²."]},{"n":284,"lab":"30.3","blk":"h","cls":9,"topic":"Кусочно заданные функции","err":"Считает выколотую точку частью графика","type":"sub","q":"<p>Найди значение функции по высотам двух точек.</p><ol class=\"subq\"><li>Пустая 2, закр. 5</li><li>Пустая −1, закр. 0</li><li>Пустая 4, закр. −3</li></ol>","subs":[{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"−3","var":[],"show":"−3"}],"sym":"","h":["Подумай: «При x = 2 пустая точка на высоте 1, закрашенная на 3. Чему равно f(2)?»","Выколотая точка показывает, что соответствующая ветвь не включает этот конец. Закрашенная точка входит в график. При x = 2 берём её ординату: f(2) = 3."]},{"n":285,"lab":"30.4","blk":"h","cls":9,"topic":"Кусочно заданные функции","err":"Подставляет границу в обе формулы","type":"sub","q":"<p>Найди значения по формулам из примера.</p><ol class=\"subq\"><li>f(−1)</li><li>f(1)</li><li>f(3)</li></ol>","subs":[{"k":"e","v":"0","var":[],"show":"0"},{"k":"e","v":"2","var":[],"show":"2"},{"k":"e","v":"6","var":[],"show":"6"}],"sym":"","h":["Подумай: «f(x) = x + 1 при x &lt; 2, а f(x) = 2x при x ≥ 2. Чему равно f(2)?»","Сначала проверяем условия при x = 2. Условие x &lt; 2 не выполняется. Условие x ≥ 2 выполняется. Берём вторую формулу: f(2) = 2 · 2 = 4."]},{"n":286,"lab":"31.3","blk":"h","cls":9,"topic":"Квадратные неравенства","err":"Записывает только корни вместо промежутка","type":"sub","q":"<p>Реши неравенство.</p><ol class=\"subq\"><li>x² − 9 &lt; 0</li><li>x² − 16 &lt; 0</li><li>x² − 25 &lt; 0</li></ol>","subs":[{"k":"t","v":["(−3; 3)","−3; 3"],"show":"(−3; 3)"},{"k":"t","v":["(−4; 4)","−4; 4"],"show":"(−4; 4)"},{"k":"t","v":["(−5; 5)","−5; 5"],"show":"(−5; 5)"}],"sym":"²","h":["Подумай: «Реши x² − 4 &lt; 0. Проверь числа −2, 0 и 2».","Парабола y = x² − 4 пересекает ось x в точках с x = −2 и x = 2. Между ними график ниже оси. Например, при x = 0 получаем −4. Ищем все x между корнями. Границы исключаем."]},{"n":287,"lab":"31.4","blk":"h","cls":9,"topic":"Квадратные неравенства","err":"Включает границы при строгом знаке","type":"sub","q":"<p>Реши неравенство.</p><ol class=\"subq\"><li>x² − 1 &gt; 0</li><li>x² − 4 ≥ 0</li><li>x² − 16 &gt; 0</li></ol>","subs":[{"k":"t","v":["x < −1 или x > 1",">"],"show":"x < −1 или x > 1"},{"k":"t","v":["x ≤ −2 или x ≥ 2"],"show":"x ≤ −2 или x ≥ 2"},{"k":"t","v":["x < −4 или x > 4",">"],"show":"x < −4 или x > 4"}],"sym":"²≤≥","h":["Подумай: «Подходит ли x = 3 для x² − 9 &gt; 0? А для x² − 9 ≥ 0?»","При x = 3 выражение равно нулю. Ноль подходит для знака ≥, а для строгого знака &gt; границу исключаем. Положительные значения получаются при x &lt; −3 или x &gt; 3."]},{"n":288,"lab":"32.3","blk":"h","cls":9,"topic":"Знак и изменение функции","err":"Путает положительные значения x и y","type":"sub","q":"<p>Определи знак значения функции.</p><ol class=\"subq\"><li>Знак f(0)</li><li>Знак f(2)</li><li>Знак f(4)</li></ol>","subs":[{"k":"t","v":["Отрицательный"],"show":"Отрицательный"},{"k":"t","v":["Ноль"],"show":"Ноль"},{"k":"t","v":["Положительный"],"show":"Положительный"}],"sym":"","h":["Подумай: «На рисунке f(x) = x − 2. При x = 1 аргумент положителен. А f(1)?»","Знак функции определяем по высоте графика. Выше оси x значения положительны, ниже отрицательны. При x = 1 точка ниже оси, поэтому f(1) = −1."]},{"n":289,"lab":"32.4","blk":"h","cls":9,"topic":"Знак и изменение функции","err":"Считает, что ниже оси функция убывает","type":"sub","q":"<p>Скажи, увеличилось или уменьшилось значение при переходе.</p><ol class=\"subq\"><li>−5 → −2</li><li>3 → 1</li><li>−1 → −4</li></ol>","subs":[{"k":"t","v":["Увеличилось"],"show":"Увеличилось"},{"k":"t","v":["Уменьшилось"],"show":"Уменьшилось"},{"k":"t","v":["Уменьшилось"],"show":"Уменьшилось"}],"sym":"","h":["Подумай: «График f(x) = x − 2 на отрезке [0; 1] ниже оси. Он убывает?»","Эта прямая поднимается слева направо. Здесь f(0) = −2, а f(1) = −1. Значение увеличилось. Функция может возрастать, оставаясь отрицательной."]},{"n":290,"lab":"38.5","blk":"h","cls":9,"topic":"Параллельный перенос","err":"Меняет местами шаги вправо и вверх","type":"sub","q":"<p>Найди координаты образа точки.</p><ol class=\"subq\"><li>(0; 2), сдвиг (3; 1)</li><li>(2; 0), сдвиг (1; 4)</li><li>(−2; 1), сдвиг (4; 2)</li></ol>","subs":[{"k":"t","v":["(3; 3)","3; 3"],"show":"(3; 3)"},{"k":"t","v":["(3; 4)","3; 4"],"show":"(3; 4)"},{"k":"t","v":["(2; 3)","2; 3"],"show":"(2; 3)"}],"sym":"","h":["Подумай: «Перенос задан вектором (3; 1). Куда перейдёт точка (1; 1)?»","Первая координата вектора задаёт горизонтальный сдвиг. Вторая задаёт вертикальный сдвиг. Идём на 3 вправо и на 1 вверх. Получаем (1 + 3; 1 + 1) = (4; 2)."]},{"n":291,"lab":"38.6","blk":"h","cls":9,"topic":"Параллельный перенос","err":"Принимает координаты новой точки за сдвиг","type":"sub","q":"<p>Найди координаты вектора переноса.</p><ol class=\"subq\"><li>(1; 2) → (4; 5)</li><li>(3; 0) → (1; 4)</li><li>(−2; 3) → (2; 1)</li></ol>","subs":[{"k":"t","v":["(3; 3)","3; 3"],"show":"(3; 3)"},{"k":"t","v":["(−2; 4)","−2; 4"],"show":"(−2; 4)"},{"k":"t","v":["(4; −2)","4; −2"],"show":"(4; −2)"}],"sym":"","h":["Подумай: «При переносе A(2; 4) перешла в A′(5; 1). Каков вектор переноса?»","Сдвиг показывает, на сколько изменилась каждая координата. Вычитаем координаты исходной точки из координат образа. Получаем (5 − 2; 1 − 4) = (3; −3)."]},{"n":292,"lab":"44.5","blk":"h","cls":9,"topic":"Поворот на координатной плоскости","err":"Поворачивает на 90° в обратную сторону","type":"sub","q":"<p>Поверни точку на 90° против часовой стрелки вокруг O.</p><ol class=\"subq\"><li>(1; 2)</li><li>(3; 0)</li><li>(−2; −1)</li></ol>","subs":[{"k":"t","v":["(−2; 1)","−2; 1"],"show":"(−2; 1)"},{"k":"t","v":["(0; 3)","0; 3"],"show":"(0; 3)"},{"k":"t","v":["(1; −2)","1; −2"],"show":"(1; −2)"}],"sym":"°","h":["Подумай: «Поверни A(2; 1) вокруг O на 90° против часовой стрелки. Где A′?»","Два шага вправо поворачиваются в два шага вверх. Один шаг вверх превращается в один шаг влево. Получаем A′(−1; 2). Для любой точки правило: (x; y) → (−y; x)."]},{"n":293,"lab":"44.6","blk":"h","cls":9,"topic":"Поворот на координатной плоскости","err":"При повороте на 180° меняет один знак","type":"sub","q":"<p>Поверни точку на 180° вокруг O.</p><ol class=\"subq\"><li>(4; 2)</li><li>(−3; 1)</li><li>(0; −5)</li></ol>","subs":[{"k":"t","v":["(−4; −2)","−4; −2"],"show":"(−4; −2)"},{"k":"t","v":["(3; −1)","3; −1"],"show":"(3; −1)"},{"k":"t","v":["(0; 5)","0; 5"],"show":"(0; 5)"}],"sym":"°","h":["Подумай: «Куда перейдёт A(3; −2) при повороте на 180° вокруг O?»","После поворота точки лежат на противоположных лучах из O. Расстояние до O сохраняется, поэтому O — середина AA′. Меняем знаки обеих координат: A′(−3; 2)."]},{"n":294,"lab":"46.5","blk":"h","cls":9,"topic":"Площадь через синус угла","err":"Берёт угол вне пары данных сторон","type":"sub","q":"<p>Назови угол между указанными сторонами.</p><div class=\"figbox\"><svg class=\"fig\" viewBox=\"17.0 -10.6 105.6 69.3\" width=\"232\" height=\"153\" role=\"img\" aria-label=\"Рисунок к заданию\"><path d=\"M102.0,45.0 L77.0,11.0\" stroke=\"#2f5bb5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M37.0,45.0 L102.0,45.0 M37.0,45.0 L77.0,11.0\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M52.0,45.0 C52.0,41.4 50.7,38.0 48.4,35.3\" stroke=\"#dd7a3a\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"26.0\" y=\"48.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">A</text><text x=\"107.0\" y=\"48.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">B</text><text x=\"75.0\" y=\"6.0\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#16231A\">C</text></svg></div><ol class=\"subq\"><li>AB и BC</li><li>AC и BC</li><li>AB и AC</li></ol>","subs":[{"k":"t","v":["∠ABC"],"show":"∠ABC"},{"k":"t","v":["∠ACB"],"show":"∠ACB"},{"k":"t","v":["∠BAC"],"show":"∠BAC"}],"sym":"","h":["Подумай: «Известны AB и AC. Синус какого угла нужен для площади?»","В формуле площади берём две стороны и угол между ними. AB и AC сходятся в вершине A. Поэтому используем синус угла BAC."]},{"n":295,"lab":"46.6","blk":"h","cls":9,"topic":"Площадь через синус угла","err":"При тупом угле считает площадь отрицательной","type":"sub","q":"<p>Найди площадь по двум сторонам и углу между ними.</p><ol class=\"subq\"><li>4 и 6, угол 150°</li><li>8 и 10, угол 150°</li><li>6 и 12, угол 150°</li></ol>","subs":[{"k":"e","v":"6","var":[],"show":"6"},{"k":"e","v":"20","var":[],"show":"20"},{"k":"e","v":"18","var":[],"show":"18"}],"sym":"°","h":["Подумай: «Стороны 6 и 8, угол между ними 150°. Чему равна площадь?»","Синусы углов 150° и 30° равны одной второй. Поэтому берём половину произведения 6 · 8 на одну вторую. Получаем площадь 12 квадратных единиц."]},{"n":296,"lab":"49.2","blk":"h","cls":9,"topic":"Комбинаторика","err":"Дважды считает одну пару при выборе","type":"sub","q":"<p>Найди число способов выбрать двух человек.</p><ol class=\"subq\"><li>Из 3 человек</li><li>Из 5 человек</li><li>Из 6 человек</li></ol>","subs":[{"k":"e","v":"3","var":[],"show":"3"},{"k":"e","v":"10","var":[],"show":"10"},{"k":"e","v":"15","var":[],"show":"15"}],"sym":"","h":["Подумай: «Сколькими способами выбрать двух дежурных из четырёх?»","Сначала получаем 4 · 3 = 12 упорядоченных пар. При выборе дежурных порядок не важен: пара АБ и БА одна. Каждая пара посчитана дважды, поэтому делим на 2."]},{"n":297,"lab":"49.5","blk":"h","cls":9,"topic":"Гомотетия","err":"Прибавляет коэффициент к расстоянию","type":"sub","q":"<p>Найди OA′ при гомотетии с центром O.</p><ol class=\"subq\"><li>OA = 6, k = 2</li><li>OA = 10, k = 0,5</li><li>OA = 3, k = 4</li></ol>","subs":[{"k":"e","v":"12","var":[],"show":"12"},{"k":"e","v":"5","var":[],"show":"5"},{"k":"e","v":"12","var":[],"show":"12"}],"sym":"","h":["Подумай: «При гомотетии с центром O коэффициент равен 3, OA = 4. Найди OA′».","При положительном коэффициенте A′ лежит на луче OA. Расстояние от O умножаем на коэффициент 3. Получаем OA′ = 3 · 4 = 12."]},{"n":298,"lab":"49.6","blk":"h","cls":9,"topic":"Гомотетия","err":"Оставляет образ на том же луче при k < 0","type":"sub","q":"<p>Найди образ точки при k = −2 и центре (0; 0).</p><ol class=\"subq\"><li>(2; 4)</li><li>(−1; 5)</li><li>(3; 0)</li></ol>","subs":[{"k":"t","v":["(−4; −8)","−4; −8"],"show":"(−4; −8)"},{"k":"t","v":["(2; −10)","2; −10"],"show":"(2; −10)"},{"k":"t","v":["(−6; 0)","−6; 0"],"show":"(−6; 0)"}],"sym":"","h":["Подумай: «Гомотетия с центром (0; 0), k = −2. Куда переходит A(3; 1)?»","При отрицательном коэффициенте образ лежит на противоположном луче. Каждую координату умножаем на −2 и получаем A′(−6; −2)."]},{"n":299,"lab":"50.5","blk":"h","cls":9,"topic":"Сумма геометрической прогрессии","err":"Вычитает неверное число при поиске суммы","type":"sub","q":"<p>Найди сумму первых четырёх членов.</p><ol class=\"subq\"><li>b₁ = 2, q = 2</li><li>b₁ = 1, q = 3</li><li>b₁ = 4, q = 2</li></ol>","subs":[{"k":"e","v":"30","var":[],"show":"30"},{"k":"e","v":"40","var":[],"show":"40"},{"k":"e","v":"60","var":[],"show":"60"}],"sym":"","h":["Подумай: «Чему равна сумма 1 + 2 + 4 + 8? Что останется после 2S − S?»","Удвоенная сумма равна 2 + 4 + 8 + 16. Вычитаем исходную сумму. Общие члены сокращаются. Остаётся 16 − 1 = 15."]},{"n":300,"lab":"50.6","blk":"h","cls":9,"topic":"Сумма геометрической прогрессии","err":"Подставляет q = 1 в дробную формулу суммы","type":"sub","q":"<p>Найди сумму первых n членов при q = 1.</p><ol class=\"subq\"><li>b₁ = 3, n = 6</li><li>b₁ = 5, n = 8</li><li>b₁ = 0,5, n = 10</li></ol>","subs":[{"k":"e","v":"18","var":[],"show":"18"},{"k":"e","v":"40","var":[],"show":"40"},{"k":"e","v":"5","var":[],"show":"5"}],"sym":"","h":["Подумай: «Первый член 7, знаменатель q = 1. Чему равна сумма пяти членов?»","При q = 1 все члены равны первому. В дробной формуле возникает деление на q − 1, то есть на ноль. Складываем пять одинаковых чисел: 5 · 7 = 35."]}];
